// Built by /tmp/jss_build/build.js from the real-paper mocks in data-all.js; kept in its own file so a data-all.js rebuild can't drop it.
window.PREVIEW_MOCKS = window.PREVIEW_MOCKS || {};
window.PREVIEW_MOCKS["jss-pyq"] = {"id": "jss-pyq", "title": "JSS PYQ Mock", "fullTitle": "JSS PYQ Mock (90 real past-paper Qs, JSS syllabus)", "sub": "90 questions · JSS's 9 subjects × 10 · untimed", "sectionLabels": {"general": "General Psychology / Theories", "assessment": "Psychological Assessment", "social": "Social Psychology", "personality": "Personality", "physio": "Physiological Psychology", "dev": "Developmental Psychology", "clinical": "Clinical Psychology", "disorders": "Psychiatric Abnormalities / Disorders", "research": "Research Methodology"}, "questions": [{"q": "Gestalt psychology emphasizes :", "options": {"a": "Reinforcement and punishment", "b": "Neurotransmitter balance", "c": "Cognitive distortions", "d": "The whole is greater than the sum of its parts"}, "correct": "d", "section": "general", "explanation": "Gestalt psychology, founded by Wertheimer, Koffka, and Kohler, holds that perceptual experience is organized into wholes that cannot be reduced to the sum of individual sensory elements, captured in the maxim 'the whole is greater than the sum of its parts.' It gave rise to laws of perceptual organization such as proximity, similarity, and closure."}, {"q": "Cronbach's alpha assesses :", "options": {"a": "Validity", "b": "Reliability (internal consistency)", "c": "Variance", "d": "Regression"}, "correct": "b", "section": "assessment", "explanation": "Cronbach's alpha (Lee Cronbach, 1951) is a coefficient of internal consistency reliability, estimating how closely related a set of items are as a group within a scale. Values around 0.70 or higher are conventionally considered acceptable."}, {"q": "Which phenomenon explains decreased effort in groups?", "options": {"a": "Groupthink", "b": "Social loafing", "c": "Bystander effect", "d": "Deindividuation"}, "correct": "b", "section": "social", "explanation": "Social loafing (Latane, Williams & Harkins, 1979) is the reduction in individual effort when people work in a group compared to working alone, because personal accountability is diffused. It was classically demonstrated with rope-pulling and shouting tasks (building on Ringelmann's findings)."}, {"q": "Which of the following describes introversion?", "options": {"a": "Enjoying large social gatherings", "b": "Being talkative and outgoing", "c": "Gaining energy from solitude", "d": "Being aggressive and dominant"}, "correct": "c", "section": "personality", "explanation": "Introversion, as described by Jung and elaborated in Eysenck's and the Big Five trait theories, is characterized by an inward orientation, a preference for solitude, and gaining energy from quiet or solitary activities rather than social stimulation."}, {"q": "Which system includes the brain and spinal cord?", "options": {"a": "Peripheral nervous system", "b": "Autonomic nervous system", "c": "Somatic nervous system", "d": "Central nervous system"}, "correct": "d", "section": "physio", "explanation": "The central nervous system (CNS) consists of the brain and the spinal cord, serving as the primary processing and integration center of the body."}, {"q": "According to Piaget, object permanence develops during :", "options": {"a": "Sensorimotor stage", "b": "Preoperational stage", "c": "Concrete operational stage", "d": "Formal operational stage"}, "correct": "a", "section": "dev", "explanation": "In Piaget's theory, object permanence, the understanding that objects continue to exist when out of sight, is acquired during the sensorimotor stage (birth to about 2 years), typically emerging around 8-12 months. It is a landmark achievement of that stage before the onset of symbolic thought."}, {"q": "Which therapy focuses on changing maladaptive thought patterns?", "options": {"a": "Humanistic therapy", "b": "Cognitive-behavioural therapy (CBT)", "c": "Psychoanalysis", "d": "Play therapy"}, "correct": "b", "section": "clinical", "explanation": "Cognitive-behavioural therapy (Beck, Ellis) targets maladaptive/distorted cognitions and the behaviours that maintain them, using cognitive restructuring to identify and modify dysfunctional automatic thoughts and beliefs. Changing thinking is its defining mechanism of change."}, {"q": "Conversion disorder differs from hypochondriasis in that :", "options": {"a": "Conversion requires delusions, hypochondriasis requires hallucinations", "b": "Conversion involves neurological-like symptoms without organic basis, while hypochondriasis involves fear of having a serious illness", "c": "Conversion involves somatic preoccupation, hypochondriasis does not", "d": "Hypochondriasis is always associated with depression, conversion is not"}, "correct": "b", "section": "disorders", "explanation": "Conversion disorder (functional neurological symptom disorder) presents with pseudoneurological deficits (paralysis, blindness, seizures) incompatible with recognized organic disease, whereas hypochondriasis (illness anxiety disorder in DSM-5) is defined by preoccupation with and fear of having a serious illness. This is the core phenomenological distinction under both ICD-10 (F44 vs F45.2) and DSM classifications."}, {"q": "A researcher finds a correlation of r = -0.85 between stress and sleep quality. This indicates :", "options": {"a": "A weak negative relationship", "b": "A strong positive relationship", "c": "A strong negative relationship", "d": "No relationship"}, "correct": "c", "section": "research", "explanation": "A correlation of r = -0.85 is close to -1, indicating a strong inverse (negative) relationship: as stress increases, sleep quality decreases. The magnitude (0.85) reflects strength and the sign reflects direction."}, {"q": "Who among the following has defined perception as a complex of sensory and imaginal events?", "options": {"a": "Kimbel", "b": "Titchener", "c": "Bruner", "d": "Schafer"}, "correct": "b", "section": "general", "explanation": "Edward Titchener defined perception as a complex of sensory and imaginal elements, making b correct. Titchener was the leading proponent of structuralism, the school he brought to America from Wundt's Leipzig laboratory. Structuralism sought to analyse conscious experience into its most basic elements, much as chemistry breaks matter into atoms, using the method of introspection in which trained observers reported the elementary contents of their minds under controlled stimulation. For Titchener the three irreducible elements of mind were sensations, images, and affections, each describable by attributes such as quality, intensity, duration, and clarity. Within this framework a perception is not a simple sensation but a compound, a complex built from sensory elements together with the imaginal residues of past experience that give the present experience its meaning. That is exactly why his definition speaks of a complex of sensory and imaginal events. Structuralism eventually collapsed because introspection proved unreliable and the approach could not study children, animals, or the abnormal, but Titchener's elementalist definitions remain frequent exam content. The phrasing sensory and imaginal is the signature of Titchener's structuralist account of perception."}, {"q": "Which personality assessment tool uses inkblots to assess thought processes?", "options": {"a": "MMPI", "b": "Thematic Apperception Test (TAT)", "c": "Rorschach Test", "d": "Myers-Briggs Type Indicator (MBTI)"}, "correct": "c", "section": "assessment", "explanation": "The Rorschach test, option c, uses inkblots to assess thought processes and personality. Created by the Swiss psychiatrist Hermann Rorschach in 1921, it consists of ten standardised, symmetrical inkblots, some achromatic and some with colour, that the examinee is asked to interpret by saying what each blot might be. It is a projective test, based on the projective hypothesis that when confronted with an ambiguous stimulus a person projects unconscious needs, conflicts, and ways of organising experience onto it. The clinician records responses and then codes them on dimensions such as location, whether the whole blot or a detail was used, determinants like form, colour, movement, and shading, and the content and quality of the response. The most rigorous modern scoring system is John Exner's Comprehensive System, which aimed to put interpretation on an empirical footing. The Rorschach is used to examine thought organisation, reality testing, emotional functioning, and the presence of disordered thinking, which makes it especially relevant when assessing thought processes. Its psychometric validity is debated, but its identity as the inkblot test is unambiguous, so option c is correct."}, {"q": "What does ‘groupthink’ refer to in social psychology?", "options": {"a": "Individual thinking", "b": "Collective decision-making that discourages dissent", "c": "Brainstorming", "d": "Peer pressure"}, "correct": "b", "section": "social", "explanation": "Groupthink, the correct answer b, is the mode of thinking that occurs when the drive for consensus in a cohesive group overrides realistic appraisal of alternatives, so dissent is suppressed and bad decisions result. The concept was introduced by Irving Janis in 1972 after he analysed foreign-policy fiascoes such as the Bay of Pigs invasion. Janis identified antecedent conditions: high cohesiveness, insulation from outside opinion, directive leadership, and high stress with low hope of a better solution than the leader's. These produce symptoms including an illusion of invulnerability, collective rationalisation, belief in the group's inherent morality, stereotyping of out-groups, direct pressure on dissenters, self-censorship, a shared illusion of unanimity, and self-appointed mindguards who shield the group from troubling information. The consequences are incomplete survey of alternatives, failure to examine risks, and poor contingency planning. Janis proposed remedies such as appointing a devil's advocate, inviting outside experts, and the leader withholding his preference. The defining feature for exams is that the cost of cohesion is the discouragement of dissent and critical evaluation, which is precisely what option b states."}, {"q": "Which of the following personality types is described as noisy, callous and fond of physical activity?", "options": {"a": "Endomorph", "b": "Ectomorph", "c": "Mesomorph", "d": "None of the above"}, "correct": "c", "section": "personality", "explanation": "The mesomorph, option c, is described in Sheldon's constitutional theory as somatotonic: assertive, energetic, noisy, callous, and fond of physical activity and risk. William Sheldon proposed that body build, or somatotype, correlates with temperament. He identified three components present in every person to varying degrees. The endomorph is round and soft with a dominant digestive system and a viscerotonic temperament that is relaxed, sociable, comfort-loving, and food-loving. The mesomorph is muscular and hard-bodied with a dominant musculoskeletal system and a somatotonic temperament that is adventurous, dominant, assertive, physically active, and at times insensitive or callous to others. The ectomorph is thin, fragile, and linear with a dominant nervous system and a cerebrotonic temperament that is restrained, introverted, intellectual, and self-conscious. The theory is largely discredited as a serious account of personality because the correlations Sheldon reported were inflated and the work bordered on physiognomy, but it remains a staple exam item. The cluster of being noisy, tough, and craving physical activity maps directly onto the muscular mesomorph and the somatotonic temperament."}, {"q": "Which part of the brain is primarily associated with cognitive functions such as problem-solving?", "options": {"a": "Occipital lobe", "b": "Frontal lobe", "c": "Temporal lobe", "d": "Parietal lobe"}, "correct": "b", "section": "physio", "explanation": "The frontal lobe is the seat of higher cognitive functions including problem-solving, planning, reasoning, working memory, and judgement, so b is correct. The frontal lobe is the largest of the four cerebral lobes and its most anterior portion, the prefrontal cortex, is what most distinguishes the human brain. The prefrontal cortex orchestrates executive functions: setting goals, holding information online, inhibiting inappropriate responses, shifting between rules, and weighing consequences. Just behind it sits the primary motor cortex along the precentral gyrus, which initiates voluntary movement, and Broca's area in the left frontal lobe, which governs speech production. The classic case of Phineas Gage, whose personality and decision-making were devastated after an iron rod destroyed his frontal cortex while sparing basic abilities, dramatised that this region underlies social judgement and self-control. Clinically, frontal damage produces dysexecutive syndrome with poor planning, perseveration, disinhibition, and apathy, and the frontal lobes are implicated in disorders such as ADHD and schizophrenia. The other lobes specialise elsewhere, so when a question pairs cognition, reasoning, or problem-solving with brain location, the frontal lobe is the answer."}, {"q": "Which psychologist proposed the concept of the ‘zone of proximal development’?", "options": {"a": "Jean Piaget", "b": "Erik Erikson", "c": "Lev Vygotsky", "d": "Sigmund Freud"}, "correct": "c", "section": "dev", "explanation": "Lev Vygotsky proposed the zone of proximal development, option c. Vygotsky was a Russian psychologist whose sociocultural theory emphasised that cognitive development is fundamentally social, mediated by language and culture and arising through interaction with more knowledgeable others. The zone of proximal development, or ZPD, is the gap between what a learner can do independently and what they can achieve with guidance from a more capable partner such as a teacher, parent, or skilled peer. Learning is most effective when it targets this zone, just beyond the learner's current independent ability. The supportive guidance that helps the learner cross the ZPD is often called scaffolding, a term coined by Bruner inspired by Vygotsky's ideas, where assistance is provided then gradually withdrawn as competence grows. Vygotsky also stressed the role of private speech and of cultural tools, and he argued that social interaction precedes and drives internal development, captured in his claim that every function appears first on the social plane and then on the psychological plane. This contrasts with Piaget's more individual, discovery-based account. The exam cue ZPD points unmistakably to Vygotsky."}, {"q": "Match List I with List II LIST I (Psychologist) LIST 2 (Theory) A. Dollard and Miller 1. Radical Behaviorism B. Skinner 2. Self-Actualization C. Bandura and Walters 3. Early Social Learning D. Maslow 4. Later Social Learning", "options": {"a": "A-1, B-2, C-3, D-4", "b": "A-3, B-1, C-4, D-2", "c": "A-2, B-1, C-3, D-4", "d": "A-3, B-2, C-4, D-1"}, "correct": "b", "section": "clinical", "explanation": "The correct matching is A-3, B-1, C-4, D-2, option b. Dollard and Miller produced the early social learning theory by translating Freudian concepts into the language of Hullian learning theory in their 1950 work, so they pair with early social learning. B.F. Skinner is the founder of radical behaviourism, the position that even private events like thoughts and feelings are behaviour governed by environmental contingencies and that mental causes are unnecessary, so he pairs with radical behaviourism. Bandura and Walters advanced the later, more cognitive social learning theory, emphasising observational learning, modelling, and vicarious reinforcement that went beyond simple stimulus-response accounts, so they pair with later social learning. Abraham Maslow, a founder of humanistic psychology, is identified with self-actualization, the drive to fulfil one's potential at the apex of his hierarchy of needs, so he pairs with self-actualization. The conceptual through-line is the evolution of learning theory: Dollard and Miller bridged psychoanalysis and behaviourism (John B. Watson, 1913), Skinner radicalised behaviourism, Bandura cognitised it into social-cognitive theory, while Maslow stood apart in the humanistic camp. Mapping each name to its correct school yields b."}, {"q": "Which disorder is characterised by persistent sadness and loss of interest?", "options": {"a": "Schizophrenia", "b": "Depression", "c": "OCD", "d": "Bipolar-disorder"}, "correct": "b", "section": "disorders", "explanation": "Persistent sadness combined with a loss of interest or pleasure is the hallmark of depression, making b correct. In DSM-5 terms, major depressive disorder requires at least five symptoms over a two-week period, and crucially at least one of them must be either depressed mood or anhedonia, the loss of interest or pleasure in nearly all activities. The remaining symptoms span the neurovegetative and cognitive domains: significant weight or appetite change, insomnia or hypersomnia, psychomotor agitation or retardation, fatigue, feelings of worthlessness or excessive guilt, diminished concentration, and recurrent thoughts of death or suicide. The two cardinal symptoms, low mood and anhedonia, are what the question is pointing to. Depression is among the most common mental disorders and a leading cause of disability worldwide. Beck's cognitive model frames it around the negative cognitive triad of negative views of self, world, and future, while biological models emphasise monoamine dysregulation involving serotonin, norepinephrine, and dopamine. Treatments include antidepressants, cognitive-behavioural therapy, and interpersonal therapy. The distinguishing point for Sihan is the combination of pervasive sadness with anhedonia, which separates depression from disorders defined by psychosis, mood cycling, or anxiety."}, {"q": "A graphical representation of correlational data is called a :", "options": {"a": "Bell curve", "b": "Chi square", "c": "Scatterplot", "d": "Skewed distribution"}, "correct": "c", "section": "research", "explanation": "A graphical representation of correlational data is a scatterplot, option c. A scatterplot, also called a scatter diagram, displays each pair of observations as a single point whose horizontal position represents one variable and vertical position represents the other. By plotting all paired scores it reveals the form, direction, and strength of the relationship between two variables at a glance. If points trend upward from lower left to upper right the correlation is positive; if they trend downward it is negative; if they cluster tightly around a line the correlation is strong, and if they scatter widely it is weak; if they show no slope there is little or no linear relationship. The scatterplot also exposes nonlinearity and outliers that a single correlation coefficient would hide, which is why it is the standard visual companion to the Pearson correlation. Correlation, expressed by coefficient r ranging from minus one to plus one, quantifies the linear association but never proves causation. For the exam, the rule is simple: when two continuous variables and their relationship are to be shown visually, the scatterplot is the chart, making option c correct."}, {"q": "The visible spectrum wavelength ranges from", "options": {"a": "380 to 760 nanometres", "b": "200 to 700 nanometres", "c": "400 to 1000 nanometres", "d": "100 to 1000 nanometres"}, "correct": "a", "section": "general", "explanation": "The correct answer is roughly 380 to 760 nanometres because this is the narrow band of electromagnetic radiation that the human eye can actually detect and convert into neural signals. Light is one form of electromagnetic energy, and the full spectrum runs from very short gamma and X rays through ultraviolet, then the visible band, then infrared, microwaves and radio waves. What makes the visible band special is purely biological: the photopigments in our rods and cones, especially the three cone opsins, absorb photons only within this range, so wavelengths outside it never trigger a visual response. Wavelength maps onto the experience of colour. The short end near 380 to 400 nm is seen as violet and blue, the middle around 500 to 565 nm as green and yellow, and the long end near 700 to 760 nm as red. Below 380 nm lies ultraviolet, which carries enough energy to damage tissue but is filtered by the cornea and lens, and above 760 nm lies infrared, which we feel as heat rather than see. Different texts quote slightly different cut offs, often 400 to 700 nm, but the classic psychophysics figure given in introductory psychology is 380 to 760 nm, so that is the keyed answer. The key idea to carry into the exam is that vision is a transduction process limited by the absorption properties of our photoreceptors, not by the physics of light itself."}, {"q": "Confabulatory responses on Rorschach Psychodiagnostics are indicative of:", "options": {"a": "Impairment in reality testing", "b": "Extreme lack of empathy", "c": "Regressed ego", "d": "Cognitive immaturity"}, "correct": "a", "section": "assessment", "explanation": "Confabulatory responses on the Rorschach indicate impairment in reality testing, so the answer is a. The Rorschach inkblot test is a projective assessment in which the examinee reports what they see in ambiguous blots, and the way they perceive and organise the stimulus reveals their thought processes and contact with reality. A confabulation (often scored DW or as a confabulatory response) occurs when the person uses a small, isolated detail of the blot to justify a global response about the whole area, overgeneralising from a fragment to an unjustified whole, for example seeing a tiny claw and therefore declaring the entire blot a monstrous crab. This kind of response reflects a loosening of the perceptual and logical link between what is actually on the card and the percept reported; the conclusion is not adequately grounded in the stimulus. Because reality testing is precisely the capacity to keep perceptions and inferences anchored to external reality and to distinguish internal impressions from objective fact, confabulatory responses, in which inference runs ahead of the perceptual evidence, signal impaired reality testing and are associated with psychotic level thought disturbance. The exam discriminator is recognising that confabulation on the Rorschach is a sign of a thought disorder and faulty reality contact, rather than a marker of empathy, ego regression, or mere cognitive immaturity."}, {"q": "A state that occurs when bystanders in an emergency situation use the behaviour of others to determine whether help is actually required is called:", "options": {"a": "Pluralistic ignorance", "b": "Group conformity", "c": "Group compliance", "d": "Crowd behavior"}, "correct": "a", "section": "social", "explanation": "When bystanders read others' behaviour to decide whether help is needed, the resulting state is pluralistic ignorance, so the answer is a. Pluralistic ignorance is a social psychological phenomenon in which each member of a group privately doubts or rejects a norm or interpretation but mistakenly assumes that most others accept it, because everyone is publicly conforming while privately uncertain. In an ambiguous emergency, each bystander glances at the calm faces of the others to judge whether the situation is truly serious. Since everyone is doing the same thing and trying not to look panicked, all see a roomful of apparently unconcerned people and each concludes the event must not be an emergency. This is one of the key mechanisms, alongside diffusion of responsibility and audience inhibition, behind the bystander effect documented by Latane and Darley after the Kitty Genovese case. It operates through the broader process of informational social influence, using others as a source of information about reality, but the specific labelled outcome, where everyone wrongly infers no emergency from everyone else's inaction, is pluralistic ignorance. The exam discriminator is the phrase use the behaviour of others to determine whether help is actually required, which is the textbook description of pluralistic ignorance in the bystander intervention sequence."}, {"q": "Who was called the 'French Freud'?", "options": {"a": "Jules Pierre Falret", "b": "Jean-Etienne Esquirol", "c": "Paul Briquet", "d": "Jacques Lacan"}, "correct": "d", "section": "personality", "explanation": "Jacques Lacan was called the French Freud, so the answer is d. Lacan was the most influential French psychoanalyst of the twentieth century, who launched a return to Freud, urging analysts to read Freud's texts closely while reinterpreting psychoanalysis through structural linguistics and structuralism. His famous claims include that the unconscious is structured like a language, and his theory of the three registers, the Imaginary, the Symbolic, and the Real, along with the mirror stage, in which the infant forms an ego by identifying with its unified reflected image, a misrecognition that founds the self. His seminars dominated French intellectual life and shaped psychoanalysis, philosophy, and literary theory, earning him the epithet the French Freud for his stature and his project of renewing Freudian thought in France. For the exam this is a recognition item linking a nickname to a figure, and it usefully anchors Lacan's distinctive reworking of Freud through language and the symbolic order. The discriminating skill is distinguishing Lacan from the nineteenth century French alienists in the other options, Falret, Esquirol, and Briquet, who made important contributions to descriptive psychiatry but were not the structuralist heir to Freud honoured with that nickname."}, {"q": "The twenty-third pair of chromosomes is missing an X, turning into a syndrome characterised by a short, infertile female:", "options": {"a": "Down Syndrome", "b": "Asperger's Syndrome", "c": "Turner's Syndrome", "d": "Klinefelter's Syndrome"}, "correct": "c", "section": "physio", "explanation": "The answer is Turner's syndrome. Humans normally carry 23 pairs of chromosomes, and the twenty third pair determines sex, XX in females and XY in males. Turner syndrome arises when a female is missing all or part of one X chromosome, giving the karyotype 45,X (a single X with no second sex chromosome). The phenotype the question describes, a short, infertile female, is the hallmark: affected girls show short stature, gonadal dysgenesis with non functioning streak ovaries leading to infertility and absent or incomplete puberty, a webbed neck, low hairline, broad chest, and often cardiac and renal anomalies. Cognitively, intelligence is usually in the normal range, but there is a characteristic profile of relatively weak visuospatial and arithmetic ability with preserved verbal skills. Contrast this with the other sex chromosome conditions to keep them straight: an extra X in a male gives 47,XXY, Klinefelter syndrome, producing tall, often infertile males. The key exam discriminator is the word missing combined with female and short and infertile, which points specifically to the single X, 45,X picture of Turner syndrome. Remembering that Turner is the loss of an X in a female and Klinefelter is the gain of an X in a male prevents the most common mix up on this item."}, {"q": "The fact that people can use later experiences to compensate for earlier deficits is a contradiction of which element of earlier developmental psychology?", "options": {"a": "Critical periods", "b": "Continuity", "c": "Sensitive periods", "d": "Stability"}, "correct": "a", "section": "dev", "explanation": "The answer is critical periods. A critical period is a rigidly bounded window of time during which a particular experience must occur for normal development to proceed; if the window closes without the right input, the capacity is said to be permanently lost and no later experience can fully repair the deficit. The classic example is Konrad Lorenz's imprinting in geese, and Hubel and Wiesel's work on the visual cortex, where depriving a kitten of patterned vision during a fixed early window caused lasting blindness. The very strong claim of the critical period idea is irreversibility. So the observation that humans can use later, enriching experiences to compensate for and partly overcome earlier deprivation directly contradicts the strict critical period notion, because it shows that the door has not slammed shut forever. This evidence is exactly why modern developmental psychology largely replaced the term critical period with the softer concept of a sensitive period, a window during which the organism is especially responsive to certain input but which does not permanently foreclose later learning. The deeper lesson for the exam is the contrast between a deterministic, all or nothing view of timing and a probabilistic, plasticity friendly view: brains remain capable of reorganisation, so the capacity for catch up growth and recovery is the empirical fact that undermines the original critical period dogma."}, {"q": "'Healing and Persuasion' is the work of:", "options": {"a": "Alfred Pritz", "b": "Jerome Frank", "c": "Charles Winnicot", "d": "Jeff Klerman"}, "correct": "b", "section": "clinical", "explanation": "The keyed answer is Jerome Frank, the American psychiatrist whose book Persuasion and Healing (first published 1961, the question phrases it as Healing and Persuasion) is one of the most influential analyses of what makes all psychotherapies work. Frank argued that the many competing schools of therapy share common ingredients rather than owing their success to their specific techniques. He proposed that every form of healing, from shamanic ritual to modern psychotherapy, contains four shared features: an emotionally charged, confiding relationship with a helping person; a healing setting that carries social sanction; a rationale or myth that provides a plausible explanation for the patient's distress; and a ritual or procedure that both believe will restore health. The unifying mechanism, in Frank's view, is the remoralization of a demoralized person, the restoration of hope and a sense of mastery. This anticipated what we now call the common factors model of psychotherapy and the placebo or expectancy literature, and it directly informs debates about whether specific techniques outperform the therapeutic alliance. For an entrance exam this is a classic name and book pairing, and the deeper point is that Frank reframed therapy outcome as a question of shared persuasive and relational processes rather than rival doctrines."}, {"q": "False belief which cannot be shaken by reason is termed as:", "options": {"a": "Illusion", "b": "Delusion", "c": "Hallucination", "d": "False memory"}, "correct": "b", "section": "disorders", "explanation": "A false belief that cannot be shaken by reason is a delusion, so the answer is b. A delusion is a fixed, false belief held with absolute conviction, out of keeping with the person's social, cultural, and educational background, and not amenable to correction by logical argument or contradictory evidence. It is a disorder of thought content, in contrast to disorders of thought form or stream. The defining features for the exam are three: the belief is false, it is firmly held despite proof to the contrary, and it is not a shared cultural or religious belief. Delusions come in recognisable types, including persecutory (being plotted against), grandiose (inflated worth or power), delusion of reference (neutral events are personally significant), nihilistic, somatic, and delusions of control, and they are a hallmark of psychotic disorders such as schizophrenia and delusional disorder, though they can occur in mood disorders and organic states too. The crucial discriminator in this question is the phrase cannot be shaken by reason, which captures the imperviousness to argument that distinguishes a delusion from a mere mistaken idea or an overvalued idea. It is also important to separate a delusion, a disorder of belief, from an illusion or hallucination, which are disorders of perception."}, {"q": "A body of prior work related to a research problem is referred to as:", "options": {"a": "Archive", "b": "Repository", "c": "Literature", "d": "None of the above"}, "correct": "c", "section": "research", "explanation": "The body of prior work related to a research problem is the literature, so the answer is c. In research methodology the literature means the accumulated published scholarship, theories, empirical studies, reviews, and findings that bear on a chosen topic. Surveying it is the literature review, an essential early step in any project. The literature review serves several functions: it establishes what is already known and what remains unknown so the researcher can locate a genuine gap; it prevents needless duplication of work already done; it sharpens the research question and hypotheses; it informs the choice of methods, measures, and design by showing what has worked or failed before; and it provides the theoretical framework that situates the new study within an ongoing scholarly conversation. A good review is critical and synthetic, not a mere list, weighing the quality and convergence of prior evidence. So when a question speaks of the existing body of prior work connected to a research problem, the standard methodological term is the literature. The exam point is to recognise this as basic research vocabulary and to associate it with the literature review as a defined stage of the research process."}, {"q": "The backward digit span test, where participants must repeat a sequence of numbers in reverse order, is primarily used to assess which type of memory system?", "options": {"a": "Long-term memory", "b": "Working memory", "c": "Sensory memory", "d": "Procedural memory"}, "correct": "b", "section": "general", "explanation": "The answer is working memory because the backward digit span forces you not merely to hold information but to actively manipulate it, which is the defining function of working memory. The concept comes from Alan Baddeley and Graham Hitch, who in 1974 replaced the older idea of a single passive short-term store with a multi-component working memory model. In their model the phonological loop temporarily holds verbal and acoustic material (the digits you hear), while a central executive directs attention and performs operations on that held material. Simply repeating digits forward taps mostly the phonological loop's storage capacity, but repeating them backward requires the central executive to hold the string, reverse its order, and output it, which is why backward span is a purer measure of working memory than forward span. This is why clinicians and intelligence tests such as the Wechsler scales include digit span backward as a working memory index. The key exam distinction is manipulation versus passive holding: any task that asks you to transform, reorder, or compute on information you are actively keeping in mind is tapping working memory, not long-term storage, sensory registration, or automatic procedural skills."}, {"q": "In the WAIS-IV (Wechsler Adult Intelligence Scale - Fourth Edition), how many core subtests are there in the Verbal Comprehension Index and the Perceptual Reasoning Index respectively?", "options": {"a": "3 verbal, 4 performance", "b": "3 verbal, 3 performance", "c": "4 verbal, 3 performance", "d": "2 verbal, 4 performance"}, "correct": "b", "section": "assessment", "explanation": "The answer is three verbal and three perceptual because the WAIS-IV, published by Pearson in 2008 and descended from David Wechsler's original adult scale of 1955, organises its subtests into four index scores, two of which are the Verbal Comprehension Index and the Perceptual Reasoning Index. The Verbal Comprehension Index has three core subtests: Similarities (identifying how two concepts are alike), Vocabulary (defining words), and Information (general knowledge questions). The Perceptual Reasoning Index also has three core subtests: Block Design (arranging blocks to match a pattern), Matrix Reasoning (completing a visual pattern), and Visual Puzzles (selecting pieces that reconstruct a shape). Each index additionally has supplemental subtests that can substitute for a spoiled core subtest, but the core count is three and three. Wechsler's key innovation, worth knowing, was replacing the single ratio IQ (William Stern, 1912) with a deviation IQ that compares a person to same-age peers on a scale with a mean of 100 and a standard deviation of 15, and splitting intelligence into separately interpretable domains rather than one global number. The other two WAIS-IV indices are Working Memory and Processing Speed. For the exam, simply memorise that both the Verbal Comprehension and Perceptual Reasoning indices rest on three core subtests each."}, {"q": "A \"Sociogram\" is a primary tool used in sociometry to measure:", "options": {"a": "IQ scores of a group", "b": "Social distance and patterns of choice within a group", "c": "Personality traits of a leader", "d": "Economic status of a community"}, "correct": "b", "section": "social", "explanation": "The answer is social distance and patterns of choice within a group because a sociogram is the graphic tool of sociometry, the method developed by Jacob Levy Moreno (also known for founding psychodrama) in the 1930s to study the structure of social relationships in groups. Sociometry works by asking each member of a group a choice question, such as whom they would most like to sit with, work with, or invite to a party, and, sometimes, whom they would least prefer. These stated preferences and rejections are then plotted as a diagram in which each person is a point (a node) and each choice is an arrow (a line) pointing from the chooser to the chosen. Reading the resulting sociogram reveals the informal social structure that formal organisation charts hide: who the 'stars' are (individuals chosen by many), who the isolates or neglectees are (chosen by no one), who forms mutually chosen pairs or cliques, and how socially close or distant members are from one another. It is widely used in classrooms, teams, and therapy groups to understand cohesion, popularity, and rejection. The key idea is that a sociogram measures interpersonal attraction and repulsion, that is, patterns of choice and social distance, not intelligence, individual personality, or economics. That makes option b the correct definition."}, {"q": "In psychoanalytic theory, what term describes the mental representation of psychic energy being invested or attached to a particular object, person, or idea?", "options": {"a": "Libido", "b": "Cathexis", "c": "Fixation", "d": "Sublimation"}, "correct": "b", "section": "personality", "explanation": "The answer is cathexis because in Sigmund Freud's economic model of the mind, cathexis is the specific term for the investment of psychic energy (libido) into a mental representation of an object, person, activity, or idea. Freud borrowed an economic metaphor: the mind has a limited quantity of psychic energy that it can allocate, and when we love, desire, or become preoccupied with something, we are cathecting energy onto it. The German word Freud used was Besetzung (occupation or filling), which his English translator James Strachey rendered with the Greek-derived 'cathexis'. Withdrawing that energy is called decathexis or anticathexis, and Freud used this idea to explain phenomena such as grief, where the painful work of mourning is the slow withdrawal of cathexis from a lost loved one. It is essential to separate the fuel from the act of investing it: libido is the energy, cathexis is the process of directing that energy at a target. This distinguishes it cleanly from fixation, which is energy trapped at a developmental stage, and from sublimation, which is a defence that redirects forbidden impulses into acceptable outlets. When an exam item says 'investment or attachment of psychic energy to an object', the answer is always cathexis."}, {"q": "In Phenylketonuria (PKU), the body fails to convert phenylalanine into which substance due to a deficiency of phenylalanine hydroxylase?", "options": {"a": "Urea", "b": "Tyrosine", "c": "Tryptophan", "d": "Histidine"}, "correct": "b", "section": "physio", "explanation": "The answer is tyrosine because Phenylketonuria is caused by a deficiency of the enzyme phenylalanine hydroxylase, whose normal job is to convert the amino acid phenylalanine into the amino acid tyrosine. PKU is an inherited autosomal recessive metabolic disorder, first described by the Norwegian physician Asbjorn Folling in 1934. When the enzyme is missing or faulty, phenylalanine cannot be broken down, so it accumulates to toxic levels in the blood and brain, while tyrosine becomes deficient. The excess phenylalanine and its abnormal breakdown products (phenylketones) are neurotoxic and, if untreated from birth, cause severe intellectual disability, seizures, and behavioural problems, which is exactly why newborns are screened for PKU with a heel-prick blood test. The tyrosine link matters for psychology because tyrosine is itself the precursor for the catecholamine neurotransmitters dopamine, norepinephrine, and epinephrine, as well as for the pigment melanin, which is why untreated PKU patients often have lighter hair and skin. Treatment is a strict low-phenylalanine diet. For the exam, remember the single reaction: phenylalanine, via phenylalanine hydroxylase, becomes tyrosine, and PKU is what happens when that arrow is broken."}, {"q": "According to Erik Erikson's psychosocial development theory, a child who is 1.5 years old (18 months) would be in which developmental stage?", "options": {"a": "Trust vs. Mistrust", "b": "Autonomy vs. Shame and Doubt", "c": "Initiative vs. Guilt", "d": "Industry vs. Inferiority"}, "correct": "b", "section": "dev", "explanation": "The answer is Autonomy vs. Shame and Doubt because in Erik Erikson's eight-stage theory of psychosocial development this stage spans approximately 18 months to three years, the toddler period, so a child of 18 months is entering it. Erikson, a psychoanalyst who extended Freud's ideas across the entire lifespan rather than stopping in adolescence, proposed that each stage presents a central psychosocial crisis, a tension the person must resolve, and that healthy resolution yields a specific virtue or strength. In the autonomy stage the toddler is developing physical skills such as walking, grasping, feeding, and, importantly, toilet training, and is driven to do things independently and assert their own will. If caregivers encourage and patiently support this budding independence, the child develops autonomy and the virtue of will; if caregivers are overly controlling, critical, or shaming of the child's failed attempts, the child instead develops shame and self-doubt about their abilities. The preceding stage, Trust vs. Mistrust (birth to about 18 months), is where the infant learns whether the world and caregivers are reliable. For the exam, anchor the early ages: 0 to 18 months is trust, 18 months to 3 years is autonomy, so 18 months sits at the boundary that the question maps onto the autonomy stage."}, {"q": "In Dialectical Behavior Therapy (DBT), the \"core mindfulness\" skills are primarily derived from which tradition?", "options": {"a": "Stoicism", "b": "Zen Buddhism", "c": "Psychoanalysis", "d": "Existentialism"}, "correct": "b", "section": "clinical", "explanation": "The answer is Zen Buddhism because Marsha Linehan, the psychologist who developed Dialectical Behavior Therapy in the late 1980s, explicitly drew DBT's core mindfulness skills from Zen Buddhist practice, which she had studied personally. DBT was originally created to treat chronically suicidal patients and people with borderline personality disorder, populations for whom standard cognitive-behavioural therapy alone was insufficient. Its central innovation is the dialectic between acceptance and change: patients need to accept themselves and their present reality (the acceptance pole) while also working to change harmful behaviours (the change pole). Mindfulness supplies the acceptance side and is considered the foundational skill module on which the others rest. From Zen, Linehan took the practices of observing, describing, and participating in the present moment fully, and of doing so non-judgmentally, one-mindfully, and effectively, culminating in the concept of Wise Mind, the balanced integration of the emotional mind and the reasonable mind. It is worth distinguishing the two philosophical lineages that feed modern therapies: cognitive therapy (Beck and Ellis) traces its intellectual roots to Stoic philosophers like Epictetus who argued we are disturbed not by events but by our judgments of them, whereas DBT's mindfulness component traces to Zen Buddhism. So when an exam links DBT mindfulness to a tradition, the answer is Zen Buddhism."}, {"q": "A patient presents with a fixed delusional belief that their spouse is being unfaithful, despite having no evidence. This specific form of delusional jealousy is known as:", "options": {"a": "Capgras syndrome", "b": "Othello syndrome", "c": "Fregoli syndrome", "d": "De Clerambault's syndrome"}, "correct": "b", "section": "disorders", "explanation": "The answer is Othello syndrome because it is the specific name for delusional jealousy, a fixed, unshakeable belief that one's partner is being unfaithful, held with delusional intensity despite the complete absence of real evidence. The name comes from Shakespeare's Othello, who is manipulated into believing his faithful wife Desdemona has betrayed him and murders her out of that jealousy. In psychiatry this is a monothematic delusion, meaning the person can be entirely rational about everything else in life yet holds this one impenetrable false belief. Sufferers often gather 'proof' by checking phones, following the partner, or examining clothing, and the condition carries real forensic risk because morbid jealousy can drive violence. It is important to distinguish it from the three misidentification-type delusions in the options. Capgras (impostor double), Fregoli (one persecutor in many faces), and De Clerambault's erotomania (someone is in love with me) all involve false beliefs about identity or affection, but only Othello centres on infidelity. A useful memory hook: link each eponym to its single sentence, Othello equals jealousy, Capgras equals impostor, Fregoli equals disguise, De Clerambault equals someone loves me, so the exam cue word 'unfaithful spouse' instantly points to Othello."}, {"q": "When data is assumed to be normally distributed and meets the assumptions of equal variances, which category of statistical tests is most appropriate to use?", "options": {"a": "Non-parametric tests", "b": "Parametric tests", "c": "Chi-square tests", "d": "Distribution-free tests"}, "correct": "b", "section": "research", "explanation": "The answer is parametric tests because that entire family of tests rests on specific assumptions about the underlying population, chief among them that the data are drawn from a normal distribution, that the groups being compared have roughly equal variances (homogeneity of variance or homoscedasticity), and that the data are measured at the interval or ratio level. When those conditions are satisfied, parametric tests are preferred because they use the actual numerical values (means and standard deviations) rather than just ranks, which gives them greater statistical power, meaning a better chance of detecting a true effect. The classic parametric tests are the t-test (for comparing one or two means), analysis of variance or ANOVA (for comparing three or more means), and Pearson's correlation coefficient (for the linear relationship between two continuous variables). The logic is that once you can assume normality, you can rely on known mathematical properties of the normal curve to calculate probabilities. The contrasting family, non-parametric or distribution-free tests such as Mann-Whitney U, Wilcoxon, and Kruskal-Wallis, makes no such normality assumption and works with ranks, which you fall back on when data are skewed, ordinal, or the samples are very small. For the exam, the trigger phrase 'normally distributed with equal variances' should immediately signal parametric."}, {"q": "In Baddeley's model of working memory, the subsystem responsible for integrating information from the phonological loop, visuospatial sketchpad, and long-term memory into a single, coherent episode is the:", "options": {"a": "Central Executive", "b": "Episodic Buffer", "c": "Visuospatial Sketchpad", "d": "Phonological Loop"}, "correct": "b", "section": "general", "explanation": "The answer is the episodic buffer, because in Alan Baddeley's model of working memory the episodic buffer is precisely the component whose job is to integrate information from the phonological loop, the visuospatial sketchpad, and long-term memory into a single, coherent, multimodal episode. Understand the model's development. Baddeley and Graham Hitch proposed working memory in 1974 to replace the passive short-term store of the earlier Atkinson-Shiffrin model, arguing that short-term memory is an active workspace with multiple components. The original model had three parts: the central executive, an attention-like controller with limited capacity that directs processing and coordinates the two slave systems; the phonological loop, which holds and rehearses speech-based and acoustic information (its subparts being the phonological store and the articulatory rehearsal process); and the visuospatial sketchpad, which holds and manipulates visual and spatial imagery. A problem became apparent over time: how do we experience a unified scene that binds sound, sight, and stored knowledge together, and where is information held while being combined? To solve this, Baddeley added a fourth component in 2000, the episodic buffer, a limited-capacity system controlled by the central executive that binds information from the two slave systems and from long-term memory into integrated, coherent episodes, acting as a temporary interface. The stem's exact wording, integrating the loop, sketchpad, and long-term memory into a single coherent episode, is the definition of the episodic buffer, so that is the answer, and the key name to attach is Alan Baddeley."}, {"q": "A 10-year-old child from a rural area, with no formal schooling, is brought for an intellectual assessment due to academic struggles. The child is illiterate and has had minimal exposure to formal testing materials. Which of the following tests would be the MOST appropriate to use to minimize cultural and educational bias?", "options": {"a": "Bhatia's Battery of Performance Tests of Intelligence", "b": "Wechsler Intelligence Scale for Children (WISC-IV)", "c": "Stanford-Binet Intelligence Scale (5th ed.)", "d": "Malin's Intelligence Scale for Indian Children (MISIC)"}, "correct": "a", "section": "assessment", "explanation": "The answer is Bhatia's Battery of Performance Tests of Intelligence, because for an illiterate, unschooled child it minimizes cultural and educational bias by relying on nonverbal performance tasks rather than language or academic knowledge. Understand the principle at stake, which is the distinction between verbal and performance (nonverbal) measures of intelligence and the problem of test bias. Any intelligence test that depends on reading, vocabulary, general information, or arithmetic taught in school will systematically underestimate the ability of a child who has had no formal education and cannot read, not because the child is less intelligent but because the test measures acquired schooling rather than underlying reasoning; this is cultural and educational bias, a threat to validity. Performance tests sidestep this by assessing reasoning through hands-on, nonverbal tasks such as assembling blocks, completing patterns, or manipulating objects, which do not require literacy or culturally specific verbal knowledge. Bhatia's battery, developed by C. M. Bhatia in 1955 specifically for the Indian population, is a set of five performance subtests (including Koh's block design, Alexander's pass-along, pattern drawing, immediate memory, and picture construction) designed to be usable with illiterate and rural children by minimizing verbal and educational demands. Because the vignette emphasizes illiteracy, no schooling, and minimal exposure to formal testing, the appropriate choice is the purely performance-based, Indian-standardized Bhatia's battery. The distractors, WISC-IV, Stanford-Binet (Lewis Terman, 1916), and even the Indian MISIC, all include verbal components and presuppose schooling, so they carry more bias, making Bhatia's the best answer."}, {"q": "The \"halo effect\" is a cognitive bias in which:", "options": {"a": "A person's overall impression of another influences ratings of specific traits.", "b": "Individuals take credit for success but blame external factors for failure.", "c": "People overestimate the extent to which others share their opinions.", "d": "A person's initial impression anchors all subsequent judgments."}, "correct": "a", "section": "social", "explanation": "The answer is that a person's overall impression of another influences ratings of specific traits, because that is the precise definition of the halo effect. Understand the concept and its history. The halo effect is a cognitive bias in impression formation, first documented empirically by Edward Thorndike in 1920, who noticed that military officers rating their soldiers tended to rate a soldier who was physically impressive as also more intelligent, loyal, and skilled, as though one good quality cast a halo over all the others. The mechanism is that a single salient global evaluation, often based on one striking attribute such as attractiveness, likeability, or competence, biases our judgments of that person's unrelated specific traits in the same direction. If we find someone physically attractive, we tend to infer they are also kinder, smarter, and more trustworthy, an instance sometimes called the what-is-beautiful-is-good stereotype. The bias runs in the negative direction too, sometimes called the horn effect, where one bad impression drags down ratings of unrelated qualities. The halo effect matters practically because it contaminates job interviews, performance appraisals, and teacher evaluations, undermining the validity of ratings, and it partly explains why structured, criterion-based assessment is preferred over global impressions. The exam signal is any wording about a global or overall impression spreading to influence specific, separate trait judgments, which is exactly option a, distinguishing it from the self-serving bias, false consensus, and anchoring described in the other options."}, {"q": "The \"D-type\" personality, identified as a risk factor for poor prognosis in cardiovascular disease, is characterized by:", "options": {"a": "Hostility and competitiveness.", "b": "The joint tendency to experience negative emotions and to inhibit self-expression in social situations (social inhibition).", "c": "An optimistic and resilient outlook on life.", "d": "Perfectionism and rigidity."}, "correct": "b", "section": "personality", "explanation": "The answer is the joint tendency to experience negative emotions and to inhibit self-expression in social situations, because the Type D or distressed personality is defined precisely by the combination of negative affectivity and social inhibition. Understand the construct and its clinical significance. The Type D personality was introduced by the Belgian psychologist Johan Denollet in the 1990s within the field of health psychology, and the D stands for distressed. It is defined by the co-occurrence of two stable traits. The first is negative affectivity, the tendency to experience negative emotions across time and situations, including worry, irritability, gloom, tension, and a generally dysphoric view of oneself and the world. The second is social inhibition, the tendency to inhibit the expression of these emotions and behaviors in social interactions, out of fear of disapproval or rejection, so the person feels tense, insecure, and reticent around others and keeps their distress bottled up. It is the combination of both, feeling a lot of distress and simultaneously suppressing it socially, that constitutes Type D. Denollet's research showed that Type D personality is an independent predictor of poor prognosis in patients with established cardiovascular disease, associated with higher rates of cardiac events, mortality, and poorer quality of life, likely mediated by chronic stress physiology, poor health behaviors, and reduced help-seeking. It is important to distinguish Type D from the older Type A pattern (Friedman and Rosenman's hostile, competitive, time-urgent pattern) and Type C (the cancer-prone, emotion-suppressing pattern). The defining features of Type D are negative affectivity plus social inhibition."}, {"q": "A patient presents with severe memory deficits, confabulation, and nystagmus, with a history of chronic alcohol use. This clinical picture is classic for:", "options": {"a": "Alzheimer's Disease", "b": "Wernicke-Korsakoff Syndrome", "c": "Vascular Dementia", "d": "Frontotemporal Dementia"}, "correct": "b", "section": "physio", "explanation": "The answer is Wernicke-Korsakoff syndrome, because the combination of severe memory deficits, confabulation, and nystagmus in a chronic drinker is the textbook presentation of thiamine (vitamin B1) deficiency damaging the brain. Learn the mechanism and structure of the disorder. Chronic alcohol use causes thiamine deficiency through poor diet, impaired absorption, and reduced storage, and thiamine is essential for glucose metabolism in neurons, so its lack injures brain regions with high metabolic demand, particularly the mammillary bodies, the medial thalamus (dorsomedial nucleus), and periaqueductal gray. The syndrome has two linked phases. Wernicke's encephalopathy is the acute, potentially reversible emergency defined by a classic triad: confusion (an acute encephalopathy), ataxia (unsteady gait), and ocular abnormalities such as nystagmus and ophthalmoplegia. If untreated with urgent thiamine, it can progress to Korsakoff's psychosis, a chronic, largely irreversible amnestic disorder marked by profound anterograde amnesia, some retrograde amnesia, and confabulation, the unintentional filling of memory gaps with fabricated but plausible material without intent to deceive. The stem's mixture of the eye sign (nystagmus, from the acute Wernicke phase) with memory loss and confabulation (from the chronic Korsakoff phase) is why the combined eponym Wernicke-Korsakoff is correct. The clinical teaching point examiners reward is that thiamine must be given before glucose in a suspected case, and the pathognomonic cue in any vignette is the pairing of an alcohol history with confabulation and eye-movement abnormality."}, {"q": "According to the Thomas and Chess model of temperament, a child who is generally negative in mood, slow to adapt to new situations, and has irregular biological rhythms (e.g., sleep, hunger) would be classified as:", "options": {"a": "Easy Temperament", "b": "Difficult Temperament", "c": "Slow-to-Warm-Up Temperament", "d": "Insecurely Attached"}, "correct": "b", "section": "dev", "explanation": "The answer is difficult temperament, because the trio of features named (negative mood, slow adaptation, and irregular biological rhythms) is the textbook signature of the difficult child in the Thomas and Chess model. Understand the theory from its foundation. Alexander Thomas and Stella Chess launched the New York Longitudinal Study in the 1950s and argued, against the then-dominant view that infants are blank slates shaped only by parenting, that babies show stable, biologically based behavioral styles from birth. They rated infants on nine dimensions, including activity level, rhythmicity (regularity of sleep and hunger), approach or withdrawal to new stimuli, adaptability, intensity of reaction, mood quality, and distractibility. Clustering these, they described three broad types. The easy child (about 40 percent) has regular rhythms, positive mood, and adapts readily. The difficult child (about 10 percent) has irregular rhythms, withdraws from novelty, adapts slowly, reacts intensely, and shows frequent negative mood, exactly the profile in the stem. The slow-to-warm-up child (about 15 percent) is a milder mix, cautious and slow to adapt but with low-intensity reactions rather than stormy negativity, with the rest unclassified. Their most influential idea was goodness of fit: development goes well when parenting matches the child's temperament. The exam clue for difficult temperament is the combination of negative mood plus irregular rhythms plus slow adaptation, and note that attachment categories are a separate framework never to be confused with temperament types."}, {"q": "While on your clinical placement as a trainee, a client discloses that their previous therapist (from a different organization) frequently made inappropriate sexual comments and breached confidentiality. As a trainee psychologist, your FIRST and MOST appropriate course of action should be to:", "options": {"a": "Immediately file a formal police complaint against the previous therapist.", "b": "Confront the previous therapist directly to get their side of the story.", "c": "Discuss the matter with your clinical supervisor to determine the appropriate steps.", "d": "Advise the client to forget the past and focus on the current therapeutic relationship."}, "correct": "c", "section": "clinical", "explanation": "The answer is to discuss the matter with your clinical supervisor, because the universally taught first step in any ethical dilemma faced by a trainee is consultation within the supervisory relationship. Build the reasoning from the structure of ethical decision-making models, such as the one popularized in Kenneth Pope and Melba Vasquez's ethics texts: identify the problem, consult the relevant codes and experienced colleagues, consider the options and their consequences, then act and document. A trainee, by definition, practices under supervision; the supervisor holds clinical and legal responsibility for the trainee's cases, so serious disclosures must flow upward before any external action is taken. Consultation is not passive buck-passing. It protects the client, because the supervisor can help weigh confidentiality against any duty to report; it protects the client's autonomy, because the client's wishes about pursuing a complaint must be explored; and it protects the trainee from well-intentioned but harmful improvisation. The wrong options each break a core principle: going straight to the police may violate confidentiality without consent, confronting the accused therapist personally has no professional standing and could contaminate any future inquiry, and telling the client to forget it commits the worst error of all, invalidating an abuse disclosure. On any exam question that says trainee plus ethical dilemma, the reflex answer is consult the supervisor first."}, {"q": "Expressed Emotion (EE) is a significant predictor of relapse in schizophrenia. Which of the following is NOT one of the three core dimensions of high Expressed Emotion?", "options": {"a": "Hostility", "b": "Critical Comments", "c": "Emotional Over-involvement", "d": "Warmth and Positive Regard"}, "correct": "d", "section": "disorders", "explanation": "The answer is warmth and positive regard, because Expressed Emotion is a construct about negative, over-charged family attitudes, and warmth is not one of its three high-EE dimensions. Learn the concept from its origins: George Brown and colleagues in Britain during the 1960s and 1970s, later refined with the Camberwell Family Interview by Christine Vaughn and Julian Leff, observed that patients with schizophrenia returning to families high in certain emotional attitudes relapsed far more often than those returning to low-EE homes, even controlling for illness severity. Expressed Emotion measures the emotional climate a key relative shows toward the patient, and high EE is defined by three components: critical comments (statements of disapproval or resentment about the patient's behavior), hostility (generalized rejection or blame directed at the person rather than specific behaviors), and emotional over-involvement (overprotectiveness, self-sacrifice, exaggerated emotional responses, and intrusive concern). High EE on any of these predicts relapse and now guides family psychoeducation interventions designed to lower it. Warmth and positive remarks are actually assessed in the interview as separate, generally protective dimensions, so they are the opposite of high EE, which is precisely why they are the correct exception here. The exam hook: high EE equals criticism, hostility, and over-involvement, three negatives; anything positive, like warmth, is never a high-EE dimension."}, {"q": "In a cohort study investigating the association between a new psychological intervention and relapse rates in schizophrenia, the risk ratio is calculated as 1.0. This finding indicates that:", "options": {"a": "The incidence of relapse in the exposed group is double that of the unexposed group.", "b": "The intervention has a significant protective effect against relapse.", "c": "There is no difference in the risk of relapse between the intervention and control groups.", "d": "The odds of exposure are equal in both the relapse and non-relapse groups."}, "correct": "c", "section": "research", "explanation": "The answer is that there is no difference in risk, because a risk ratio, also called relative risk, is a simple division: the incidence of the outcome in the exposed group divided by the incidence in the unexposed group. If relapse occurs in 20 percent of the intervention group and 20 percent of the control group, the calculation is 0.20 divided by 0.20, which equals exactly 1.0. Whenever a ratio of two numbers equals 1, the numerator and denominator must be the same, so a risk ratio of 1.0 is the null value: exposure makes no difference to the outcome. To interpret any risk ratio on an exam, anchor yourself to this benchmark. Values above 1.0 mean the exposure increases risk (a risk ratio of 2.0 means the exposed group has double the risk), and values below 1.0 mean the exposure is protective (0.5 means half the risk). This measure comes from the cohort tradition of epidemiology, where you follow exposed and unexposed groups forward in time and directly measure incidence, which is why the risk ratio is the natural statistic for cohort studies and randomized trials, while case-control studies must instead use the odds ratio because they cannot measure incidence directly."}, {"q": "Functionalism is how people work, play, and adapt to their surroundings. This viewpoint was given by:", "options": {"a": "William James", "b": "William Wundt", "c": "Charles Darwin", "d": "John B. Watson"}, "correct": "a", "section": "general", "explanation": "The answer is William James because functionalism, the school concerned with the purpose and adaptive function of mental processes, is most strongly associated with him in American psychology. To learn this properly, set functionalism against its rival, structuralism. Structuralism, founded by Wilhelm Wundt and carried to America by Edward Titchener, asked WHAT the mind is made of: it tried to break consciousness into its basic elements (sensations, feelings, images) using introspection, much like a chemist analyzing compounds into elements. Functionalism, led by William James (and developed at the University of Chicago by John Dewey and others), rejected that static dissection and asked instead WHY the mind works as it does, what mental processes are FOR, and how consciousness helps an organism adapt to and survive in its environment. This functional, purpose-focused view was heavily influenced by Darwin's theory of evolution and natural selection, since it framed mind and behavior as adaptive tools. James's 1890 textbook Principles of Psychology, with its idea of the stream of consciousness, embodied this approach. The question's phrasing, how people work, play, and adapt to their surroundings, is the functionalist emphasis on adaptation, which points to James. Beware the distractor Wundt: he is the father of experimental psychology and structuralism, not functionalism. Darwin inspired functionalism but was a naturalist, not a psychologist who founded the school. Watson founded behaviorism, which rejected the study of consciousness altogether."}, {"q": "The Wechsler Adult Intelligence Scale can be used to assess eligibility for:", "options": {"a": "Housing benefit", "b": "Disability allowance", "c": "Suicide risk", "d": "Special educational needs"}, "correct": "b", "section": "assessment", "explanation": "The Wechsler Adult Intelligence Scale (WAIS) can be used to help assess eligibility for disability allowance, because establishing intellectual functioning is part of documenting a qualifying disability such as intellectual disability or cognitive impairment. The WAIS, originally developed by David Wechsler (the first version, the Wechsler-Bellevue, appeared in 1939, with the WAIS proper in 1955 and now in its fourth and fifth editions), is the most widely used individually administered adult intelligence test. It yields a Full Scale IQ along with index scores for verbal comprehension, perceptual reasoning, working memory, and processing speed. Because a diagnosis of intellectual disability requires demonstrating significantly subaverage intellectual functioning (roughly an IQ below 70) alongside deficits in adaptive behavior, a standardized IQ measure like the WAIS provides exactly the objective intellectual data that disability determinations require. The question is testing whether the student understands the practical, applied use of intelligence testing in clinical and medico-legal contexts: an IQ score can substantiate a claim for a disability benefit by quantifying cognitive limitation. The other options describe contexts where an adult intelligence test is either irrelevant or the wrong instrument entirely."}, {"q": "In Lewin's topological system, emphasis was placed on the study of 'life space,' which includes:", "options": {"a": "Person and Psychological environment", "b": "Society and group", "c": "Person and group", "d": "Environment and group"}, "correct": "a", "section": "social", "explanation": "The answer is Person and Psychological environment because Kurt Lewin defined the life space as exactly those two interacting elements. Lewin was a Gestalt-influenced social psychologist who created field theory, the idea that behavior must be understood as a function of the whole field of forces acting on a person at a given moment, not of isolated traits or stimuli. His famous formula is B = f(P, E): Behavior is a function of the Person and the Environment, taken together. The life space is his name for the total psychological reality that determines behavior at any instant: it consists of the person (P) plus the psychological environment (E), meaning the environment as it is perceived and experienced by that person, not the objective physical world. Lewin borrowed topology, a branch of mathematics dealing with spatial relationships and boundaries, to represent the life space as regions with boundaries, paths, barriers, and forces (valences) that push and pull the person toward or away from goals. The crucial nuance is that what matters is the psychological environment, the world as it exists for the individual, including their needs, goals, and perceptions, because that is what actually drives behavior. So the two components of the life space are the person and the psychological environment. The other options substitute group and society, which belong to broader social-level analyses, not to Lewin's definition of an individual's life space."}, {"q": "'Id' is to 'Just do it' as superego is to:", "options": {"a": "'Wait till later.'", "b": "'Do your own thing.'", "c": "'Don't do it.'", "d": "'Oh, sit on it.'"}, "correct": "c", "section": "personality", "explanation": "The answer is 'Don't do it.' because the superego is the moralizing, prohibitive agency of Freud's structural model, and a blunt internal command forbidding an impulse is exactly how it operates. Freud's structural theory (introduced in 1923 in The Ego and the Id) divides the mind into three systems. The id is the oldest and most primitive, present from birth, a seething reservoir of instinctual drives (sex and aggression) that runs entirely on the pleasure principle: it wants immediate gratification with no regard for reality, logic, or morality, hence the 'Just do it' framing. The superego develops last, around ages three to five, as the child resolves the Oedipus complex and internalizes the moral standards, rules, and prohibitions of the parents and wider society. It has two parts: the conscience, which punishes violations with guilt and says 'don't,' and the ego ideal, which holds up standards of who we should be. The ego sits between them, operating on the reality principle, mediating the id's demands against the superego's prohibitions and the constraints of the external world. So the analogy maps the id's permissive 'do it' onto the superego's moral veto, 'Don't do it.' This is the most basic way to remember the superego: it is the internalized parental 'no,' the source of guilt and conscience."}, {"q": "Which brain structure would most likely result in death if damaged?", "options": {"a": "Cerebellum", "b": "Medulla", "c": "Reticular formation", "d": "Pons"}, "correct": "b", "section": "physio", "explanation": "The answer is the medulla because it houses the vital reflex centers that keep us alive automatically, and destroying it stops those functions abruptly. The medulla oblongata sits at the very bottom of the brainstem, where the brain joins the spinal cord. To learn this properly, organize the brainstem from bottom to top: medulla, then pons, then midbrain. The medulla contains the cardiac center (regulating heart rate), the respiratory center (driving breathing), and centers for vasomotor control (blood pressure), as well as reflexes like swallowing, coughing, sneezing, and vomiting. Because breathing and heartbeat are fundamentally controlled here and these cannot be consciously sustained if the control center is gone, damage to the medulla typically causes immediate respiratory and cardiac arrest, hence death. This is why brainstem strokes or trauma at this level are so often fatal, and why brainstem function is central to clinical definitions of brain death. Contrast this with structures that, while important, are not immediately life-ending if damaged: the cerebellum governs balance, coordination, and motor learning; damage causes ataxia and clumsiness, not death. The pons relays signals and helps regulate sleep and breathing rhythm, but the actual life-critical respiratory drive resides in the medulla. The reticular formation regulates arousal and consciousness; severe damage can cause coma, but it is the medulla's autonomic centers that most directly equal survival. Anchor the rule: medulla equals automatic life support, so its destruction equals death."}, {"q": "Kohlberg studied moral development by:", "options": {"a": "Having subjects keep a daily journal of their actions", "b": "Evaluating criminal and delinquent persons' court records", "c": "Posing moral dilemmas to children of different ages", "d": "Having subjects perform various legal or illegal behaviours"}, "correct": "c", "section": "dev", "explanation": "Kohlberg studied moral development by posing moral dilemmas to children and adolescents of different ages, which is why c is correct. Lawrence Kohlberg extended Piaget's work on moral judgement by using hypothetical dilemmas, the most famous being the Heinz dilemma, in which a man must decide whether to steal an unaffordable drug to save his dying wife. Crucially, Kohlberg was not interested in whether a person said Heinz should or should not steal the drug; he was interested in the reasoning behind the answer, because the same conclusion could be justified at very different levels of moral sophistication. From the patterns of justification he identified three broad levels, each with two stages. At the preconventional level, morality is based on consequences to the self: stage one is obedience and avoidance of punishment, stage two is instrumental self-interest and simple exchange. At the conventional level, morality rests on social approval and maintaining order: stage three is being a good person in the eyes of others, stage four is upholding law and duty. At the postconventional level, morality is grounded in abstract principles: stage five recognises social contracts and individual rights, stage six rests on universal ethical principles of justice. Kohlberg argued these stages are universal, sequential, and invariant in order. The method was therefore a cross-sectional and interview-based analysis of reasoning, not behaviour tracking, which is the key distinction the question tests."}, {"q": "A parent deliberately ignores a child's temper tantrums in an attempt to discourage them. The parent's strategy is in accordance with:", "options": {"a": "Negative reinforcement", "b": "Extinction", "c": "Operant escape", "d": "Operant avoidance"}, "correct": "c", "section": "clinical", "explanation": "The source key marks this as operant escape, but the textbook-correct concept the question describes is extinction, so learn the concept properly and note the discrepancy. The scenario is a parent deliberately withholding any response (attention) to a behavior (tantrums) that was previously reinforced by that attention, in order to reduce the behavior. In operant conditioning (B. F. Skinner), when a behavior that has been maintained by reinforcement no longer produces that reinforcement, the behavior gradually weakens and disappears. That process is extinction. Crucially, ignoring an attention-seeking behavior is the textbook clinical example of extinction: the tantrum was being reinforced by parental attention, so removing the attention removes the reinforcer and the tantrum should fade (often after a temporary extinction burst). So conceptually the right answer is extinction. The source has marked operant escape (c), which describes something different: escape behavior is negatively reinforced behavior that terminates an aversive stimulus already present (for example, taking aspirin to end a headache). That does not match a parent passively ignoring a child. Because this question's wording maps cleanly onto extinction, you should learn it as an extinction item; if the answer key on the exam credits escape, it is an error in the key. For your understanding, distinguish the four: positive reinforcement adds a pleasant stimulus, negative reinforcement removes an aversive one, both increase behavior; extinction removes the maintaining reinforcer to decrease behavior; escape and avoidance are negative-reinforcement subtypes that increase behavior."}, {"q": "A condition characterised by recurrent intense sexually arousing fantasies and urges involving the use of an inanimate object to obtain sexual gratification:", "options": {"a": "Necrophilia", "b": "Fetishism", "c": "Frotteurism", "d": "Voyeurism"}, "correct": "b", "section": "disorders", "explanation": "The answer is fetishism because it is defined precisely as recurrent, intense sexual arousal from a nonliving (inanimate) object. This question falls under the paraphilic disorders, a class of conditions in which sexual arousal centers on atypical objects, situations, or targets. The defining hallmark of fetishism (fetishistic disorder) is that the focus of arousal is an inanimate object, classically items like shoes, leather, rubber, or undergarments, or in some definitions a specific nonsexual body part, and the person experiences recurrent and intense sexually arousing fantasies, urges, or behaviors involving that object over at least six months, causing distress or impairment. The key diagnostic feature to anchor is the inanimate object. The distractors are other paraphilias, each defined by a DIFFERENT focus, so learning them as a contrasting set is the efficient strategy. Necrophilia is sexual arousal involving corpses (a dead body, not an inanimate object in the fetish sense). Frotteurism is arousal from touching or rubbing against a nonconsenting person, typically in a crowded public place. Voyeurism is arousal from secretly observing an unsuspecting person who is naked, undressing, or engaged in sexual activity. So each paraphilia is distinguished by the specific stimulus or situation that triggers arousal, and the inanimate object is unique to fetishism. Match the trigger to the disorder and these items become straightforward."}, {"q": "In an experiment, the group which receives no treatment is called:", "options": {"a": "Experimental group", "b": "No group", "c": "Control group", "d": "None of these"}, "correct": "c", "section": "research", "explanation": "The answer is control group because in experimental design the control group is the set of participants who do NOT receive the treatment or independent variable manipulation, serving as the baseline against which the treated group is compared. The logic of a true experiment is that you manipulate one variable (the independent variable) while holding everything else constant, then observe its effect on an outcome (the dependent variable). To know whether any observed change was actually caused by the treatment rather than by chance, the passage of time, expectations, or other confounds, you need a comparison condition that is identical in every way except that it lacks the treatment. That comparison condition is the control group. The group that does receive the treatment is the experimental group. By randomly assigning participants to experimental and control groups, the researcher distributes confounding variables evenly, so any difference in outcomes can be attributed to the independent variable, giving the study internal validity. A common refinement is the placebo control, where the control group receives an inert substitute so that expectancy effects are equalized. Understanding this terminology is foundational to reading any research methods question: experimental equals treated, control equals untreated baseline. Hence the group receiving no treatment is, by definition, the control group."}, {"q": "Concept formation stages include the following:", "options": {"a": "Observation, Discrimination, Generalization, Abstraction", "b": "Abstraction, Generalisation, Discrimination, Assimilation", "c": "Observation, Generalisation, Discrimination, Abstraction", "d": "Observation, Assimilation, Generalisation, Discrimination"}, "correct": "a", "section": "general", "explanation": "A concept is a mental category that groups objects, events, or ideas by shared defining features, letting us respond to novel instances without relearning each one. Learning-theory accounts, drawing on Clark Hull's stimulus-response tradition and later elaborated in Indian psychology curricula, describe concept formation as an ordered progression. It begins with Observation, the raw perceptual encounter with many exemplars of the class. Next comes Discrimination, in which the learner detects how these exemplars differ from non-members, sharpening the boundary of the category (learning that a whale is not a fish despite surface similarity). Then Generalization allows the learner to extend the response across all members that share the essential attributes, treating varied instances as equivalent. Finally Abstraction isolates the common defining property itself, stripping away irrelevant surface detail so the concept becomes a portable rule ('mammal' regardless of size or habitat). Option A preserves this Observation to Discrimination to Generalization to Abstraction sequence. The distractors permute the stages or swap in 'assimilation,' a Piagetian term for fitting new input into existing schemas rather than a named concept-formation stage here. Note that different texts word this sequence slightly differently, so it is genuinely debatable, but the observation-first, abstraction-last ordering is the most widely reproduced version and the intended key. (No official key released; answer expert-determined and flagged as debatable.)"}, {"q": "Location in Rorschach Inkblot Test is concerned with", "options": {"a": "Whole/Part", "b": "Fantasy/Emotion", "c": "Colour/Movement", "d": "Figure/Landscape"}, "correct": "a", "section": "assessment", "explanation": "The correct answer is: Whole/Part. In Rorschach scoring, Location codes WHERE in the blot the response was seen: the whole blot (W), a common detail (D), an unusual detail (Dd) or white space (S). So Location is the whole-versus-part dimension. Colour and Movement are Determinants, not Location."}, {"q": "The process of changing your behaviour to match that of others in a group is termed:", "options": {"a": "Norming", "b": "Conformity", "c": "Standardization", "d": "Forming a social contact"}, "correct": "b", "section": "social", "explanation": "The correct answer is conformity. Conformity is the tendency to change one's beliefs or behaviour to align with the standards of a group, even without any direct request to do so. It is one of the central topics of social psychology. People conform for two broad reasons identified by Deutsch and Gerard: normative social influence, the desire to be liked and accepted and to avoid the discomfort of standing out, and informational social influence, the assumption that the group may know better than oneself, especially in ambiguous situations. Solomon Asch's famous line-judgement experiments demonstrated normative conformity, showing that many participants would give an obviously wrong answer about line lengths simply because confederates had done so first. Muzafer Sherif's autokinetic-effect studies showed informational conformity, where individuals converged on a group estimate when the task was genuinely uncertain. Conformity differs from compliance (yielding to a direct request) and obedience (following an order from an authority). The question's phrasing, matching your behaviour to that of others in a group, is essentially the textbook definition of conformity, which is why it is the precise answer."}, {"q": "Cardiovascular diseases are more related to", "options": {"a": "Introverted personality.", "b": "Extroverted personality.", "c": "Type A personality.", "d": "Type B personality."}, "correct": "c", "section": "personality", "explanation": "This question comes from health psychology's study of how personality relates to physical illness. Cardiologists Meyer Friedman and Ray Rosenman, working in the 1950s, noticed that many of their coronary patients shared a distinctive behavioural style, which they labelled the Type A behaviour pattern. Type A individuals are characterised by chronic time-urgency (a constant sense of racing the clock), competitiveness, high achievement striving, impatience, and, importantly, free-floating hostility and easily provoked anger. Their research, including the long-term Western Collaborative Group Study, found that Type A men developed coronary heart disease at roughly twice the rate of their more relaxed counterparts. The proposed mechanism is that persistent hostility and time pressure keep the sympathetic nervous system chronically activated, raising blood pressure, heart rate, and stress hormones such as cortisol and catecholamines, which over time damage the cardiovascular system. Later refinements, notably by Redford Williams, suggested that hostility and anger are the truly toxic core of the pattern rather than ambition itself. Type B, by contrast, describes people who are patient, relaxed, and non-competitive, and who show lower coronary risk. Introversion and extroversion belong to a different framework (Eysenck's and the trait tradition) and are not the established coronary-prone dimension. The intended link here is Friedman and Rosenman's Type A personality with cardiovascular disease."}, {"q": "Which movement disorder is a secondary one?", "options": {"a": "Hungtington's chorea (sic)", "b": "Parkinson's", "c": "Akathisia", "d": "None of these"}, "correct": "c", "section": "physio", "explanation": "Movement disorders are split into primary (idiopathic or genetic, arising from the nervous system itself) and secondary (produced by an identifiable external cause such as medication, toxins, or another illness). Huntington's chorea, first described clinically by George Huntington, is a primary disorder caused by an inherited expansion of the huntingtin gene. Parkinson's disease, named after James Parkinson's 'Essay on the Shaking Palsy,' is a primary neurodegenerative condition marked by loss of dopamine-producing cells in the substantia nigra. Akathisia is different: it is a state of inner restlessness and an inability to stay still that most commonly appears as a side effect of dopamine-blocking drugs, especially antipsychotics (neuroleptics) and some antiemetics. Because it is triggered by an outside agent rather than by an intrinsic disease process, it is classified as a secondary (drug-induced) movement disorder. This distinction matters clinically because secondary disorders are often reversible: reduce or switch the offending medication and the symptoms frequently resolve, whereas primary degenerative disorders progress. Recognising akathisia as iatrogenic also guides management, since patients may be mislabelled as anxious or agitated when the true cause is their prescription. The take-home rule is simple: if an external, removable factor causes the abnormal movement, the disorder is secondary."}, {"q": "The term holophrase means", "options": {"a": "a single word that is used as a sentence.", "b": "the first word a child say when he/she starts speaking.", "c": "the first sentence a child say when he/she starts speaking.", "d": "the first few intelligible words the child speaks."}, "correct": "a", "section": "dev", "explanation": "Holophrase is a term from the study of early language development describing the way very young children, typically around twelve to eighteen months in the one-word or holophrastic stage, use a single word to convey the meaning of an entire sentence. The word 'holophrase' literally combines 'holo' (whole) and 'phrase,' capturing the idea that one word stands in for a complete thought. For example, a toddler saying 'milk' may mean 'I want milk,' 'that is milk,' or 'my milk is gone,' with the intended proposition inferred from context, gesture, and intonation. The concept is central to developmental accounts of how children move from single words toward two-word (telegraphic) speech and then full grammar; observers such as Jean Berko Gleason and researchers in the Piagetian and psycholinguistic traditions have documented this progression, and it aligns with the sequence of milestones described in developmental psychology texts like Elizabeth Hurlock's. The key insight is functional: the child is already communicating whole intentions before mastering syntax, so a single word is doing the work of a sentence. That is why the correct definition emphasises a single word used as a sentence, rather than simply being the first word spoken or a complete grammatical sentence. Recognising holophrastic speech helps caregivers and clinicians gauge whether pragmatic communication is developing normally even before word combinations appear."}, {"q": "Health psychology differs from behavioural medicine primarily in that", "options": {"a": "Health psychology focuses on health promotion and prevention; behavioural medicine integrates behavioural and biomedical interventions", "b": "Health psychology only uses medication", "c": "Behavioural medicine does not consider behaviour", "d": "Health psychology is purely neurological"}, "correct": "a", "section": "clinical", "explanation": "These two fields overlap heavily and are easy to confuse, so it helps to see how each was defined. Health psychology was formally launched when Joseph Matarazzo, first president of the American Psychological Association's Division 38, described it as the discipline's contribution to promoting and maintaining health, preventing and treating illness, and studying the psychological causes and correlates of disease and the health-care system. Its centre of gravity is psychological science applied to health promotion and prevention: understanding attitudes, motivation, stress, coping, and behaviour change. Behavioural medicine, defined at the 1977 Yale Conference, is deliberately interdisciplinary: it integrates behavioural and biomedical knowledge and techniques relevant to health and illness, and it applies them clinically to prevention, diagnosis, treatment, and rehabilitation. In other words, behavioural medicine is a broader tent that includes physicians, nurses, and other clinicians alongside psychologists, and it fuses behavioural interventions directly with medical treatment. So the cleanest way to distinguish them, and the answer here, is that health psychology emphasises the psychological study of health promotion and prevention, whereas behavioural medicine integrates behavioural and biomedical interventions in an applied, clinical, multidisciplinary way. The other options are simply false characterisations: health psychology neither prescribes medication nor confines itself to neurology, and behavioural medicine most certainly does consider behaviour, since behaviour is right there in its name."}, {"q": "Suicidal risk is assessed to be highest when the following criteria are met in comparison to others, the 'time' factor being the same for all—", "options": {"a": "High lethality, specific plan, frequent suicidal ideas, family history", "b": "Disrupted biological functioning, no recent attempt, no suicidal ideation", "c": "Adequate biological functioning, no previous attempt, moderate intent", "d": "Frequent suicidal ideation, recent suicide attempt, low lethality, absence of family history"}, "correct": "a", "section": "disorders", "explanation": "Suicide risk assessment weighs a converging set of empirically validated markers rather than any single sign. Edwin Shneidman, the founder of modern suicidology, emphasized that risk peaks when psychological pain ('psychache') meets means and intent. Clinicians operationalize this through several dimensions: the lethality of the chosen method (a firearm or hanging is far more lethal than superficial cutting), the specificity of the plan (a detailed plan with identified means and time indicates rehearsal and resolve), the frequency and intensity of suicidal ideation, and static risk factors such as a family history of suicide, which carries both genetic and modeling influence. When these load together, high lethality, a concrete plan, persistent ideation, and family history, the probability of a fatal act is greatest. Aaron Beck's work on hopelessness added that pessimism about the future predicts eventual suicide better than depression severity alone. Option A stacks the most dangerous combination, so it is correct. The distractors each remove one or more critical elements: absent ideation, only moderate intent, or low lethality all attenuate acute danger even when other stressors exist. The clinical lesson is that risk is multiplicative, not additive; the deadliest presentation is the patient who has both the will (ideation, intent, history) and the way (a lethal, specific plan)."}, {"q": "Number of existing cases on a specific date out of the total population is called", "options": {"a": "Prevalence", "b": "Periodic prevalence", "c": "Incidence", "d": "Point prevalence"}, "correct": "d", "section": "research", "explanation": "Epidemiology, the study of how disorders distribute across populations, distinguishes two core rate families: prevalence (how many cases exist) and incidence (how many new cases appear). Prevalence itself splits by the window of observation. Point prevalence is a snapshot: the proportion of a population that HAS the disorder on one specified date, cases divided by total population at that instant. Period prevalence widens the lens to a stretch of time (say all cases present at any point during a year), so it captures both those who already had the condition and those who developed it mid-period. Incidence is conceptually different: it counts only the fresh onsets over an interval, indexing risk of getting the disorder rather than the burden of having it. The stem's wording, 'existing cases on a specific date out of the total population,' is the textbook definition of point prevalence, so option D is precise. A useful mnemonic from epidemiologists is the bathtub: incidence is water flowing in from the tap, prevalence is the level of water standing in the tub, and point prevalence is that level measured at one exact second. Recovery and death drain the tub, which is why chronic disorders show high prevalence even with modest incidence."}, {"q": "In cognitive psychology, the 'Stroop effect' primarily demonstrates which cognitive phenomenon?", "options": {"a": "The interference that occurs in reaction time due to conflicting information processing.", "b": "Improved recall when semantically related information is presented.", "c": "The increased accuracy of perception under divided attention tasks.", "d": "The predictive power of schema theory on episodic memory."}, "correct": "a", "section": "general", "explanation": "The Stroop effect, first reported by John Ridley Stroop in 1935, is a classic demonstration of response interference and the automaticity of reading. Participants are shown color words printed in incongruent ink (for example, the word RED printed in blue ink) and asked to name the ink color, not read the word. Reaction times slow markedly and errors rise compared with naming the color of a neutral patch. The dominant explanation is that skilled reading is automatic: the word meaning is processed involuntarily and competes with the slower, controlled task of ink-color naming, producing a processing conflict that must be resolved. This taps selective attention and executive control, and the task is widely used to index the ability to inhibit a prepotent response. Modern accounts tie Stroop performance to the anterior cingulate cortex and prefrontal conflict-monitoring systems. Option a is correct because the defining feature of the effect is the interference (increased reaction time) caused by conflicting streams of information, one automatic and one controlled."}, {"q": "In the context of psychometrics, which of the following best represents 'construct validity'?", "options": {"a": "The degree to which a test measures what it claims to measure.", "b": "The consistency of test scores across repeated administrations.", "c": "The extent to which test content represents the entire domain.", "d": "The agreement between different raters assessing the same performance."}, "correct": "a", "section": "assessment", "explanation": "Construct validity is the extent to which a test actually measures the theoretical construct, the unobservable trait such as intelligence, anxiety, or extraversion, that it is intended to measure. The term and framework were formalized by Lee Cronbach and Paul Meehl in 1955, who argued that a construct is embedded in a nomological network of expected relationships, and evidence for construct validity accumulates as scores behave as theory predicts. It has two complementary strands: convergent validity (the measure correlates with other measures of the same construct) and discriminant validity (it does not correlate with measures of unrelated constructs), a distinction sharpened by Donald Campbell and Donald Fiske through the multitrait-multimethod matrix. Modern testing standards treat construct validity as the overarching, unifying concept under which content and criterion evidence fall. Option a, capturing whether the test measures what it claims to measure, is the standard textbook definition. The distractors describe reliability (b and d) and content validity (c), which are related but distinct psychometric properties."}, {"q": "According to the Theory of Planned Behavior, which of the following factors influences an individual's intention to engage in health behaviors?", "options": {"a": "Attitude, subjective norms and self-efficacy", "b": "Genetics, personality traits and socio-economic status", "c": "Cultural beliefs, social support and health literacy", "d": "Physical environment, emotional intelligence and coping strategies"}, "correct": "a", "section": "social", "explanation": "The correct answer is attitude, subjective norms and self-efficacy. The Theory of Planned Behavior, developed by Icek Ajzen, holds that the strongest predictor of behaviour is a person's intention to perform it, and that intention is in turn shaped by three factors. The first is attitude toward the behaviour, one's favourable or unfavourable evaluation of performing it. The second is subjective norms, the perceived social pressure from important others to perform or not perform the behaviour. The third is perceived behavioural control, the person's belief in their ability to carry out the behaviour, a construct closely related to Albert Bandura's concept of self-efficacy. These three components jointly determine intention, and intention drives behaviour, so option A correctly names them. The Theory of Planned Behavior extended Ajzen and Martin Fishbein's earlier Theory of Reasoned Action by adding perceived behavioural control to account for behaviours not fully under voluntary control. Option B (genetics, personality traits, socio-economic status), option C (cultural beliefs, social support, health literacy), and option D (physical environment, emotional intelligence (Peter Salovey and John Mayer, 1990), coping strategies) all list plausible-sounding influences on health but none matches the three specific constructs of the model. The theory is widely applied in health psychology to predict and change behaviours such as exercise, smoking cessation, and safe practices. (no official key in the paper; answer determined by subject expertise)"}, {"q": "The concept of \"reciprocal determinism\" is central to which personality theory?", "options": {"a": "Psychodynamic theory", "b": "Social cognitive theory", "c": "Humanistic theory", "d": "Biological theory"}, "correct": "b", "section": "personality", "explanation": "The correct answer is Social cognitive theory. Reciprocal determinism is a core concept of the social cognitive theory of personality developed by Albert Bandura. It proposes that human functioning results from the continuous, mutual interaction of three sets of factors: behaviour, personal or cognitive factors (such as beliefs and expectations), and the environment. Each of these influences and is influenced by the others in a triadic, bidirectional loop, so people are neither driven purely by inner forces nor simply shaped by the environment; instead they actively shape and are shaped by their surroundings. This interactive model is why option B is correct. Bandura is also famous for the concept of self-efficacy and for the Bobo doll studies demonstrating observational learning. Psychodynamic theory (option A), founded by Sigmund Freud, explains personality through unconscious conflicts, the id, ego, and superego, and psychosexual stages, not through reciprocal interaction of behaviour and environment. Humanistic theory (option C), advanced by Carl Rogers and Abraham Maslow, stresses free will, self-concept, and the drive toward self-actualisation. Biological theory (option D) roots personality in genetics, temperament, and brain physiology. Reciprocal determinism specifically captures Bandura's insight that person, behaviour, and environment jointly and reciprocally determine one another. (no official key in the paper; answer determined by subject expertise)"}, {"q": "Which neuroscientific technique provides the highest temporal resolution for studying neural activity?", "options": {"a": "fMRI", "b": "PET scan", "c": "EEG", "d": "CT scan"}, "correct": "c", "section": "physio", "explanation": "Temporal resolution refers to how precisely in time a technique can track changes in neural activity, whereas spatial resolution refers to how precisely it localizes them in space. Electroencephalography (EEG), pioneered for humans by Hans Berger, records the summed electrical potentials of cortical neurons directly from scalp electrodes. Because it measures electrical activity in real time, its temporal resolution is on the order of milliseconds, the best among the options listed, which is why it and the related magnetoencephalography are preferred for studying the rapid dynamics of perception and the timing of event-related potentials. Its weakness is poor spatial resolution and the inverse problem of localizing sources. Functional MRI (fMRI) and PET rely on hemodynamic or metabolic signals (blood oxygenation for fMRI, tracer uptake for PET) that lag neural events by seconds to minutes, giving them fine spatial but coarse temporal resolution. CT is purely structural. Because the question asks specifically about the highest temporal resolution, EEG (option c) is correct."}, {"q": "Lack of bowel control in children is known as:", "options": {"a": "Encopresis", "b": "Analism", "c": "Enuresis", "d": "Anorexia"}, "correct": "a", "section": "dev", "explanation": "The correct answer is encopresis. Encopresis is the repeated passage of faeces into inappropriate places (such as clothing or the floor) by a child who is old enough to have achieved bowel control, conventionally a chronological and developmental age of at least four years. It is the lack of bowel control beyond the expected age, and it can be either primary (the child has never established control) or secondary (control was achieved and then lost, often linked to stress or constipation with overflow soiling). Encopresis is contrasted with enuresis, which is the repeated involuntary or intentional voiding of urine, that is, lack of bladder control, into bed or clothes by a child old enough to be continent (usually age five and above). The simple way to keep these straight is that encopresis concerns the bowel (faeces) while enuresis concerns the bladder (urine). Both are elimination disorders in child psychiatry and may have physiological contributors (constipation, small bladder capacity), developmental delay, or emotional and behavioural factors. Because the question specifically asks about bowel control, encopresis is the correct term, and the key distinction to remember is bowel versus bladder."}, {"q": "Which of the following methods is used in Beck's cognitive therapy for depression?", "options": {"a": "Encouraging dream analysis", "b": "Making objective assessments of beliefs", "c": "Administering psychoactive medication", "d": "Practicing free association"}, "correct": "b", "section": "clinical", "explanation": "Cognitive therapy for depression was developed by Aaron Beck, who proposed that depression is maintained by systematically distorted thinking rather than by unconscious conflict. Central to his model is the negative cognitive triad: negative views of the self, the world, and the future, sustained by cognitive distortions such as arbitrary inference, overgeneralization, and catastrophizing, all stemming from maladaptive core beliefs and schemas. The therapy therefore trains clients to identify automatic negative thoughts, examine the evidence for and against them, and test their validity, essentially treating beliefs as hypotheses to be evaluated objectively rather than accepted as fact. This process, often called collaborative empiricism and cognitive restructuring, may be paired with behavioral experiments and homework. The distractors describe methods from other traditions: dream analysis and free association are hallmark techniques of the psychoanalysis of Sigmund Freud, and administering medication is a biological treatment. Because making objective, evidence-based assessments of one's beliefs is the defining technique of Beck's approach, option b is correct."}, {"q": "Which personality disorder is marked by manipulation, lack of remorse, and irresponsibility?", "options": {"a": "Borderline personality disorder", "b": "Antisocial personality disorder", "c": "Dependent personality disorder", "d": "Narcissistic personality disorder"}, "correct": "b", "section": "disorders", "explanation": "Antisocial personality disorder (ASPD) is a Cluster B personality disorder in the DSM-5 characterized by a pervasive pattern of disregard for and violation of the rights of others beginning by age 15. Its hallmark features are deceitfulness and manipulation for personal gain, lack of remorse for harm caused, impulsivity, irritability and aggressiveness, reckless disregard for safety, and consistent irresponsibility in work and financial obligations. Diagnosis requires the person to be at least 18 and to have had evidence of conduct disorder before age 15. The construct overlaps with, but is broader than, the classic notion of psychopathy described by Hervey Cleckley in The Mask of Sanity and later operationalized by Robert Hare. The distractors are other personality disorders with different cores: borderline (emotional and relational instability, abandonment fears), dependent (clinging, submissive reliance on others), and narcissistic (grandiosity and need for admiration). Because the triad of manipulation, lack of remorse, and irresponsibility maps directly onto ASPD, option b is correct."}, {"q": "In experimental psychology, which of the following scenarios best controls for expectancy effects?", "options": {"a": "Using a single-blind procedure.", "b": "Employing random assignment without blinding.", "c": "Providing participants with pretest instructions to reduce bias.", "d": "Implementing a double-blind design where neither subjects nor experimenters know the conditions."}, "correct": "d", "section": "research", "explanation": "Expectancy effects are systematic biases introduced when the beliefs or hopes of participants or experimenters influence outcomes. On the participant side these are demand characteristics and placebo responses; on the experimenter side they are the Rosenthal effect, named for Robert Rosenthal, who showed that experimenters can unconsciously cue subjects toward expected results. A single-blind procedure conceals the condition from participants only, leaving the experimenter free to bias measurement, coding, or interaction. A double-blind design conceals condition assignment from both the participants and the experimenters (or the personnel interacting with and assessing them), so neither party's expectations can shape behavior or scoring. This is the gold standard in clinical drug trials, where an active drug and an inert placebo are administered by staff who do not know which is which. Random assignment (option b) is essential for internal validity and controlling confounds, but it addresses group equivalence, not expectancy. Because only the double-blind arrangement neutralizes expectancy from both directions, option d is correct."}, {"q": "Dark adaptation is the process in which the eyes get more sensitive to:", "options": {"a": "Green light", "b": "Coloured lights", "c": "Light with bright illumination", "d": "Light with low illumination"}, "correct": "d", "section": "general", "explanation": "The correct answer is light with low illumination. Dark adaptation is the gradual recovery of the eye's sensitivity that occurs when you move from a brightly lit environment into darkness, for example walking from sunlight into a dim cinema. At first you can see almost nothing, but over roughly twenty to thirty minutes your eyes become dramatically more sensitive, able to detect very faint light. The mechanism rests on the two photoreceptor systems of the retina. Cones, packed in the fovea, handle bright daytime (photopic) vision and colour but are relatively insensitive in dim light. Rods, spread across the periphery, contain the pigment rhodopsin and are exquisitely sensitive to low illumination. In bright light rhodopsin is bleached and broken down; in darkness it is resynthesised, and as its concentration rebuilds the rods regain sensitivity. The dark adaptation curve is therefore biphasic: an early rapid cone phase lasting a few minutes, then a slower rod phase that continues for half an hour and accounts for the deepest sensitivity. This is why faint stars become visible only after you have stood outside for a while, and why we see dim objects best slightly off-centre, using peripheral rods rather than the cone-rich fovea. The process is the basis of scotopic (low-light) vision."}, {"q": "The improvement in anxiety may sometimes spuriously improve depression. This is called:", "options": {"a": "Halo effect", "b": "Ceiling effect", "c": "Hawthorne effect", "d": "Therapeutic effect"}, "correct": "a", "section": "assessment", "explanation": "The keyed answer is the halo effect. The halo effect is a cognitive bias in which one's overall impression of a person, or one prominent trait, colours the judgement of their other, separate characteristics. Coined by Edward Thorndike, it originally described how officers rating soldiers let a single favourable impression inflate ratings of unrelated qualities. In this clinical example, because the patient's anxiety has improved, the rater is inclined to judge that the depression has improved too, even though depression was not really assessed independently; the positive global impression spills over and spuriously raises the depression rating. This is a serious threat to the validity of clinical ratings and assessment, because it creates artificial correlations between symptoms that should be rated separately. Researchers guard against it by using structured, anchored rating scales, by having different raters assess different domains, and by blinding. It is worth noting that some texts would describe symptom co-improvement differently, but within the framework of rating bias the spillover of one improved judgement onto another is the halo effect, which is why the source keys it here. The key learning point is that a rater's general impression can distort the measurement of specific, supposedly independent variables."}, {"q": "Who proposed the social role theory of gender?", "options": {"a": "Buss", "b": "Alice Eagly", "c": "Mehta and Strough", "d": "Anderson"}, "correct": "b", "section": "social", "explanation": "The correct answer is Alice Eagly. Alice Eagly proposed social role theory to explain sex differences in social behavior. The theory holds that observed psychological and behavioral differences between men and women arise largely from the contrasting social roles they occupy, roles historically shaped by a division of labor. Because women were more often assigned domestic and caregiving roles and men more often assigned provider and leadership roles, societies developed gender-role expectations (communal traits like nurturance for women, agentic traits like assertiveness for men). Individuals then internalize and enact these expectations, and observers infer that men and women have differing inherent dispositions, a bias that reinforces the roles. Crucially, social role theory is a sociocultural account and stands in direct contrast to the evolutionary psychology explanation championed by David Buss, who attributes sex differences to inherited adaptations from ancestral mating and survival pressures. Eagly later extended her framework into the biosocial and role congruity theories, the latter explaining prejudice against women in leadership when leader stereotypes clash with female gender roles. The item tests correct attribution of the sociocultural theory to Eagly."}, {"q": "Which of the following statements is TRUE with respect to Minnesota Multiphasic Personality Inventory (MMPI)?", "options": {"a": "It utilizes rational method of test construction", "b": "It is constructed by assuming specific personality traits and formulating questions to answer them", "c": "It is derived by finding items that discriminate between criterion and control groups", "d": "It is true with respect to both a and b"}, "correct": "c", "section": "personality", "explanation": "The correct answer is that the MMPI is derived by finding items that discriminate between criterion and control groups. The Minnesota Multiphasic Personality Inventory was developed by Starke Hathaway and J. Charnley McKinley in the early 1940s and is the classic example of the empirical (criterion-keying) method of test construction. Rather than assuming in advance which items should measure a trait (the rational or deductive approach) or grouping items by statistical clustering (the factor-analytic approach used by Raymond Cattell for the 16PF), the empirical method selects items purely on the basis of whether they empirically distinguish a criterion group (for example, patients diagnosed with depression) from a normal control group. An item is retained for a scale if the two groups answer it differently, regardless of whether its content seems face-relevant. This is why some MMPI items appear unrelated to the construct they help measure. The approach yields clinical scales (such as Depression, Hypochondriasis, Psychopathic Deviate, Schizophrenia, Paranoia) plus validity scales (L, F, K) that detect response distortion. Because options a and b both describe the rational method that the MMPI did not use, the only true statement is that it discriminates between criterion and control groups, making option c correct."}, {"q": "Narendra turns around and around in a circle. When he stops, he feels like his head is spinning. What is responsible for this sensation?", "options": {"a": "Semi circular canals", "b": "Proprioceptors", "c": "Otolith organs", "d": "Otolith crystals"}, "correct": "a", "section": "physio", "explanation": "The correct answer is the semicircular canals. Spinning and the dizzy after-sensation are functions of the vestibular system in the inner ear, which provides our sense of balance and head movement. The vestibular apparatus has two parts. The three semicircular canals, oriented in three different planes, detect rotational (angular) acceleration: each canal is filled with fluid (endolymph) and contains a gelatinous cupula with hair cells. When the head rotates, the fluid lags behind due to inertia, bending the cupula and triggering the hair cells. When Narendra suddenly stops spinning, the fluid keeps moving for a moment, continuing to bend the hair cells, so the brain is still told the head is rotating even though it has stopped. This mismatch produces the illusion of spinning, dizziness, and the characteristic nystagmus of the eyes. The other vestibular structures, the otolith organs (the utricle and saccule), detect linear acceleration and the pull of gravity, telling us about head tilt and straight-line motion, not rotation. Because the question is specifically about turning in circles and the resulting spin sensation, the rotation-detecting semicircular canals are the correct structure."}, {"q": "A researcher would like to study how and to what degree heredity and the environment influence obesity. What population of individuals would provide the most information?", "options": {"a": "Dizygotic twins adopted by different parents", "b": "Monozygotic twins raised by their biological parents", "c": "Monozygotic twins adopted by different parents", "d": "Siblings adopted by different parents"}, "correct": "c", "section": "dev", "explanation": "The correct answer is monozygotic twins adopted by different parents. This is the classic 'twins reared apart' design, the most powerful natural experiment in behaviour genetics for separating the effects of heredity from environment. Monozygotic (identical) twins share essentially 100 percent of their genes, so when they are raised in different families and thus different environments, any remaining similarity between them (for example in body weight or obesity) can be attributed largely to their shared genetics, while any differences reflect environmental influence. This logic underpinned famous projects such as the Minnesota Study of Twins Reared Apart led by Thomas Bouchard. Comparing identical twins reared apart to identical twins reared together, and to fraternal twins and unrelated adoptees, lets researchers estimate heritability. Dizygotic twins and ordinary siblings share only about half their genes, so they cannot pinpoint genetic contribution as precisely, and twins raised together confound genes with a shared home environment. The item tests understanding of why maximising genetic similarity while varying environment yields the cleanest estimate of the nature versus nurture balance for a trait like obesity."}, {"q": "Any distorting or selective effect of a person’s inner world on his perception or conception of the outer world is termed:", "options": {"a": "Projection", "b": "Introjection", "c": "Empathy", "d": "Denial"}, "correct": "d", "section": "clinical", "explanation": "The keyed answer is denial, though the wording of the question describes a broader concept. The phrase 'any distorting or selective effect of a person's inner world on his perception of the outer world' captures how defence mechanisms in general bend reality to protect the ego. Denial is the most primitive of these defences: the person simply refuses to acknowledge an external reality that is too threatening to bear, behaving as though a painful fact does not exist, for example a terminally ill patient insisting they are perfectly healthy, or a person refusing to accept a loved one's death. Defence mechanisms were first systematised by Sigmund Freud and elaborated by Anna Freud in The Ego and the Mechanisms of Defence. They operate unconsciously and serve to reduce anxiety arising from conflict between the id's impulses, the superego's prohibitions, and external reality. Denial works at the level of perception itself, blocking the threatening information before it is fully registered, which is exactly why it fits a definition framed around distorting one's conception of the outer world. Clinically, heavy reliance on denial is associated with more immature or psychotic-level functioning, whereas mature defences like sublimation or humour distort reality far less. The source treats denial as the answer because the definition stresses a global filtering of outer reality rather than a specific impulse."}, {"q": "The term ‘Ambivalence’ was coined by:", "options": {"a": "Kraepelin", "b": "Eugen Bleuler", "c": "Richmond Fromm", "d": "Sigmund Freud"}, "correct": "b", "section": "disorders", "explanation": "The correct answer is Eugen Bleuler. Ambivalence, the simultaneous holding of contradictory feelings, attitudes, or impulses toward the same object (such as loving and hating someone at once), was coined by the Swiss psychiatrist Eugen Bleuler. Bleuler is one of the most important figures in the history of schizophrenia. In 1911 he renamed Kraepelin's dementia praecox as schizophrenia, meaning a splitting of psychic functions, to capture the disintegration between thought, emotion, and behaviour. He identified what are now called Bleuler's four As as the fundamental symptoms of the disorder: loosening of Associations (disordered thought connections), Affective disturbance (blunted or inappropriate emotion), Ambivalence (contradictory feelings or volitions held together), and Autism (withdrawal into an inner fantasy world). He regarded hallucinations and delusions as merely accessory symptoms, secondary to these core disturbances. Ambivalence as Bleuler used it can occur in the emotional, volitional, or intellectual spheres and reflects the fragmentation of the integrated mind that he believed defined schizophrenia. The term has since entered general psychological and psychoanalytic vocabulary, but its origin lies with Bleuler."}, {"q": "Reliable difference between two groups can be obtained by using:", "options": {"a": "Norms", "b": "Validity", "c": "Reliability", "d": "Statistical test"}, "correct": "d", "section": "research", "explanation": "The correct answer is a statistical test. To know whether two groups genuinely differ, rather than differing only because of random sampling fluctuation, you must apply an inferential statistical test such as a t-test, ANOVA, or chi-square. These tests compute the probability (the p-value) that the observed difference could have arisen by chance if there were truly no difference in the populations. If that probability is small (conventionally below .05), the difference is judged statistically significant and considered reliable, meaning unlikely to be a fluke. The logic rests on null hypothesis significance testing: you assume no difference (the null hypothesis), calculate how surprising your data would be under that assumption, and reject the null when the data are sufficiently improbable. Without such a test you cannot distinguish a real effect from noise, no matter how large the raw difference looks, because small samples produce large random swings. This is the core tool of quantitative research design and why a statistical test, not a property of the measuring instrument, is what establishes a reliable difference between groups."}, {"q": "Which method is characterized by moving from specific observations to broader generalizations?", "options": {"a": "Deductive reasoning", "b": "Inductive reasoning", "c": "Experimental design", "d": "Qualitative analysis"}, "correct": "b", "section": "general", "explanation": "The correct answer is Inductive reasoning. Inductive reasoning is defined by its direction of inference: it moves from specific, particular observations toward broader, general conclusions or theories. The researcher notices individual instances, identifies a recurring pattern, and then generalises to a wider principle, so the phrase in the question, from specific observations to broader generalizations, is the textbook definition of induction, making option B correct. Deductive reasoning (option A) runs in exactly the opposite direction, from broad general premises or theory down to specific predictions and instances, so it cannot be the answer. Experimental design (option C) is a methodological strategy for manipulating variables and controlling conditions to test causal hypotheses, in the tradition of Ronald Fisher; it is a type of study, not a label for the specific-to-general direction of reasoning. Qualitative analysis (option D) frequently employs inductive logic and is associated with it, but qualitative analysis names a family of data-analysis approaches rather than the reasoning pattern itself, so it is not the precise term the question seeks. A key caution about induction is that its conclusions are probable rather than certain, since a general claim inferred from limited observations can always be overturned by a new counterexample. (no official key in the paper; answer determined by subject expertise)"}, {"q": "Which of the following is a type of attitude measurement scale?", "options": {"a": "Nominal scale", "b": "Ordinal scale", "c": "Interval scale", "d": "Likert scale"}, "correct": "d", "section": "assessment", "explanation": "The correct answer is Likert scale. A Likert scale is a specific attitude measurement technique developed by Rensis Likert in 1932. It presents respondents with a series of statements and asks them to indicate their level of agreement along a symmetric range, typically five points from strongly disagree to strongly agree, and it sums or averages responses to gauge an underlying attitude. It is one of the most widely used attitude scales, alongside the Thurstone scale (Louis Leon Thurstone) and the Guttman scale (Louis Guttman). The other three options, nominal, ordinal, and interval, are Stanley Smith Stevens's levels of measurement, describing the mathematical properties of data rather than being named instruments for capturing attitudes. Nominal denotes unordered categories, ordinal denotes ranked categories, and interval denotes equal-spaced values with an arbitrary zero. While Likert responses are themselves usually treated as ordinal data, the Likert scale as a whole is a purpose-built attitude-measurement method, which is what the question asks for. Recognising named attitude scales matters in psychometrics because each has different assumptions about scoring and dimensionality, and the Likert format's ease of construction and interpretation explains its dominance in survey research. (no official key in the paper; answer determined by subject expertise)"}, {"q": "Arvind is a college student who has strong negative feelings about smoking cigarettes. His grandfather died of lung cancer and he believes smoking is disgusting. One night at a party, Arvind's friends all go outside for a cigarette and he decides to smoke as well. What will he most likely experience as a result?", "options": {"a": "Justification of efforts", "b": "Increased drive to smoke", "c": "Cognitive Dissonance", "d": "Drive Reduction"}, "correct": "c", "section": "social", "explanation": "The correct answer is cognitive dissonance. Leon Festinger developed the theory of cognitive dissonance in 1957, proposing that people feel an uncomfortable state of psychological tension when they hold two contradictory cognitions or when their behaviour conflicts with their attitudes. Arvind strongly believes smoking is disgusting and harmful (his grandfather died of lung cancer), yet he chooses to smoke. The clash between his anti-smoking attitude and his pro-smoking behaviour produces dissonance. Festinger argued that people are motivated to reduce this tension, typically by changing the attitude ('maybe smoking once is not so bad'), changing the behaviour (stopping), or adding consonant cognitions ('everyone was doing it, it was just social'). Festinger and James Merrill Carlsmith demonstrated this experimentally in their famous 1959 study where participants paid only one dollar to lie about a boring task later rated it as more enjoyable, because low external justification forced them to resolve dissonance internally. Distractors like justification of effort are subtypes of dissonance but require prior effort or suffering, which is absent here. This item tests whether the student can identify the general dissonance concept from an attitude-behaviour conflict scenario."}, {"q": "Vaibhav smokes, drinks alcohol, overeats, and bites his nails. Which stage of Freud's stages of psychosexual Development has Vaibhav become fixated at?", "options": {"a": "Phallic stage", "b": "Anal stage", "c": "Oral stage", "d": "Latency stage"}, "correct": "c", "section": "personality", "explanation": "The correct answer is the oral stage. Sigmund Freud proposed five psychosexual stages of development (oral, anal, phallic, latency, genital), each centred on a different erogenous zone where libidinal energy is focused. If a child's needs are either overindulged or under-gratified at a given stage, Freud argued that some libido remains fixated there, producing characteristic adult personality traits and behaviours. The oral stage (roughly birth to 18 months) centres on the mouth, with pleasure derived from sucking, biting, and chewing. Fixation at the oral stage is expressed in adulthood through mouth-oriented and dependency-related behaviours such as smoking, excessive drinking, overeating, nail-biting, and thumb-sucking, exactly the cluster described for Vaibhav. An oral-receptive versus oral-aggressive personality may also develop. The anal stage (option B) concerns bladder and bowel control and yields orderliness or messiness; the phallic stage involves the Oedipus and Electra complexes; and latency is a quiet period before the mature genital stage. Although Freud's theory is scientifically criticised and largely unfalsifiable, it remains standard exam content. The item tests the classic association between oral fixation and mouth-focused adult habits."}, {"q": "Which area of the brain is primarily associated with the consolidation of long-term memories?", "options": {"a": "Hippocampus", "b": "Amygdala", "c": "Prefrontal Cortex", "d": "Cerebellum"}, "correct": "a", "section": "physio", "explanation": "The correct answer is Hippocampus. The hippocampus, a seahorse-shaped structure in the medial temporal lobe, plays a central role in consolidating new information from short-term into long-term declarative memory, that is, memory for facts and events. Its importance was dramatically revealed by the case of patient H.M. (Henry Molaison), studied by Brenda Milner, whose bilateral hippocampal removal left him unable to form new long-term memories (anterograde amnesia) while sparing older memories and motor learning. This showed the hippocampus is essential for encoding and consolidating new declarative memories, even though the memories are eventually stored in the neocortex. Option A is thus correct. The amygdala (option B), also in the temporal lobe, processes emotion, especially fear, and modulates how strongly emotional experiences are remembered, but it is not the primary consolidation site. The prefrontal cortex (option C) supports working memory, attention, and executive control rather than the consolidation of new long-term memories. The cerebellum (option D) governs motor coordination, balance, and procedural (implicit) learning such as classically conditioned responses, not declarative memory. The concept of synaptic consolidation, involving long-term potentiation described by Donald Hebb's principle that cells that fire together wire together, underlies how the hippocampus stabilises new memories. (no official key in the paper; answer determined by subject expertise)"}, {"q": "Helicopter Parenting is the result of:", "options": {"a": "Parental anxiety", "b": "Parental unfulfilled wishes", "c": "Parents' personality traits", "d": "All of above"}, "correct": "d", "section": "dev", "explanation": "The keyed answer is all of the above, because helicopter parenting is multiply determined rather than springing from one source. Helicopter parenting describes an over involved style in which parents hover, intervene excessively, solve problems their child could solve alone, and monitor and control developmentally inappropriate amounts of the child's life. Research on its origins points to several converging causes. First, parental anxiety: parents who are highly anxious about safety, failure, or the future manage their own distress by controlling the child's environment, so the hovering is partly an emotion regulation strategy for the parent. Second, parents' unfulfilled wishes: parents may project their own thwarted ambitions onto the child and micromanage achievement so the child realises the life the parent did not, a form of vicarious living. Third, the parents' own personality traits: dispositions such as perfectionism, neuroticism, high need for control, or an anxious attachment style predispose a person to over involvement. Because each of these has empirical support and they often act together, the comprehensive answer is all of the above. Developmentally the concern is that over parenting undermines the child's autonomy, self efficacy (Albert Bandura, 1977), and emotion regulation, contributing to higher anxiety and lower coping in emerging adults, which is why it is studied as a risk style rather than a benign quirk."}, {"q": "Which of the following technique or techniques would not typically be included within the repertoire of an Adlerian counsellor?", "options": {"a": "Acting \"as if\"", "b": "Push button", "c": "Encouragement", "d": "Analysis of transference"}, "correct": "d", "section": "clinical", "explanation": "The correct answer is analysis of transference. Adlerian counselling, derived from the Individual Psychology of Alfred Adler, emphasizes holism, social interest (Gemeinschaftsgefuhl), lifestyle assessment, birth-order and family constellation, striving for superiority, and encouragement, working in a collaborative, egalitarian, present-and-future-oriented way. Its distinctive techniques include acting as if (encouraging clients to behave as though they were already the capable person they wish to become), the push-button technique (having clients alternately generate pleasant and unpleasant memories to demonstrate that they can control their emotional states), catching oneself, spitting in the client's soup, paradoxical intention, and above all encouragement, which Adlerians regard as the key to counteracting discouragement and inferiority feelings. Analysis of transference, by contrast, is a hallmark of classical psychoanalysis developed by Sigmund Freud, in which the client's unconscious redirection of feelings about significant early figures onto the analyst is systematically interpreted. Adler broke from Freud and de-emphasized the unconscious, drive theory, and the intensive analysis of transference in favor of conscious goals, social embeddedness, and encouragement. Therefore, transference analysis is the technique that does not belong in the Adlerian repertoire, making option d correct."}, {"q": "The diathesis-stress model of psychopathology suggests that mental disorders result from :", "options": {"a": "Genetic factors only", "b": "Environmental factors only", "c": "A combination of genetic predisposition and environmental stressors", "d": "Neurobiological abnormalities only"}, "correct": "c", "section": "disorders", "explanation": "The correct answer is a combination of genetic predisposition and environmental stressors. The diathesis-stress model is an interactionist framework in psychopathology holding that mental disorders arise from the interaction between a diathesis, a pre-existing vulnerability or predisposition (often genetic, but also biological or psychological), and stress, adverse environmental experiences or life events. Neither factor alone is usually sufficient: a person may carry a vulnerability that never manifests unless triggered by sufficient environmental stress, and conversely, stress may not produce disorder in someone without the underlying predisposition. The disorder emerges when the accumulated stress exceeds the threshold set by the individual's diathesis. This interaction of nature and nurture is exactly what option C describes. Option A, genetic factors only, is wrong because it omits the stress side of the equation and reduces the model to pure heredity. Option B, environmental factors only, is likewise incomplete because it ignores the predisposition, or diathesis. Option D, neurobiological abnormalities only, is a single-cause, reductionist explanation that contradicts the model's central claim that disorder results from the interplay of vulnerability and environment, not from biology alone. The diathesis-stress model, with roots in work by researchers such as Paul Meehl on schizophrenia, is widely used to explain conditions like depression and schizophrenia, integrating biological and environmental contributions. (no official key in the paper; answer determined by subject expertise)"}, {"q": "Which of the following is an example of a quantitative research method?", "options": {"a": "Case study", "b": "Ethnography", "c": "Survey", "d": "Grounded theory"}, "correct": "c", "section": "research", "explanation": "The correct answer is Survey. Quantitative research collects numerical data that can be counted, measured, and statistically analysed to test hypotheses and generalise to a population. A survey administers standardised questions to a sample and yields numeric responses (ratings, frequencies, percentages), so it is a classic quantitative method. This distinction traces to the broader positivist tradition described by Auguste Comte, in which knowledge is built from measurable observation. Qualitative methods, by contrast, aim to understand meaning, context, and lived experience through words rather than numbers. Case study (championed as a method by Robert Yin), ethnography (rooted in the anthropology of Bronislaw Malinowski), and grounded theory (developed by Barney Glaser and Anselm Strauss) all fall on the qualitative side because they produce rich descriptive text, not quantified variables. The key marker of a quantitative method is that the data can be entered into statistics and expressed as numbers. Surveys with closed-ended, scaled items fit this exactly. Understanding this divide matters because it determines which analysis (means, correlations, significance tests versus thematic coding) is appropriate for the data collected. (no official key in the paper; answer determined by subject expertise)"}]};
window.PREVIEW_DEEP = Object.assign(window.PREVIEW_DEEP||{}, {"jss-pyq": [{"q": "Gestalt psychology emphasizes :", "concept": "Gestalt psychology, founded by Wertheimer, Koffka, and Kohler, holds that perceptual experience is organized into wholes that cannot be reduced to the sum of individual sensory elements, captured in the maxim 'the whole is greater than the sum of its parts.' It gave rise to laws of perceptual organization such as proximity, similarity, and closure.", "traps": {"a": "Reinforcement and punishment are central to behaviorism (Skinner), not Gestalt psychology.", "b": "Neurotransmitter balance reflects a biological/biochemical model, unrelated to Gestalt perception.", "c": "Cognitive distortions belong to Beck's cognitive therapy, not Gestalt psychology."}}, {"q": "Cronbach's alpha assesses :", "concept": "Cronbach's alpha (Lee Cronbach, 1951) is a coefficient of internal consistency reliability, estimating how closely related a set of items are as a group within a scale. Values around 0.70 or higher are conventionally considered acceptable.", "traps": {"a": "Validity concerns whether a test measures what it intends; alpha addresses reliability, not validity.", "c": "Variance is a component within the alpha formula but is not what alpha assesses.", "d": "Regression is a predictive modeling technique, unrelated to alpha's function."}}, {"q": "Which phenomenon explains decreased effort in groups?", "concept": "Social loafing (Latane, Williams & Harkins, 1979) is the reduction in individual effort when people work in a group compared to working alone, because personal accountability is diffused. It was classically demonstrated with rope-pulling and shouting tasks (building on Ringelmann's findings).", "traps": {"a": "Groupthink (Irving Janis, 1972) is the tendency toward flawed consensus-seeking decisions, not reduced effort.", "c": "The bystander effect concerns reduced helping in the presence of others, not task effort.", "d": "Deindividuation is loss of self-awareness and restraint in crowds, not decreased effort."}}, {"q": "Which of the following describes introversion?", "concept": "Introversion, as described by Jung and elaborated in Eysenck's and the Big Five trait theories, is characterized by an inward orientation, a preference for solitude, and gaining energy from quiet or solitary activities rather than social stimulation.", "traps": {"a": "Enjoying large social gatherings reflects extraversion, not introversion.", "b": "Being talkative and outgoing is a hallmark of extraversion.", "d": "Aggressiveness and dominance relate to other traits (e.g., low agreeableness), not introversion."}}, {"q": "Which system includes the brain and spinal cord?", "concept": "The central nervous system (CNS) consists of the brain and the spinal cord, serving as the primary processing and integration center of the body.", "traps": {"a": "The peripheral nervous system comprises the nerves outside the brain and spinal cord.", "b": "The autonomic nervous system is a subdivision of the PNS controlling involuntary functions.", "c": "The somatic nervous system is a PNS subdivision controlling voluntary skeletal muscle movement."}}, {"q": "According to Piaget, object permanence develops during :", "concept": "In Piaget's theory, object permanence, the understanding that objects continue to exist when out of sight, is acquired during the sensorimotor stage (birth to about 2 years), typically emerging around 8-12 months. It is a landmark achievement of that stage before the onset of symbolic thought.", "traps": {"b": "The preoperational stage is marked by symbolic thought and egocentrism, well after object permanence is established.", "c": "The concrete operational stage introduces conservation and logical operations, far later than object permanence.", "d": "The formal operational stage involves abstract and hypothetical reasoning in adolescence, unrelated to object permanence."}}, {"q": "Which therapy focuses on changing maladaptive thought patterns?", "concept": "Cognitive-behavioural therapy (Beck, Ellis) targets maladaptive/distorted cognitions and the behaviours that maintain them, using cognitive restructuring to identify and modify dysfunctional automatic thoughts and beliefs. Changing thinking is its defining mechanism of change.", "traps": {"a": "Humanistic therapy (e.g., Rogers) emphasises self-actualisation and unconditional positive regard, not restructuring thoughts.", "c": "Psychoanalysis focuses on unconscious conflicts and insight, not directly on maladaptive thought patterns.", "d": "Play therapy uses play as the medium for children to express emotions, not cognitive restructuring."}}, {"q": "Conversion disorder differs from hypochondriasis in that :", "concept": "Conversion disorder (functional neurological symptom disorder) presents with pseudoneurological deficits (paralysis, blindness, seizures) incompatible with recognized organic disease, whereas hypochondriasis (illness anxiety disorder in DSM-5) is defined by preoccupation with and fear of having a serious illness. This is the core phenomenological distinction under both ICD-10 (F44 vs F45.2) and DSM classifications.", "traps": {"a": "Neither conversion nor hypochondriasis is defined by delusions or hallucinations; these are psychotic features, not somatoform ones.", "c": "Somatic preoccupation is actually the hallmark of hypochondriasis, so this reverses the true picture.", "d": "Hypochondriasis is not 'always' associated with depression, and comorbid mood symptoms can occur with conversion too."}}, {"q": "A researcher finds a correlation of r = -0.85 between stress and sleep quality. This indicates :", "concept": "A correlation of r = -0.85 is close to -1, indicating a strong inverse (negative) relationship: as stress increases, sleep quality decreases. The magnitude (0.85) reflects strength and the sign reflects direction.", "traps": {"a": "0.85 is a large magnitude, so the relationship is strong, not weak.", "b": "The negative sign indicates an inverse relationship, not a positive one.", "d": "An r near zero would indicate no relationship; -0.85 is far from zero."}}, {"q": "Who among the following has defined perception as a complex of sensory and imaginal events?", "concept": "Edward Titchener defined perception as a complex of sensory and imaginal elements, making b correct. Titchener was the leading proponent of structuralism, the school he brought to America from Wundt's Leipzig laboratory. Structuralism sought to analyse conscious experience into its most basic elements, much as chemistry breaks matter into atoms, using the method of introspection in which trained observers reported the elementary contents of their minds under controlled stimulation. For Titchener the three irreducible elements of mind were sensations, images, and affections, each describable by attributes such as quality, intensity, duration, and clarity. Within this framework a perception is not a simple sensation but a compound, a complex built from sensory elements together with the imaginal residues of past experience that give the present experience its meaning. That is exactly why his definition speaks of a complex of sensory and imaginal events. Structuralism eventually collapsed because introspection proved unreliable and the approach could not study children, animals, or the abnormal, but Titchener's elementalist definitions remain frequent exam content. The phrasing sensory and imaginal is the signature of Titchener's structuralist account of perception.", "traps": {"a": "Kimble is associated with definitions of learning, not with a structuralist analysis of perception into sensory and imaginal elements.", "c": "Bruner studied perception too, but he is known for the New Look approach emphasising motivation and expectancy, not for defining perception as sensory plus imaginal complexes.", "d": "Schafer worked with Bruner on value-driven perception, not on the structuralist elemental definition Titchener gave."}}, {"q": "Which personality assessment tool uses inkblots to assess thought processes?", "concept": "The Rorschach test, option c, uses inkblots to assess thought processes and personality. Created by the Swiss psychiatrist Hermann Rorschach in 1921, it consists of ten standardised, symmetrical inkblots, some achromatic and some with colour, that the examinee is asked to interpret by saying what each blot might be. It is a projective test, based on the projective hypothesis that when confronted with an ambiguous stimulus a person projects unconscious needs, conflicts, and ways of organising experience onto it. The clinician records responses and then codes them on dimensions such as location, whether the whole blot or a detail was used, determinants like form, colour, movement, and shading, and the content and quality of the response. The most rigorous modern scoring system is John Exner's Comprehensive System, which aimed to put interpretation on an empirical footing. The Rorschach is used to examine thought organisation, reality testing, emotional functioning, and the presence of disordered thinking, which makes it especially relevant when assessing thought processes. Its psychometric validity is debated, but its identity as the inkblot test is unambiguous, so option c is correct.", "traps": {"a": "The MMPI (Starke Hathaway and J. Charnley McKinley, 1943) is an objective, self-report personality inventory with hundreds of true-false items and validity scales, not an inkblot test.", "b": "The TAT is also projective but uses ambiguous pictures of people about which the person tells stories, not inkblots.", "d": "The MBTI is a self-report questionnaire sorting people into sixteen Jungian types; it uses no inkblots and is not a clinical thought-process measure."}}, {"q": "What does ‘groupthink’ refer to in social psychology?", "concept": "Groupthink, the correct answer b, is the mode of thinking that occurs when the drive for consensus in a cohesive group overrides realistic appraisal of alternatives, so dissent is suppressed and bad decisions result. The concept was introduced by Irving Janis in 1972 after he analysed foreign-policy fiascoes such as the Bay of Pigs invasion. Janis identified antecedent conditions: high cohesiveness, insulation from outside opinion, directive leadership, and high stress with low hope of a better solution than the leader's. These produce symptoms including an illusion of invulnerability, collective rationalisation, belief in the group's inherent morality, stereotyping of out-groups, direct pressure on dissenters, self-censorship, a shared illusion of unanimity, and self-appointed mindguards who shield the group from troubling information. The consequences are incomplete survey of alternatives, failure to examine risks, and poor contingency planning. Janis proposed remedies such as appointing a devil's advocate, inviting outside experts, and the leader withholding his preference. The defining feature for exams is that the cost of cohesion is the discouragement of dissent and critical evaluation, which is precisely what option b states.", "traps": {"a": "Individual thinking is the opposite of a group phenomenon and does not describe the consensus pressure Janis identified.", "c": "Brainstorming is a deliberate technique for generating many ideas without criticism, which actually encourages divergent input rather than suppressing dissent.", "d": "Peer pressure is a broader, more informal notion of social influence; groupthink is the specific, structured decision-making failure of cohesive groups."}}, {"q": "Which of the following personality types is described as noisy, callous and fond of physical activity?", "concept": "The mesomorph, option c, is described in Sheldon's constitutional theory as somatotonic: assertive, energetic, noisy, callous, and fond of physical activity and risk. William Sheldon proposed that body build, or somatotype, correlates with temperament. He identified three components present in every person to varying degrees. The endomorph is round and soft with a dominant digestive system and a viscerotonic temperament that is relaxed, sociable, comfort-loving, and food-loving. The mesomorph is muscular and hard-bodied with a dominant musculoskeletal system and a somatotonic temperament that is adventurous, dominant, assertive, physically active, and at times insensitive or callous to others. The ectomorph is thin, fragile, and linear with a dominant nervous system and a cerebrotonic temperament that is restrained, introverted, intellectual, and self-conscious. The theory is largely discredited as a serious account of personality because the correlations Sheldon reported were inflated and the work bordered on physiognomy, but it remains a staple exam item. The cluster of being noisy, tough, and craving physical activity maps directly onto the muscular mesomorph and the somatotonic temperament.", "traps": {"a": "The endomorph is the soft, round body type whose viscerotonic temperament is relaxed, sociable, and pleasure-loving, not noisy and physically aggressive.", "b": "The ectomorph is the thin, fragile type with a cerebrotonic, introverted, restrained temperament, the opposite of the bold physical mesomorph.", "d": "None of the above is incorrect because the mesomorph precisely matches the described temperament."}}, {"q": "Which part of the brain is primarily associated with cognitive functions such as problem-solving?", "concept": "The frontal lobe is the seat of higher cognitive functions including problem-solving, planning, reasoning, working memory, and judgement, so b is correct. The frontal lobe is the largest of the four cerebral lobes and its most anterior portion, the prefrontal cortex, is what most distinguishes the human brain. The prefrontal cortex orchestrates executive functions: setting goals, holding information online, inhibiting inappropriate responses, shifting between rules, and weighing consequences. Just behind it sits the primary motor cortex along the precentral gyrus, which initiates voluntary movement, and Broca's area in the left frontal lobe, which governs speech production. The classic case of Phineas Gage, whose personality and decision-making were devastated after an iron rod destroyed his frontal cortex while sparing basic abilities, dramatised that this region underlies social judgement and self-control. Clinically, frontal damage produces dysexecutive syndrome with poor planning, perseveration, disinhibition, and apathy, and the frontal lobes are implicated in disorders such as ADHD and schizophrenia. The other lobes specialise elsewhere, so when a question pairs cognition, reasoning, or problem-solving with brain location, the frontal lobe is the answer.", "traps": {"a": "The occipital lobe is the primary visual cortex; it processes sight, not reasoning or problem-solving.", "c": "The temporal lobe handles auditory processing, language comprehension via Wernicke's area, and memory through the underlying hippocampus, not executive cognition.", "d": "The parietal lobe integrates somatosensory information and spatial awareness; it is not the primary problem-solving region."}}, {"q": "Which psychologist proposed the concept of the ‘zone of proximal development’?", "concept": "Lev Vygotsky proposed the zone of proximal development, option c. Vygotsky was a Russian psychologist whose sociocultural theory emphasised that cognitive development is fundamentally social, mediated by language and culture and arising through interaction with more knowledgeable others. The zone of proximal development, or ZPD, is the gap between what a learner can do independently and what they can achieve with guidance from a more capable partner such as a teacher, parent, or skilled peer. Learning is most effective when it targets this zone, just beyond the learner's current independent ability. The supportive guidance that helps the learner cross the ZPD is often called scaffolding, a term coined by Bruner inspired by Vygotsky's ideas, where assistance is provided then gradually withdrawn as competence grows. Vygotsky also stressed the role of private speech and of cultural tools, and he argued that social interaction precedes and drives internal development, captured in his claim that every function appears first on the social plane and then on the psychological plane. This contrasts with Piaget's more individual, discovery-based account. The exam cue ZPD points unmistakably to Vygotsky.", "traps": {"a": "Jean Piaget proposed stages of cognitive development and emphasised individual discovery, not the socially mediated ZPD.", "b": "Erik Erikson developed psychosocial stages of identity and social-emotional crises, unrelated to the ZPD.", "d": "Sigmund Freud's theory concerned unconscious drives and psychosexual stages, not cognitive scaffolding or the ZPD."}}, {"q": "Match List I with List II LIST I (Psychologist) LIST 2 (Theory) A. Dollard and Miller 1. Radical Behaviorism B. Skinner 2. Self-Actualization C. Bandura and Walters 3. Early Social Learning D. Maslow 4. Later Social Learning", "concept": "The correct matching is A-3, B-1, C-4, D-2, option b. Dollard and Miller produced the early social learning theory by translating Freudian concepts into the language of Hullian learning theory in their 1950 work, so they pair with early social learning. B.F. Skinner is the founder of radical behaviourism, the position that even private events like thoughts and feelings are behaviour governed by environmental contingencies and that mental causes are unnecessary, so he pairs with radical behaviourism. Bandura and Walters advanced the later, more cognitive social learning theory, emphasising observational learning, modelling, and vicarious reinforcement that went beyond simple stimulus-response accounts, so they pair with later social learning. Abraham Maslow, a founder of humanistic psychology, is identified with self-actualization, the drive to fulfil one's potential at the apex of his hierarchy of needs, so he pairs with self-actualization. The conceptual through-line is the evolution of learning theory: Dollard and Miller bridged psychoanalysis and behaviourism (John B. Watson, 1913), Skinner radicalised behaviourism, Bandura cognitised it into social-cognitive theory, while Maslow stood apart in the humanistic camp. Mapping each name to its correct school yields b.", "traps": {"a": "A-1, B-2, C-3, D-4 wrongly assigns radical behaviourism to Dollard and Miller and self-actualization to Skinner, reversing the actual authorship of those ideas.", "c": "A-2, B-1, C-3, D-4 gives self-actualization to Dollard and Miller and misplaces Maslow, which is incorrect.", "d": "A-3, B-2, C-4, D-1 correctly places Dollard and Miller but assigns self-actualization to Skinner and radical behaviourism to Maslow, both wrong."}}, {"q": "Which disorder is characterised by persistent sadness and loss of interest?", "concept": "Persistent sadness combined with a loss of interest or pleasure is the hallmark of depression, making b correct. In DSM-5 terms, major depressive disorder requires at least five symptoms over a two-week period, and crucially at least one of them must be either depressed mood or anhedonia, the loss of interest or pleasure in nearly all activities. The remaining symptoms span the neurovegetative and cognitive domains: significant weight or appetite change, insomnia or hypersomnia, psychomotor agitation or retardation, fatigue, feelings of worthlessness or excessive guilt, diminished concentration, and recurrent thoughts of death or suicide. The two cardinal symptoms, low mood and anhedonia, are what the question is pointing to. Depression is among the most common mental disorders and a leading cause of disability worldwide. Beck's cognitive model frames it around the negative cognitive triad of negative views of self, world, and future, while biological models emphasise monoamine dysregulation involving serotonin, norepinephrine, and dopamine. Treatments include antidepressants, cognitive-behavioural therapy, and interpersonal therapy. The distinguishing point for Sihan is the combination of pervasive sadness with anhedonia, which separates depression from disorders defined by psychosis, mood cycling, or anxiety.", "traps": {"a": "Schizophrenia is a psychotic disorder defined by delusions, hallucinations, disorganised thought, and negative symptoms, not by sadness and lost interest.", "c": "OCD is an anxiety-related disorder marked by intrusive obsessions and compulsive rituals, not by pervasive low mood.", "d": "Bipolar disorder does include depressive episodes but is defined by the presence of mania or hypomania, so persistent sadness alone points to depression, not bipolar."}}, {"q": "A graphical representation of correlational data is called a :", "concept": "A graphical representation of correlational data is a scatterplot, option c. A scatterplot, also called a scatter diagram, displays each pair of observations as a single point whose horizontal position represents one variable and vertical position represents the other. By plotting all paired scores it reveals the form, direction, and strength of the relationship between two variables at a glance. If points trend upward from lower left to upper right the correlation is positive; if they trend downward it is negative; if they cluster tightly around a line the correlation is strong, and if they scatter widely it is weak; if they show no slope there is little or no linear relationship. The scatterplot also exposes nonlinearity and outliers that a single correlation coefficient would hide, which is why it is the standard visual companion to the Pearson correlation. Correlation, expressed by coefficient r ranging from minus one to plus one, quantifies the linear association but never proves causation. For the exam, the rule is simple: when two continuous variables and their relationship are to be shown visually, the scatterplot is the chart, making option c correct.", "traps": {"a": "A bell curve is the normal distribution, depicting how a single variable is distributed, not the relationship between two variables.", "b": "Chi square is a statistical test of association between categorical variables, not a graph of correlational data.", "d": "A skewed distribution describes the asymmetric shape of one variable's frequency distribution, not a display of correlation."}}, {"q": "The visible spectrum wavelength ranges from", "concept": "The correct answer is roughly 380 to 760 nanometres because this is the narrow band of electromagnetic radiation that the human eye can actually detect and convert into neural signals. Light is one form of electromagnetic energy, and the full spectrum runs from very short gamma and X rays through ultraviolet, then the visible band, then infrared, microwaves and radio waves. What makes the visible band special is purely biological: the photopigments in our rods and cones, especially the three cone opsins, absorb photons only within this range, so wavelengths outside it never trigger a visual response. Wavelength maps onto the experience of colour. The short end near 380 to 400 nm is seen as violet and blue, the middle around 500 to 565 nm as green and yellow, and the long end near 700 to 760 nm as red. Below 380 nm lies ultraviolet, which carries enough energy to damage tissue but is filtered by the cornea and lens, and above 760 nm lies infrared, which we feel as heat rather than see. Different texts quote slightly different cut offs, often 400 to 700 nm, but the classic psychophysics figure given in introductory psychology is 380 to 760 nm, so that is the keyed answer. The key idea to carry into the exam is that vision is a transduction process limited by the absorption properties of our photoreceptors, not by the physics of light itself.", "traps": {"b": "200 to 700 nm pulls the lower bound down into the ultraviolet, which the cornea and lens absorb and which we cannot see, so this range is too wide on the short end.", "c": "400 to 1000 nm extends well into the infrared region beyond about 760 nm, which we perceive as warmth rather than light, so the upper bound is wrong.", "d": "100 to 1000 nm spans deep ultraviolet through infrared and is far too broad, covering radiation our photoreceptors cannot transduce at either extreme."}}, {"q": "Confabulatory responses on Rorschach Psychodiagnostics are indicative of:", "concept": "Confabulatory responses on the Rorschach indicate impairment in reality testing, so the answer is a. The Rorschach inkblot test is a projective assessment in which the examinee reports what they see in ambiguous blots, and the way they perceive and organise the stimulus reveals their thought processes and contact with reality. A confabulation (often scored DW or as a confabulatory response) occurs when the person uses a small, isolated detail of the blot to justify a global response about the whole area, overgeneralising from a fragment to an unjustified whole, for example seeing a tiny claw and therefore declaring the entire blot a monstrous crab. This kind of response reflects a loosening of the perceptual and logical link between what is actually on the card and the percept reported; the conclusion is not adequately grounded in the stimulus. Because reality testing is precisely the capacity to keep perceptions and inferences anchored to external reality and to distinguish internal impressions from objective fact, confabulatory responses, in which inference runs ahead of the perceptual evidence, signal impaired reality testing and are associated with psychotic level thought disturbance. The exam discriminator is recognising that confabulation on the Rorschach is a sign of a thought disorder and faulty reality contact, rather than a marker of empathy, ego regression, or mere cognitive immaturity.", "traps": {"b": "Extreme lack of empathy is more associated with the absence or quality of human responses on the Rorschach, not with confabulatory perception.", "c": "Regressed ego is a broader psychodynamic inference; confabulation specifically indexes faulty reality testing rather than ego regression per se.", "d": "Cognitive immaturity might produce simple or concrete responses, but confabulation specifically signals a disturbance in the logic of reality contact, more than mere immaturity."}}, {"q": "A state that occurs when bystanders in an emergency situation use the behaviour of others to determine whether help is actually required is called:", "concept": "When bystanders read others' behaviour to decide whether help is needed, the resulting state is pluralistic ignorance, so the answer is a. Pluralistic ignorance is a social psychological phenomenon in which each member of a group privately doubts or rejects a norm or interpretation but mistakenly assumes that most others accept it, because everyone is publicly conforming while privately uncertain. In an ambiguous emergency, each bystander glances at the calm faces of the others to judge whether the situation is truly serious. Since everyone is doing the same thing and trying not to look panicked, all see a roomful of apparently unconcerned people and each concludes the event must not be an emergency. This is one of the key mechanisms, alongside diffusion of responsibility and audience inhibition, behind the bystander effect documented by Latane and Darley after the Kitty Genovese case. It operates through the broader process of informational social influence, using others as a source of information about reality, but the specific labelled outcome, where everyone wrongly infers no emergency from everyone else's inaction, is pluralistic ignorance. The exam discriminator is the phrase use the behaviour of others to determine whether help is actually required, which is the textbook description of pluralistic ignorance in the bystander intervention sequence.", "traps": {"b": "Group conformity is the broad tendency to align with a group; it is a more general process, not the specific misreading of others' inaction as evidence no help is needed.", "c": "Group compliance refers to publicly going along with a request or norm while perhaps disagreeing privately, not the emergency interpretation phenomenon.", "d": "Crowd behaviour is a general term for how people act in large gatherings and does not name the specific cognitive error in bystander emergencies."}}, {"q": "Who was called the 'French Freud'?", "concept": "Jacques Lacan was called the French Freud, so the answer is d. Lacan was the most influential French psychoanalyst of the twentieth century, who launched a return to Freud, urging analysts to read Freud's texts closely while reinterpreting psychoanalysis through structural linguistics and structuralism. His famous claims include that the unconscious is structured like a language, and his theory of the three registers, the Imaginary, the Symbolic, and the Real, along with the mirror stage, in which the infant forms an ego by identifying with its unified reflected image, a misrecognition that founds the self. His seminars dominated French intellectual life and shaped psychoanalysis, philosophy, and literary theory, earning him the epithet the French Freud for his stature and his project of renewing Freudian thought in France. For the exam this is a recognition item linking a nickname to a figure, and it usefully anchors Lacan's distinctive reworking of Freud through language and the symbolic order. The discriminating skill is distinguishing Lacan from the nineteenth century French alienists in the other options, Falret, Esquirol, and Briquet, who made important contributions to descriptive psychiatry but were not the structuralist heir to Freud honoured with that nickname.", "traps": {"a": "Jules Pierre Falret was a nineteenth century French psychiatrist who described folie circulaire (circular insanity), an early account of bipolar illness, not the French Freud.", "b": "Jean Etienne Esquirol was a pioneering French alienist who advanced the classification of mental disorders and asylum reform, predating Freud entirely.", "c": "Paul Briquet described what became known as Briquet's syndrome (somatisation, hysteria); he was not the psychoanalytic heir nicknamed the French Freud."}}, {"q": "The twenty-third pair of chromosomes is missing an X, turning into a syndrome characterised by a short, infertile female:", "concept": "The answer is Turner's syndrome. Humans normally carry 23 pairs of chromosomes, and the twenty third pair determines sex, XX in females and XY in males. Turner syndrome arises when a female is missing all or part of one X chromosome, giving the karyotype 45,X (a single X with no second sex chromosome). The phenotype the question describes, a short, infertile female, is the hallmark: affected girls show short stature, gonadal dysgenesis with non functioning streak ovaries leading to infertility and absent or incomplete puberty, a webbed neck, low hairline, broad chest, and often cardiac and renal anomalies. Cognitively, intelligence is usually in the normal range, but there is a characteristic profile of relatively weak visuospatial and arithmetic ability with preserved verbal skills. Contrast this with the other sex chromosome conditions to keep them straight: an extra X in a male gives 47,XXY, Klinefelter syndrome, producing tall, often infertile males. The key exam discriminator is the word missing combined with female and short and infertile, which points specifically to the single X, 45,X picture of Turner syndrome. Remembering that Turner is the loss of an X in a female and Klinefelter is the gain of an X in a male prevents the most common mix up on this item.", "traps": {"a": "Down syndrome is trisomy 21, an extra autosome, not a missing sex chromosome, and it presents with intellectual disability and characteristic facial features in both sexes.", "b": "Asperger's syndrome is a former diagnostic label for an autism spectrum presentation with no chromosomal definition and no sex chromosome loss.", "d": "Klinefelter's syndrome is the opposite pattern, an extra X (47,XXY) in a tall, infertile male, not a missing X in a short female."}}, {"q": "The fact that people can use later experiences to compensate for earlier deficits is a contradiction of which element of earlier developmental psychology?", "concept": "The answer is critical periods. A critical period is a rigidly bounded window of time during which a particular experience must occur for normal development to proceed; if the window closes without the right input, the capacity is said to be permanently lost and no later experience can fully repair the deficit. The classic example is Konrad Lorenz's imprinting in geese, and Hubel and Wiesel's work on the visual cortex, where depriving a kitten of patterned vision during a fixed early window caused lasting blindness. The very strong claim of the critical period idea is irreversibility. So the observation that humans can use later, enriching experiences to compensate for and partly overcome earlier deprivation directly contradicts the strict critical period notion, because it shows that the door has not slammed shut forever. This evidence is exactly why modern developmental psychology largely replaced the term critical period with the softer concept of a sensitive period, a window during which the organism is especially responsive to certain input but which does not permanently foreclose later learning. The deeper lesson for the exam is the contrast between a deterministic, all or nothing view of timing and a probabilistic, plasticity friendly view: brains remain capable of reorganisation, so the capacity for catch up growth and recovery is the empirical fact that undermines the original critical period dogma.", "traps": {"b": "Continuity refers to whether development is gradual and quantitative versus stage like; compensating for early deficits is about reversibility of timing, not the smoothness of change.", "c": "Sensitive periods is the concept that already accommodates later compensation, so catch up does not contradict it; it actually fits, which is why it is not the contradicted element.", "d": "Stability concerns whether traits persist across the lifespan, a separate continuity issue, not the time bounded irreversibility being challenged here."}}, {"q": "'Healing and Persuasion' is the work of:", "concept": "The keyed answer is Jerome Frank, the American psychiatrist whose book Persuasion and Healing (first published 1961, the question phrases it as Healing and Persuasion) is one of the most influential analyses of what makes all psychotherapies work. Frank argued that the many competing schools of therapy share common ingredients rather than owing their success to their specific techniques. He proposed that every form of healing, from shamanic ritual to modern psychotherapy, contains four shared features: an emotionally charged, confiding relationship with a helping person; a healing setting that carries social sanction; a rationale or myth that provides a plausible explanation for the patient's distress; and a ritual or procedure that both believe will restore health. The unifying mechanism, in Frank's view, is the remoralization of a demoralized person, the restoration of hope and a sense of mastery. This anticipated what we now call the common factors model of psychotherapy and the placebo or expectancy literature, and it directly informs debates about whether specific techniques outperform the therapeutic alliance. For an entrance exam this is a classic name and book pairing, and the deeper point is that Frank reframed therapy outcome as a question of shared persuasive and relational processes rather than rival doctrines.", "traps": {"a": "Alfred Pritz is an Austrian psychotherapy figure associated with the World Council for Psychotherapy and the professionalisation of the field, not the author of Persuasion and Healing.", "c": "Charles Winnicot is a distractor; the real Donald Winnicott was a British object relations analyst known for the good enough mother and transitional objects, not this book.", "d": "Jeff (Gerald) Klerman, with Weissman, developed Interpersonal Psychotherapy for depression, a specific manualised treatment, not the common factors thesis of this work."}}, {"q": "False belief which cannot be shaken by reason is termed as:", "concept": "A false belief that cannot be shaken by reason is a delusion, so the answer is b. A delusion is a fixed, false belief held with absolute conviction, out of keeping with the person's social, cultural, and educational background, and not amenable to correction by logical argument or contradictory evidence. It is a disorder of thought content, in contrast to disorders of thought form or stream. The defining features for the exam are three: the belief is false, it is firmly held despite proof to the contrary, and it is not a shared cultural or religious belief. Delusions come in recognisable types, including persecutory (being plotted against), grandiose (inflated worth or power), delusion of reference (neutral events are personally significant), nihilistic, somatic, and delusions of control, and they are a hallmark of psychotic disorders such as schizophrenia and delusional disorder, though they can occur in mood disorders and organic states too. The crucial discriminator in this question is the phrase cannot be shaken by reason, which captures the imperviousness to argument that distinguishes a delusion from a mere mistaken idea or an overvalued idea. It is also important to separate a delusion, a disorder of belief, from an illusion or hallucination, which are disorders of perception.", "traps": {"a": "An illusion is a misperception of a real external stimulus, a perceptual error, not a false belief held against reason.", "c": "A hallucination is a perception without an external stimulus, again a disorder of perception rather than of belief.", "d": "A false memory is a distorted or fabricated recollection, a memory error, not a fixed false belief impervious to argument."}}, {"q": "A body of prior work related to a research problem is referred to as:", "concept": "The body of prior work related to a research problem is the literature, so the answer is c. In research methodology the literature means the accumulated published scholarship, theories, empirical studies, reviews, and findings that bear on a chosen topic. Surveying it is the literature review, an essential early step in any project. The literature review serves several functions: it establishes what is already known and what remains unknown so the researcher can locate a genuine gap; it prevents needless duplication of work already done; it sharpens the research question and hypotheses; it informs the choice of methods, measures, and design by showing what has worked or failed before; and it provides the theoretical framework that situates the new study within an ongoing scholarly conversation. A good review is critical and synthetic, not a mere list, weighing the quality and convergence of prior evidence. So when a question speaks of the existing body of prior work connected to a research problem, the standard methodological term is the literature. The exam point is to recognise this as basic research vocabulary and to associate it with the literature review as a defined stage of the research process.", "traps": {"a": "An archive is a repository of original records or documents; it is a place where material is stored, not the body of scholarly prior work on a problem.", "b": "A repository likewise denotes a storage location or database for files and data, not the synthesised corpus of prior research itself.", "d": "None of the above is wrong because literature is precisely the correct and standard term for the body of prior work."}}, {"q": "The backward digit span test, where participants must repeat a sequence of numbers in reverse order, is primarily used to assess which type of memory system?", "concept": "The answer is working memory because the backward digit span forces you not merely to hold information but to actively manipulate it, which is the defining function of working memory. The concept comes from Alan Baddeley and Graham Hitch, who in 1974 replaced the older idea of a single passive short-term store with a multi-component working memory model. In their model the phonological loop temporarily holds verbal and acoustic material (the digits you hear), while a central executive directs attention and performs operations on that held material. Simply repeating digits forward taps mostly the phonological loop's storage capacity, but repeating them backward requires the central executive to hold the string, reverse its order, and output it, which is why backward span is a purer measure of working memory than forward span. This is why clinicians and intelligence tests such as the Wechsler scales include digit span backward as a working memory index. The key exam distinction is manipulation versus passive holding: any task that asks you to transform, reorder, or compute on information you are actively keeping in mind is tapping working memory, not long-term storage, sensory registration, or automatic procedural skills.", "traps": {"a": "Long-term memory is the durable, consolidated store of facts and experiences; reversing a just-heard digit string tests active online manipulation, not retrieval from long-term storage.", "c": "Sensory memory is the very brief, passive registration of raw stimuli (iconic or echoic traces lasting under a second or two), whereas this task requires deliberately holding and reordering numbers.", "d": "Procedural memory stores motor skills and habits performed automatically, such as riding a bike, and has nothing to do with the conscious reordering of numbers."}}, {"q": "In the WAIS-IV (Wechsler Adult Intelligence Scale - Fourth Edition), how many core subtests are there in the Verbal Comprehension Index and the Perceptual Reasoning Index respectively?", "concept": "The answer is three verbal and three perceptual because the WAIS-IV, published by Pearson in 2008 and descended from David Wechsler's original adult scale of 1955, organises its subtests into four index scores, two of which are the Verbal Comprehension Index and the Perceptual Reasoning Index. The Verbal Comprehension Index has three core subtests: Similarities (identifying how two concepts are alike), Vocabulary (defining words), and Information (general knowledge questions). The Perceptual Reasoning Index also has three core subtests: Block Design (arranging blocks to match a pattern), Matrix Reasoning (completing a visual pattern), and Visual Puzzles (selecting pieces that reconstruct a shape). Each index additionally has supplemental subtests that can substitute for a spoiled core subtest, but the core count is three and three. Wechsler's key innovation, worth knowing, was replacing the single ratio IQ (William Stern, 1912) with a deviation IQ that compares a person to same-age peers on a scale with a mean of 100 and a standard deviation of 15, and splitting intelligence into separately interpretable domains rather than one global number. The other two WAIS-IV indices are Working Memory and Processing Speed. For the exam, simply memorise that both the Verbal Comprehension and Perceptual Reasoning indices rest on three core subtests each.", "traps": {"a": "This wrongly gives four core perceptual subtests; the Perceptual Reasoning Index has three core subtests, not four.", "c": "This inflates the Verbal Comprehension Index to four core subtests, but it actually has three core subtests.", "d": "This both undercounts verbal (it is three, not two) and overcounts perceptual (it is three, not four)."}}, {"q": "A \"Sociogram\" is a primary tool used in sociometry to measure:", "concept": "The answer is social distance and patterns of choice within a group because a sociogram is the graphic tool of sociometry, the method developed by Jacob Levy Moreno (also known for founding psychodrama) in the 1930s to study the structure of social relationships in groups. Sociometry works by asking each member of a group a choice question, such as whom they would most like to sit with, work with, or invite to a party, and, sometimes, whom they would least prefer. These stated preferences and rejections are then plotted as a diagram in which each person is a point (a node) and each choice is an arrow (a line) pointing from the chooser to the chosen. Reading the resulting sociogram reveals the informal social structure that formal organisation charts hide: who the 'stars' are (individuals chosen by many), who the isolates or neglectees are (chosen by no one), who forms mutually chosen pairs or cliques, and how socially close or distant members are from one another. It is widely used in classrooms, teams, and therapy groups to understand cohesion, popularity, and rejection. The key idea is that a sociogram measures interpersonal attraction and repulsion, that is, patterns of choice and social distance, not intelligence, individual personality, or economics. That makes option b the correct definition.", "traps": {"a": "IQ scores are measured by individual intelligence tests, not by a sociogram, which maps interpersonal relationships rather than cognitive ability.", "c": "A sociogram charts the web of relationships across a whole group; it does not assess the personality traits of a single individual such as a leader.", "d": "Economic status is captured by socioeconomic indices and surveys, not by a diagram of social choices within a group."}}, {"q": "In psychoanalytic theory, what term describes the mental representation of psychic energy being invested or attached to a particular object, person, or idea?", "concept": "The answer is cathexis because in Sigmund Freud's economic model of the mind, cathexis is the specific term for the investment of psychic energy (libido) into a mental representation of an object, person, activity, or idea. Freud borrowed an economic metaphor: the mind has a limited quantity of psychic energy that it can allocate, and when we love, desire, or become preoccupied with something, we are cathecting energy onto it. The German word Freud used was Besetzung (occupation or filling), which his English translator James Strachey rendered with the Greek-derived 'cathexis'. Withdrawing that energy is called decathexis or anticathexis, and Freud used this idea to explain phenomena such as grief, where the painful work of mourning is the slow withdrawal of cathexis from a lost loved one. It is essential to separate the fuel from the act of investing it: libido is the energy, cathexis is the process of directing that energy at a target. This distinguishes it cleanly from fixation, which is energy trapped at a developmental stage, and from sublimation, which is a defence that redirects forbidden impulses into acceptable outlets. When an exam item says 'investment or attachment of psychic energy to an object', the answer is always cathexis.", "traps": {"a": "Libido is the psychic energy itself, the fuel, not the act of attaching that energy to a specific object as the question defines.", "c": "Fixation is libido becoming stuck or arrested at a particular psychosexual stage due to over- or under-gratification, not the general process of investing energy in an object.", "d": "Sublimation is a mature defence mechanism that channels unacceptable urges into socially valued activities, not the concept of energy investment."}}, {"q": "In Phenylketonuria (PKU), the body fails to convert phenylalanine into which substance due to a deficiency of phenylalanine hydroxylase?", "concept": "The answer is tyrosine because Phenylketonuria is caused by a deficiency of the enzyme phenylalanine hydroxylase, whose normal job is to convert the amino acid phenylalanine into the amino acid tyrosine. PKU is an inherited autosomal recessive metabolic disorder, first described by the Norwegian physician Asbjorn Folling in 1934. When the enzyme is missing or faulty, phenylalanine cannot be broken down, so it accumulates to toxic levels in the blood and brain, while tyrosine becomes deficient. The excess phenylalanine and its abnormal breakdown products (phenylketones) are neurotoxic and, if untreated from birth, cause severe intellectual disability, seizures, and behavioural problems, which is exactly why newborns are screened for PKU with a heel-prick blood test. The tyrosine link matters for psychology because tyrosine is itself the precursor for the catecholamine neurotransmitters dopamine, norepinephrine, and epinephrine, as well as for the pigment melanin, which is why untreated PKU patients often have lighter hair and skin. Treatment is a strict low-phenylalanine diet. For the exam, remember the single reaction: phenylalanine, via phenylalanine hydroxylase, becomes tyrosine, and PKU is what happens when that arrow is broken.", "traps": {"a": "Urea is the nitrogen-containing waste product excreted by the urea cycle in the liver; it is unrelated to the phenylalanine hydroxylase reaction blocked in PKU.", "c": "Tryptophan is a separate essential amino acid and the precursor of serotonin; it is not the product that phenylalanine is converted into.", "d": "Histidine is another amino acid entirely and plays no role in the phenylalanine-to-tyrosine metabolic pathway that is disrupted in PKU."}}, {"q": "According to Erik Erikson's psychosocial development theory, a child who is 1.5 years old (18 months) would be in which developmental stage?", "concept": "The answer is Autonomy vs. Shame and Doubt because in Erik Erikson's eight-stage theory of psychosocial development this stage spans approximately 18 months to three years, the toddler period, so a child of 18 months is entering it. Erikson, a psychoanalyst who extended Freud's ideas across the entire lifespan rather than stopping in adolescence, proposed that each stage presents a central psychosocial crisis, a tension the person must resolve, and that healthy resolution yields a specific virtue or strength. In the autonomy stage the toddler is developing physical skills such as walking, grasping, feeding, and, importantly, toilet training, and is driven to do things independently and assert their own will. If caregivers encourage and patiently support this budding independence, the child develops autonomy and the virtue of will; if caregivers are overly controlling, critical, or shaming of the child's failed attempts, the child instead develops shame and self-doubt about their abilities. The preceding stage, Trust vs. Mistrust (birth to about 18 months), is where the infant learns whether the world and caregivers are reliable. For the exam, anchor the early ages: 0 to 18 months is trust, 18 months to 3 years is autonomy, so 18 months sits at the boundary that the question maps onto the autonomy stage.", "traps": {"a": "Trust vs. Mistrust is the infancy stage covering roughly birth to 18 months; at 18 months the child is right at the transition into the next stage.", "c": "Initiative vs. Guilt is the preschool play-age stage of about three to six years, well beyond an 18-month-old.", "d": "Industry vs. Inferiority is the school-age stage of roughly six to twelve years, far too advanced for a toddler."}}, {"q": "In Dialectical Behavior Therapy (DBT), the \"core mindfulness\" skills are primarily derived from which tradition?", "concept": "The answer is Zen Buddhism because Marsha Linehan, the psychologist who developed Dialectical Behavior Therapy in the late 1980s, explicitly drew DBT's core mindfulness skills from Zen Buddhist practice, which she had studied personally. DBT was originally created to treat chronically suicidal patients and people with borderline personality disorder, populations for whom standard cognitive-behavioural therapy alone was insufficient. Its central innovation is the dialectic between acceptance and change: patients need to accept themselves and their present reality (the acceptance pole) while also working to change harmful behaviours (the change pole). Mindfulness supplies the acceptance side and is considered the foundational skill module on which the others rest. From Zen, Linehan took the practices of observing, describing, and participating in the present moment fully, and of doing so non-judgmentally, one-mindfully, and effectively, culminating in the concept of Wise Mind, the balanced integration of the emotional mind and the reasonable mind. It is worth distinguishing the two philosophical lineages that feed modern therapies: cognitive therapy (Beck and Ellis) traces its intellectual roots to Stoic philosophers like Epictetus who argued we are disturbed not by events but by our judgments of them, whereas DBT's mindfulness component traces to Zen Buddhism. So when an exam links DBT mindfulness to a tradition, the answer is Zen Buddhism.", "traps": {"a": "Stoicism is the philosophical root of cognitive therapy's reframing of thoughts, not the source of DBT's mindfulness practices.", "c": "Psychoanalysis focuses on uncovering unconscious conflicts and early experience, not on present-moment, non-judgmental awareness training.", "d": "Existentialism deals with meaning, freedom, and responsibility in life; it is not the contemplative tradition behind DBT's mindfulness skills."}}, {"q": "A patient presents with a fixed delusional belief that their spouse is being unfaithful, despite having no evidence. This specific form of delusional jealousy is known as:", "concept": "The answer is Othello syndrome because it is the specific name for delusional jealousy, a fixed, unshakeable belief that one's partner is being unfaithful, held with delusional intensity despite the complete absence of real evidence. The name comes from Shakespeare's Othello, who is manipulated into believing his faithful wife Desdemona has betrayed him and murders her out of that jealousy. In psychiatry this is a monothematic delusion, meaning the person can be entirely rational about everything else in life yet holds this one impenetrable false belief. Sufferers often gather 'proof' by checking phones, following the partner, or examining clothing, and the condition carries real forensic risk because morbid jealousy can drive violence. It is important to distinguish it from the three misidentification-type delusions in the options. Capgras (impostor double), Fregoli (one persecutor in many faces), and De Clerambault's erotomania (someone is in love with me) all involve false beliefs about identity or affection, but only Othello centres on infidelity. A useful memory hook: link each eponym to its single sentence, Othello equals jealousy, Capgras equals impostor, Fregoli equals disguise, De Clerambault equals someone loves me, so the exam cue word 'unfaithful spouse' instantly points to Othello.", "traps": {"a": "Capgras syndrome is the delusion that a familiar person has been secretly replaced by an identical impostor or double, a misidentification delusion, not a belief about a partner's infidelity.", "c": "Fregoli syndrome is the delusion that a single persecutor is disguising themselves as many different people the patient meets, another misidentification delusion, not jealousy.", "d": "De Clerambault's syndrome is erotomania, the delusion that another person (often of higher status) is secretly in love with you, which is the reverse of suspicious jealousy."}}, {"q": "When data is assumed to be normally distributed and meets the assumptions of equal variances, which category of statistical tests is most appropriate to use?", "concept": "The answer is parametric tests because that entire family of tests rests on specific assumptions about the underlying population, chief among them that the data are drawn from a normal distribution, that the groups being compared have roughly equal variances (homogeneity of variance or homoscedasticity), and that the data are measured at the interval or ratio level. When those conditions are satisfied, parametric tests are preferred because they use the actual numerical values (means and standard deviations) rather than just ranks, which gives them greater statistical power, meaning a better chance of detecting a true effect. The classic parametric tests are the t-test (for comparing one or two means), analysis of variance or ANOVA (for comparing three or more means), and Pearson's correlation coefficient (for the linear relationship between two continuous variables). The logic is that once you can assume normality, you can rely on known mathematical properties of the normal curve to calculate probabilities. The contrasting family, non-parametric or distribution-free tests such as Mann-Whitney U, Wilcoxon, and Kruskal-Wallis, makes no such normality assumption and works with ranks, which you fall back on when data are skewed, ordinal, or the samples are very small. For the exam, the trigger phrase 'normally distributed with equal variances' should immediately signal parametric.", "traps": {"a": "Non-parametric tests are specifically designed for data that violate normality assumptions or are ordinal, which is the opposite of the well-behaved normal data described here.", "c": "Chi-square tests analyse categorical frequency counts and independence, not normally distributed continuous data with equal variances.", "d": "Distribution-free is simply another name for non-parametric tests, so it applies precisely when normality cannot be assumed, not when it holds."}}, {"q": "In Baddeley's model of working memory, the subsystem responsible for integrating information from the phonological loop, visuospatial sketchpad, and long-term memory into a single, coherent episode is the:", "concept": "The answer is the episodic buffer, because in Alan Baddeley's model of working memory the episodic buffer is precisely the component whose job is to integrate information from the phonological loop, the visuospatial sketchpad, and long-term memory into a single, coherent, multimodal episode. Understand the model's development. Baddeley and Graham Hitch proposed working memory in 1974 to replace the passive short-term store of the earlier Atkinson-Shiffrin model, arguing that short-term memory is an active workspace with multiple components. The original model had three parts: the central executive, an attention-like controller with limited capacity that directs processing and coordinates the two slave systems; the phonological loop, which holds and rehearses speech-based and acoustic information (its subparts being the phonological store and the articulatory rehearsal process); and the visuospatial sketchpad, which holds and manipulates visual and spatial imagery. A problem became apparent over time: how do we experience a unified scene that binds sound, sight, and stored knowledge together, and where is information held while being combined? To solve this, Baddeley added a fourth component in 2000, the episodic buffer, a limited-capacity system controlled by the central executive that binds information from the two slave systems and from long-term memory into integrated, coherent episodes, acting as a temporary interface. The stem's exact wording, integrating the loop, sketchpad, and long-term memory into a single coherent episode, is the definition of the episodic buffer, so that is the answer, and the key name to attach is Alan Baddeley.", "traps": {"a": "The central executive is the attentional control system that allocates resources and coordinates the subsystems, but it does the directing rather than the actual binding and storage of an integrated multimodal episode.", "c": "The visuospatial sketchpad is a slave system that holds and manipulates only visual and spatial information, so it cannot integrate verbal, visual, and long-term memory contents together.", "d": "The phonological loop is a slave system dedicated to verbal and acoustic information, storing and rehearsing sound-based material, so it too handles only one modality rather than binding across them."}}, {"q": "A 10-year-old child from a rural area, with no formal schooling, is brought for an intellectual assessment due to academic struggles. The child is illiterate and has had minimal exposure to formal testing materials. Which of the following tests would be the MOST appropriate to use to minimize cultural and educational bias?", "concept": "The answer is Bhatia's Battery of Performance Tests of Intelligence, because for an illiterate, unschooled child it minimizes cultural and educational bias by relying on nonverbal performance tasks rather than language or academic knowledge. Understand the principle at stake, which is the distinction between verbal and performance (nonverbal) measures of intelligence and the problem of test bias. Any intelligence test that depends on reading, vocabulary, general information, or arithmetic taught in school will systematically underestimate the ability of a child who has had no formal education and cannot read, not because the child is less intelligent but because the test measures acquired schooling rather than underlying reasoning; this is cultural and educational bias, a threat to validity. Performance tests sidestep this by assessing reasoning through hands-on, nonverbal tasks such as assembling blocks, completing patterns, or manipulating objects, which do not require literacy or culturally specific verbal knowledge. Bhatia's battery, developed by C. M. Bhatia in 1955 specifically for the Indian population, is a set of five performance subtests (including Koh's block design, Alexander's pass-along, pattern drawing, immediate memory, and picture construction) designed to be usable with illiterate and rural children by minimizing verbal and educational demands. Because the vignette emphasizes illiteracy, no schooling, and minimal exposure to formal testing, the appropriate choice is the purely performance-based, Indian-standardized Bhatia's battery. The distractors, WISC-IV, Stanford-Binet (Lewis Terman, 1916), and even the Indian MISIC, all include verbal components and presuppose schooling, so they carry more bias, making Bhatia's the best answer.", "traps": {"b": "The WISC-IV is a Wechsler scale that relies heavily on verbal subtests and assumes familiarity with formal testing and language, making it culturally and educationally loaded and unsuitable for an illiterate, unschooled child.", "c": "The Stanford-Binet is a Western-developed, verbally weighted intelligence test standardized on other populations, so it carries substantial cultural and educational bias for a rural, illiterate Indian child.", "d": "Malin's Intelligence Scale for Indian Children (MISIC) is an Indian adaptation of the Wechsler scale but still contains verbal subtests and presupposes some schooling and language competence, so it remains less suitable than a purely performance-based battery for an illiterate child."}}, {"q": "The \"halo effect\" is a cognitive bias in which:", "concept": "The answer is that a person's overall impression of another influences ratings of specific traits, because that is the precise definition of the halo effect. Understand the concept and its history. The halo effect is a cognitive bias in impression formation, first documented empirically by Edward Thorndike in 1920, who noticed that military officers rating their soldiers tended to rate a soldier who was physically impressive as also more intelligent, loyal, and skilled, as though one good quality cast a halo over all the others. The mechanism is that a single salient global evaluation, often based on one striking attribute such as attractiveness, likeability, or competence, biases our judgments of that person's unrelated specific traits in the same direction. If we find someone physically attractive, we tend to infer they are also kinder, smarter, and more trustworthy, an instance sometimes called the what-is-beautiful-is-good stereotype. The bias runs in the negative direction too, sometimes called the horn effect, where one bad impression drags down ratings of unrelated qualities. The halo effect matters practically because it contaminates job interviews, performance appraisals, and teacher evaluations, undermining the validity of ratings, and it partly explains why structured, criterion-based assessment is preferred over global impressions. The exam signal is any wording about a global or overall impression spreading to influence specific, separate trait judgments, which is exactly option a, distinguishing it from the self-serving bias, false consensus, and anchoring described in the other options.", "traps": {"b": "Taking credit for success but blaming external factors for failure describes the self-serving bias, an attributional bias protecting self-esteem, not the halo effect.", "c": "Overestimating how much others share one's opinions describes the false consensus effect (Lee Ross and colleagues, 1977), a distinct social-cognitive bias about perceived agreement, not a global impression coloring trait ratings.", "d": "The idea that an initial impression anchors all subsequent judgments describes the anchoring effect (or a primacy effect), which concerns numerical or sequential anchoring rather than one overall impression spreading to specific traits."}}, {"q": "The \"D-type\" personality, identified as a risk factor for poor prognosis in cardiovascular disease, is characterized by:", "concept": "The answer is the joint tendency to experience negative emotions and to inhibit self-expression in social situations, because the Type D or distressed personality is defined precisely by the combination of negative affectivity and social inhibition. Understand the construct and its clinical significance. The Type D personality was introduced by the Belgian psychologist Johan Denollet in the 1990s within the field of health psychology, and the D stands for distressed. It is defined by the co-occurrence of two stable traits. The first is negative affectivity, the tendency to experience negative emotions across time and situations, including worry, irritability, gloom, tension, and a generally dysphoric view of oneself and the world. The second is social inhibition, the tendency to inhibit the expression of these emotions and behaviors in social interactions, out of fear of disapproval or rejection, so the person feels tense, insecure, and reticent around others and keeps their distress bottled up. It is the combination of both, feeling a lot of distress and simultaneously suppressing it socially, that constitutes Type D. Denollet's research showed that Type D personality is an independent predictor of poor prognosis in patients with established cardiovascular disease, associated with higher rates of cardiac events, mortality, and poorer quality of life, likely mediated by chronic stress physiology, poor health behaviors, and reduced help-seeking. It is important to distinguish Type D from the older Type A pattern (Friedman and Rosenman's hostile, competitive, time-urgent pattern) and Type C (the cancer-prone, emotion-suppressing pattern). The defining features of Type D are negative affectivity plus social inhibition.", "traps": {"a": "Hostility and competitiveness are the hallmarks of the Type A behavior pattern, a different personality construct linked to coronary risk, not the defining features of Type D.", "c": "An optimistic and resilient outlook is protective against disease and is essentially the opposite of the negative-affect, socially inhibited Type D profile.", "d": "Perfectionism and rigidity describe obsessive or Type A-adjacent traits, not the combination of negative affectivity and social inhibition that defines the Type D (distressed) personality."}}, {"q": "A patient presents with severe memory deficits, confabulation, and nystagmus, with a history of chronic alcohol use. This clinical picture is classic for:", "concept": "The answer is Wernicke-Korsakoff syndrome, because the combination of severe memory deficits, confabulation, and nystagmus in a chronic drinker is the textbook presentation of thiamine (vitamin B1) deficiency damaging the brain. Learn the mechanism and structure of the disorder. Chronic alcohol use causes thiamine deficiency through poor diet, impaired absorption, and reduced storage, and thiamine is essential for glucose metabolism in neurons, so its lack injures brain regions with high metabolic demand, particularly the mammillary bodies, the medial thalamus (dorsomedial nucleus), and periaqueductal gray. The syndrome has two linked phases. Wernicke's encephalopathy is the acute, potentially reversible emergency defined by a classic triad: confusion (an acute encephalopathy), ataxia (unsteady gait), and ocular abnormalities such as nystagmus and ophthalmoplegia. If untreated with urgent thiamine, it can progress to Korsakoff's psychosis, a chronic, largely irreversible amnestic disorder marked by profound anterograde amnesia, some retrograde amnesia, and confabulation, the unintentional filling of memory gaps with fabricated but plausible material without intent to deceive. The stem's mixture of the eye sign (nystagmus, from the acute Wernicke phase) with memory loss and confabulation (from the chronic Korsakoff phase) is why the combined eponym Wernicke-Korsakoff is correct. The clinical teaching point examiners reward is that thiamine must be given before glucose in a suspected case, and the pathognomonic cue in any vignette is the pairing of an alcohol history with confabulation and eye-movement abnormality.", "traps": {"a": "Alzheimer's disease produces gradual, progressive memory and cognitive decline driven by amyloid and tau pathology, not the acute triad of confabulation, nystagmus, and an alcohol history seen here.", "c": "Vascular dementia arises from strokes or chronic cerebrovascular disease and typically shows a stepwise decline with focal neurological signs, not the thiamine-deficiency picture described.", "d": "Frontotemporal dementia affects the frontal and temporal lobes causing early personality, behavior, or language change, which does not match the eye-movement abnormality and alcohol-related amnesia here."}}, {"q": "According to the Thomas and Chess model of temperament, a child who is generally negative in mood, slow to adapt to new situations, and has irregular biological rhythms (e.g., sleep, hunger) would be classified as:", "concept": "The answer is difficult temperament, because the trio of features named (negative mood, slow adaptation, and irregular biological rhythms) is the textbook signature of the difficult child in the Thomas and Chess model. Understand the theory from its foundation. Alexander Thomas and Stella Chess launched the New York Longitudinal Study in the 1950s and argued, against the then-dominant view that infants are blank slates shaped only by parenting, that babies show stable, biologically based behavioral styles from birth. They rated infants on nine dimensions, including activity level, rhythmicity (regularity of sleep and hunger), approach or withdrawal to new stimuli, adaptability, intensity of reaction, mood quality, and distractibility. Clustering these, they described three broad types. The easy child (about 40 percent) has regular rhythms, positive mood, and adapts readily. The difficult child (about 10 percent) has irregular rhythms, withdraws from novelty, adapts slowly, reacts intensely, and shows frequent negative mood, exactly the profile in the stem. The slow-to-warm-up child (about 15 percent) is a milder mix, cautious and slow to adapt but with low-intensity reactions rather than stormy negativity, with the rest unclassified. Their most influential idea was goodness of fit: development goes well when parenting matches the child's temperament. The exam clue for difficult temperament is the combination of negative mood plus irregular rhythms plus slow adaptation, and note that attachment categories are a separate framework never to be confused with temperament types.", "traps": {"a": "Easy temperament describes children with generally positive mood, regular biological rhythms and quick, comfortable adaptation to new situations, the direct opposite of this profile.", "c": "Slow-to-warm-up children show mild-intensity, cautious withdrawal from novelty and gradual adaptation, but they lack the pronounced negative mood and markedly irregular biological rhythms that define the difficult pattern.", "d": "Insecure attachment is a Bowlby-Ainsworth relationship classification based on responses to separation and reunion, not a temperament category, so it belongs to a different theoretical framework entirely."}}, {"q": "While on your clinical placement as a trainee, a client discloses that their previous therapist (from a different organization) frequently made inappropriate sexual comments and breached confidentiality. As a trainee psychologist, your FIRST and MOST appropriate course of action should be to:", "concept": "The answer is to discuss the matter with your clinical supervisor, because the universally taught first step in any ethical dilemma faced by a trainee is consultation within the supervisory relationship. Build the reasoning from the structure of ethical decision-making models, such as the one popularized in Kenneth Pope and Melba Vasquez's ethics texts: identify the problem, consult the relevant codes and experienced colleagues, consider the options and their consequences, then act and document. A trainee, by definition, practices under supervision; the supervisor holds clinical and legal responsibility for the trainee's cases, so serious disclosures must flow upward before any external action is taken. Consultation is not passive buck-passing. It protects the client, because the supervisor can help weigh confidentiality against any duty to report; it protects the client's autonomy, because the client's wishes about pursuing a complaint must be explored; and it protects the trainee from well-intentioned but harmful improvisation. The wrong options each break a core principle: going straight to the police may violate confidentiality without consent, confronting the accused therapist personally has no professional standing and could contaminate any future inquiry, and telling the client to forget it commits the worst error of all, invalidating an abuse disclosure. On any exam question that says trainee plus ethical dilemma, the reflex answer is consult the supervisor first.", "traps": {"a": "Immediately filing a police complaint skips the professional chain of accountability, may breach the client's confidentiality without consent, and is not the trainee's unilateral first move before consultation.", "b": "Confronting the previous therapist directly is a boundary violation for a trainee, risks the client's confidentiality, and bypasses every formal mechanism for handling professional misconduct.", "d": "Advising the client to forget the past dismisses a serious disclosure of abuse, invalidates the client, and abandons the ethical duty to address potential ongoing risk from a misconducting professional."}}, {"q": "Expressed Emotion (EE) is a significant predictor of relapse in schizophrenia. Which of the following is NOT one of the three core dimensions of high Expressed Emotion?", "concept": "The answer is warmth and positive regard, because Expressed Emotion is a construct about negative, over-charged family attitudes, and warmth is not one of its three high-EE dimensions. Learn the concept from its origins: George Brown and colleagues in Britain during the 1960s and 1970s, later refined with the Camberwell Family Interview by Christine Vaughn and Julian Leff, observed that patients with schizophrenia returning to families high in certain emotional attitudes relapsed far more often than those returning to low-EE homes, even controlling for illness severity. Expressed Emotion measures the emotional climate a key relative shows toward the patient, and high EE is defined by three components: critical comments (statements of disapproval or resentment about the patient's behavior), hostility (generalized rejection or blame directed at the person rather than specific behaviors), and emotional over-involvement (overprotectiveness, self-sacrifice, exaggerated emotional responses, and intrusive concern). High EE on any of these predicts relapse and now guides family psychoeducation interventions designed to lower it. Warmth and positive remarks are actually assessed in the interview as separate, generally protective dimensions, so they are the opposite of high EE, which is precisely why they are the correct exception here. The exam hook: high EE equals criticism, hostility, and over-involvement, three negatives; anything positive, like warmth, is never a high-EE dimension.", "traps": {"a": "Hostility is genuinely one of the three core high-EE dimensions, so it cannot be the exception the question asks for.", "b": "Critical comments are the most frequently measured of the three high-EE dimensions, so this is a defining feature rather than the odd one out.", "c": "Emotional over-involvement, meaning excessive self-sacrifice, overprotection or dramatic distress about the patient, is the third core high-EE dimension and therefore belongs to the construct."}}, {"q": "In a cohort study investigating the association between a new psychological intervention and relapse rates in schizophrenia, the risk ratio is calculated as 1.0. This finding indicates that:", "concept": "The answer is that there is no difference in risk, because a risk ratio, also called relative risk, is a simple division: the incidence of the outcome in the exposed group divided by the incidence in the unexposed group. If relapse occurs in 20 percent of the intervention group and 20 percent of the control group, the calculation is 0.20 divided by 0.20, which equals exactly 1.0. Whenever a ratio of two numbers equals 1, the numerator and denominator must be the same, so a risk ratio of 1.0 is the null value: exposure makes no difference to the outcome. To interpret any risk ratio on an exam, anchor yourself to this benchmark. Values above 1.0 mean the exposure increases risk (a risk ratio of 2.0 means the exposed group has double the risk), and values below 1.0 mean the exposure is protective (0.5 means half the risk). This measure comes from the cohort tradition of epidemiology, where you follow exposed and unexposed groups forward in time and directly measure incidence, which is why the risk ratio is the natural statistic for cohort studies and randomized trials, while case-control studies must instead use the odds ratio because they cannot measure incidence directly.", "traps": {"a": "A doubled incidence of relapse in the exposed group would give a risk ratio of 2.0, not 1.0, so this option describes a strong harmful association rather than the null value.", "b": "A significant protective effect would require a risk ratio meaningfully below 1.0 (for example 0.5), because protection means the exposed group relapses less often than the unexposed group.", "d": "Equal odds of exposure among cases and non-cases describes an odds ratio of 1.0 from a case-control design, which is a related but different measure computed from a different study logic than the risk ratio in a cohort study."}}, {"q": "Functionalism is how people work, play, and adapt to their surroundings. This viewpoint was given by:", "concept": "The answer is William James because functionalism, the school concerned with the purpose and adaptive function of mental processes, is most strongly associated with him in American psychology. To learn this properly, set functionalism against its rival, structuralism. Structuralism, founded by Wilhelm Wundt and carried to America by Edward Titchener, asked WHAT the mind is made of: it tried to break consciousness into its basic elements (sensations, feelings, images) using introspection, much like a chemist analyzing compounds into elements. Functionalism, led by William James (and developed at the University of Chicago by John Dewey and others), rejected that static dissection and asked instead WHY the mind works as it does, what mental processes are FOR, and how consciousness helps an organism adapt to and survive in its environment. This functional, purpose-focused view was heavily influenced by Darwin's theory of evolution and natural selection, since it framed mind and behavior as adaptive tools. James's 1890 textbook Principles of Psychology, with its idea of the stream of consciousness, embodied this approach. The question's phrasing, how people work, play, and adapt to their surroundings, is the functionalist emphasis on adaptation, which points to James. Beware the distractor Wundt: he is the father of experimental psychology and structuralism, not functionalism. Darwin inspired functionalism but was a naturalist, not a psychologist who founded the school. Watson founded behaviorism, which rejected the study of consciousness altogether.", "traps": {"b": "William Wundt founded experimental psychology and structuralism, which analyzed the contents of consciousness through introspection, the opposite emphasis from functionalism.", "c": "Charles Darwin's evolutionary theory inspired functionalism's focus on adaptation, but Darwin was a naturalist, not the founder of the functionalist school of psychology.", "d": "John B. Watson founded behaviorism, which rejected the study of consciousness entirely and focused on observable behavior, not the adaptive functions of mind."}}, {"q": "The Wechsler Adult Intelligence Scale can be used to assess eligibility for:", "concept": "The Wechsler Adult Intelligence Scale (WAIS) can be used to help assess eligibility for disability allowance, because establishing intellectual functioning is part of documenting a qualifying disability such as intellectual disability or cognitive impairment. The WAIS, originally developed by David Wechsler (the first version, the Wechsler-Bellevue, appeared in 1939, with the WAIS proper in 1955 and now in its fourth and fifth editions), is the most widely used individually administered adult intelligence test. It yields a Full Scale IQ along with index scores for verbal comprehension, perceptual reasoning, working memory, and processing speed. Because a diagnosis of intellectual disability requires demonstrating significantly subaverage intellectual functioning (roughly an IQ below 70) alongside deficits in adaptive behavior, a standardized IQ measure like the WAIS provides exactly the objective intellectual data that disability determinations require. The question is testing whether the student understands the practical, applied use of intelligence testing in clinical and medico-legal contexts: an IQ score can substantiate a claim for a disability benefit by quantifying cognitive limitation. The other options describe contexts where an adult intelligence test is either irrelevant or the wrong instrument entirely.", "traps": {"a": "Housing benefit is determined by income and financial need, not by intellectual functioning, so an IQ test is irrelevant to that decision.", "c": "Suicide risk is assessed through clinical interview and risk-screening instruments measuring mood, hopelessness, and intent, not through an intelligence test.", "d": "Special educational needs concern children and are assessed with child-focused tools; the WAIS is for adults (the WISC is the child version), so it does not fit this context."}}, {"q": "In Lewin's topological system, emphasis was placed on the study of 'life space,' which includes:", "concept": "The answer is Person and Psychological environment because Kurt Lewin defined the life space as exactly those two interacting elements. Lewin was a Gestalt-influenced social psychologist who created field theory, the idea that behavior must be understood as a function of the whole field of forces acting on a person at a given moment, not of isolated traits or stimuli. His famous formula is B = f(P, E): Behavior is a function of the Person and the Environment, taken together. The life space is his name for the total psychological reality that determines behavior at any instant: it consists of the person (P) plus the psychological environment (E), meaning the environment as it is perceived and experienced by that person, not the objective physical world. Lewin borrowed topology, a branch of mathematics dealing with spatial relationships and boundaries, to represent the life space as regions with boundaries, paths, barriers, and forces (valences) that push and pull the person toward or away from goals. The crucial nuance is that what matters is the psychological environment, the world as it exists for the individual, including their needs, goals, and perceptions, because that is what actually drives behavior. So the two components of the life space are the person and the psychological environment. The other options substitute group and society, which belong to broader social-level analyses, not to Lewin's definition of an individual's life space.", "traps": {"b": "Society and group are macro-level social units, not the two components Lewin specified for the individual's life space, which centers on the person and their perceived environment.", "c": "Person and group is incorrect because Lewin's life space pairs the person with the psychological ENVIRONMENT, not with the group.", "d": "Environment and group both omit the person, who is the essential first term of the life space in Lewin's B = f(P, E)."}}, {"q": "'Id' is to 'Just do it' as superego is to:", "concept": "The answer is 'Don't do it.' because the superego is the moralizing, prohibitive agency of Freud's structural model, and a blunt internal command forbidding an impulse is exactly how it operates. Freud's structural theory (introduced in 1923 in The Ego and the Id) divides the mind into three systems. The id is the oldest and most primitive, present from birth, a seething reservoir of instinctual drives (sex and aggression) that runs entirely on the pleasure principle: it wants immediate gratification with no regard for reality, logic, or morality, hence the 'Just do it' framing. The superego develops last, around ages three to five, as the child resolves the Oedipus complex and internalizes the moral standards, rules, and prohibitions of the parents and wider society. It has two parts: the conscience, which punishes violations with guilt and says 'don't,' and the ego ideal, which holds up standards of who we should be. The ego sits between them, operating on the reality principle, mediating the id's demands against the superego's prohibitions and the constraints of the external world. So the analogy maps the id's permissive 'do it' onto the superego's moral veto, 'Don't do it.' This is the most basic way to remember the superego: it is the internalized parental 'no,' the source of guilt and conscience.", "traps": {"a": "'Wait till later' describes delay of gratification, which is the work of the ego operating on the reality principle, not the superego's moral prohibition.", "b": "'Do your own thing' is a permissive, self-indulgent attitude that fits the id's pleasure-seeking, the opposite of the superego.", "d": "'Oh, sit on it' is a flippant distractor with no theoretical meaning in the structural model and does not capture the superego's moralizing function."}}, {"q": "Which brain structure would most likely result in death if damaged?", "concept": "The answer is the medulla because it houses the vital reflex centers that keep us alive automatically, and destroying it stops those functions abruptly. The medulla oblongata sits at the very bottom of the brainstem, where the brain joins the spinal cord. To learn this properly, organize the brainstem from bottom to top: medulla, then pons, then midbrain. The medulla contains the cardiac center (regulating heart rate), the respiratory center (driving breathing), and centers for vasomotor control (blood pressure), as well as reflexes like swallowing, coughing, sneezing, and vomiting. Because breathing and heartbeat are fundamentally controlled here and these cannot be consciously sustained if the control center is gone, damage to the medulla typically causes immediate respiratory and cardiac arrest, hence death. This is why brainstem strokes or trauma at this level are so often fatal, and why brainstem function is central to clinical definitions of brain death. Contrast this with structures that, while important, are not immediately life-ending if damaged: the cerebellum governs balance, coordination, and motor learning; damage causes ataxia and clumsiness, not death. The pons relays signals and helps regulate sleep and breathing rhythm, but the actual life-critical respiratory drive resides in the medulla. The reticular formation regulates arousal and consciousness; severe damage can cause coma, but it is the medulla's autonomic centers that most directly equal survival. Anchor the rule: medulla equals automatic life support, so its destruction equals death.", "traps": {"a": "The cerebellum controls balance, posture, and coordinated movement; its damage produces ataxia and motor incoordination, which is disabling but not directly lethal.", "c": "The reticular formation governs arousal and wakefulness; severe damage can cause coma or loss of consciousness, but it does not directly stop heartbeat and breathing the way the medulla does.", "d": "The pons relays information between cerebrum and cerebellum and assists sleep and breathing rhythm, but the core vital cardiac and respiratory centers are in the medulla, not the pons."}}, {"q": "Kohlberg studied moral development by:", "concept": "Kohlberg studied moral development by posing moral dilemmas to children and adolescents of different ages, which is why c is correct. Lawrence Kohlberg extended Piaget's work on moral judgement by using hypothetical dilemmas, the most famous being the Heinz dilemma, in which a man must decide whether to steal an unaffordable drug to save his dying wife. Crucially, Kohlberg was not interested in whether a person said Heinz should or should not steal the drug; he was interested in the reasoning behind the answer, because the same conclusion could be justified at very different levels of moral sophistication. From the patterns of justification he identified three broad levels, each with two stages. At the preconventional level, morality is based on consequences to the self: stage one is obedience and avoidance of punishment, stage two is instrumental self-interest and simple exchange. At the conventional level, morality rests on social approval and maintaining order: stage three is being a good person in the eyes of others, stage four is upholding law and duty. At the postconventional level, morality is grounded in abstract principles: stage five recognises social contracts and individual rights, stage six rests on universal ethical principles of justice. Kohlberg argued these stages are universal, sequential, and invariant in order. The method was therefore a cross-sectional and interview-based analysis of reasoning, not behaviour tracking, which is the key distinction the question tests.", "traps": {"a": "Having subjects keep a daily journal of their actions is a self-report behavioural diary method and was never Kohlberg's approach; he probed reasoning, not logged daily conduct.", "b": "Evaluating criminal and delinquent court records would study moral behaviour and its legal consequences, not the developmental reasoning processes Kohlberg was measuring.", "d": "Having subjects perform legal or illegal behaviours is an action-based experimental design that ignores reasoning entirely, which is exactly what Kohlberg's dilemma interviews were designed to capture."}}, {"q": "A parent deliberately ignores a child's temper tantrums in an attempt to discourage them. The parent's strategy is in accordance with:", "concept": "The source key marks this as operant escape, but the textbook-correct concept the question describes is extinction, so learn the concept properly and note the discrepancy. The scenario is a parent deliberately withholding any response (attention) to a behavior (tantrums) that was previously reinforced by that attention, in order to reduce the behavior. In operant conditioning (B. F. Skinner), when a behavior that has been maintained by reinforcement no longer produces that reinforcement, the behavior gradually weakens and disappears. That process is extinction. Crucially, ignoring an attention-seeking behavior is the textbook clinical example of extinction: the tantrum was being reinforced by parental attention, so removing the attention removes the reinforcer and the tantrum should fade (often after a temporary extinction burst). So conceptually the right answer is extinction. The source has marked operant escape (c), which describes something different: escape behavior is negatively reinforced behavior that terminates an aversive stimulus already present (for example, taking aspirin to end a headache). That does not match a parent passively ignoring a child. Because this question's wording maps cleanly onto extinction, you should learn it as an extinction item; if the answer key on the exam credits escape, it is an error in the key. For your understanding, distinguish the four: positive reinforcement adds a pleasant stimulus, negative reinforcement removes an aversive one, both increase behavior; extinction removes the maintaining reinforcer to decrease behavior; escape and avoidance are negative-reinforcement subtypes that increase behavior.", "traps": {"a": "Negative reinforcement INCREASES a behavior by removing an aversive stimulus; here the parent is trying to decrease the tantrum, not strengthen it, so this is the wrong process.", "b": "Extinction is actually the textbook-correct description of ignoring a previously reinforced behavior to weaken it; the source unusually keys (c), but conceptually (b) fits best.", "d": "Operant avoidance is a negative-reinforcement subtype where a response prevents an aversive event from occurring; it increases behavior and does not describe a parent passively withholding attention."}}, {"q": "A condition characterised by recurrent intense sexually arousing fantasies and urges involving the use of an inanimate object to obtain sexual gratification:", "concept": "The answer is fetishism because it is defined precisely as recurrent, intense sexual arousal from a nonliving (inanimate) object. This question falls under the paraphilic disorders, a class of conditions in which sexual arousal centers on atypical objects, situations, or targets. The defining hallmark of fetishism (fetishistic disorder) is that the focus of arousal is an inanimate object, classically items like shoes, leather, rubber, or undergarments, or in some definitions a specific nonsexual body part, and the person experiences recurrent and intense sexually arousing fantasies, urges, or behaviors involving that object over at least six months, causing distress or impairment. The key diagnostic feature to anchor is the inanimate object. The distractors are other paraphilias, each defined by a DIFFERENT focus, so learning them as a contrasting set is the efficient strategy. Necrophilia is sexual arousal involving corpses (a dead body, not an inanimate object in the fetish sense). Frotteurism is arousal from touching or rubbing against a nonconsenting person, typically in a crowded public place. Voyeurism is arousal from secretly observing an unsuspecting person who is naked, undressing, or engaged in sexual activity. So each paraphilia is distinguished by the specific stimulus or situation that triggers arousal, and the inanimate object is unique to fetishism. Match the trigger to the disorder and these items become straightforward.", "traps": {"a": "Necrophilia is sexual arousal involving corpses, a dead human body, not the use of an inanimate object as described in the question.", "c": "Frotteurism is arousal from touching or rubbing against a nonconsenting person, usually in a crowd, which involves a person rather than an inanimate object.", "d": "Voyeurism is arousal from secretly watching an unsuspecting person who is naked or engaged in sexual activity, again involving a person, not an object."}}, {"q": "In an experiment, the group which receives no treatment is called:", "concept": "The answer is control group because in experimental design the control group is the set of participants who do NOT receive the treatment or independent variable manipulation, serving as the baseline against which the treated group is compared. The logic of a true experiment is that you manipulate one variable (the independent variable) while holding everything else constant, then observe its effect on an outcome (the dependent variable). To know whether any observed change was actually caused by the treatment rather than by chance, the passage of time, expectations, or other confounds, you need a comparison condition that is identical in every way except that it lacks the treatment. That comparison condition is the control group. The group that does receive the treatment is the experimental group. By randomly assigning participants to experimental and control groups, the researcher distributes confounding variables evenly, so any difference in outcomes can be attributed to the independent variable, giving the study internal validity. A common refinement is the placebo control, where the control group receives an inert substitute so that expectancy effects are equalized. Understanding this terminology is foundational to reading any research methods question: experimental equals treated, control equals untreated baseline. Hence the group receiving no treatment is, by definition, the control group.", "traps": {"a": "The experimental group is precisely the opposite: it is the group that DOES receive the treatment or manipulation, so it cannot be the untreated baseline.", "b": "No group is not a recognized term in experimental design; it is a distractor with no methodological meaning.", "d": "None of these is wrong because a correct, well-established term, control group, exactly names the untreated comparison condition."}}, {"q": "Concept formation stages include the following:", "concept": "A concept is a mental category that groups objects, events, or ideas by shared defining features, letting us respond to novel instances without relearning each one. Learning-theory accounts, drawing on Clark Hull's stimulus-response tradition and later elaborated in Indian psychology curricula, describe concept formation as an ordered progression. It begins with Observation, the raw perceptual encounter with many exemplars of the class. Next comes Discrimination, in which the learner detects how these exemplars differ from non-members, sharpening the boundary of the category (learning that a whale is not a fish despite surface similarity). Then Generalization allows the learner to extend the response across all members that share the essential attributes, treating varied instances as equivalent. Finally Abstraction isolates the common defining property itself, stripping away irrelevant surface detail so the concept becomes a portable rule ('mammal' regardless of size or habitat). Option A preserves this Observation to Discrimination to Generalization to Abstraction sequence. The distractors permute the stages or swap in 'assimilation,' a Piagetian term for fitting new input into existing schemas rather than a named concept-formation stage here. Note that different texts word this sequence slightly differently, so it is genuinely debatable, but the observation-first, abstraction-last ordering is the most widely reproduced version and the intended key. (No official key released; answer expert-determined and flagged as debatable.)", "traps": {"b": "This reverses the natural order, starting with abstraction, which is actually the culminating stage rather than the first.", "c": "Placing generalization before discrimination is out of sequence; the learner must first tell instances apart before grouping them correctly.", "d": "Substituting 'assimilation' and dropping abstraction breaks the standard concept-formation sequence used in learning psychology."}}, {"q": "Location in Rorschach Inkblot Test is concerned with", "concept": "The correct answer is: Whole/Part. In Rorschach scoring, Location codes WHERE in the blot the response was seen: the whole blot (W), a common detail (D), an unusual detail (Dd) or white space (S). So Location is the whole-versus-part dimension. Colour and Movement are Determinants, not Location.", "traps": {"b": "Fantasy/emotion is thematic content, not the Location code.", "c": "Colour and Movement are Determinants (how the percept was formed), a different scoring category.", "d": "Figure/Landscape is not a Rorschach location category."}}, {"q": "The process of changing your behaviour to match that of others in a group is termed:", "concept": "The correct answer is conformity. Conformity is the tendency to change one's beliefs or behaviour to align with the standards of a group, even without any direct request to do so. It is one of the central topics of social psychology. People conform for two broad reasons identified by Deutsch and Gerard: normative social influence, the desire to be liked and accepted and to avoid the discomfort of standing out, and informational social influence, the assumption that the group may know better than oneself, especially in ambiguous situations. Solomon Asch's famous line-judgement experiments demonstrated normative conformity, showing that many participants would give an obviously wrong answer about line lengths simply because confederates had done so first. Muzafer Sherif's autokinetic-effect studies showed informational conformity, where individuals converged on a group estimate when the task was genuinely uncertain. Conformity differs from compliance (yielding to a direct request) and obedience (following an order from an authority). The question's phrasing, matching your behaviour to that of others in a group, is essentially the textbook definition of conformity, which is why it is the precise answer.", "traps": {"a": "Norming is the third stage of Tuckman's group-development model where a team settles into shared norms; it describes group formation, not an individual matching others.", "c": "Standardization refers to establishing uniform procedures or test norms, a methodological term, not a social behaviour.", "d": "Forming a social contact simply means making an acquaintance and has nothing to do with adjusting behaviour to group standards."}}, {"q": "Cardiovascular diseases are more related to", "concept": "This question comes from health psychology's study of how personality relates to physical illness. Cardiologists Meyer Friedman and Ray Rosenman, working in the 1950s, noticed that many of their coronary patients shared a distinctive behavioural style, which they labelled the Type A behaviour pattern. Type A individuals are characterised by chronic time-urgency (a constant sense of racing the clock), competitiveness, high achievement striving, impatience, and, importantly, free-floating hostility and easily provoked anger. Their research, including the long-term Western Collaborative Group Study, found that Type A men developed coronary heart disease at roughly twice the rate of their more relaxed counterparts. The proposed mechanism is that persistent hostility and time pressure keep the sympathetic nervous system chronically activated, raising blood pressure, heart rate, and stress hormones such as cortisol and catecholamines, which over time damage the cardiovascular system. Later refinements, notably by Redford Williams, suggested that hostility and anger are the truly toxic core of the pattern rather than ambition itself. Type B, by contrast, describes people who are patient, relaxed, and non-competitive, and who show lower coronary risk. Introversion and extroversion belong to a different framework (Eysenck's and the trait tradition) and are not the established coronary-prone dimension. The intended link here is Friedman and Rosenman's Type A personality with cardiovascular disease.", "traps": {"a": "Introversion is not the personality style associated with elevated coronary risk.", "b": "Extroversion refers to sociability and outward orientation, which is not the coronary-prone pattern.", "d": "Type B is the relaxed, easygoing pattern that is comparatively protective, not the one linked to heart disease."}}, {"q": "Which movement disorder is a secondary one?", "concept": "Movement disorders are split into primary (idiopathic or genetic, arising from the nervous system itself) and secondary (produced by an identifiable external cause such as medication, toxins, or another illness). Huntington's chorea, first described clinically by George Huntington, is a primary disorder caused by an inherited expansion of the huntingtin gene. Parkinson's disease, named after James Parkinson's 'Essay on the Shaking Palsy,' is a primary neurodegenerative condition marked by loss of dopamine-producing cells in the substantia nigra. Akathisia is different: it is a state of inner restlessness and an inability to stay still that most commonly appears as a side effect of dopamine-blocking drugs, especially antipsychotics (neuroleptics) and some antiemetics. Because it is triggered by an outside agent rather than by an intrinsic disease process, it is classified as a secondary (drug-induced) movement disorder. This distinction matters clinically because secondary disorders are often reversible: reduce or switch the offending medication and the symptoms frequently resolve, whereas primary degenerative disorders progress. Recognising akathisia as iatrogenic also guides management, since patients may be mislabelled as anxious or agitated when the true cause is their prescription. The take-home rule is simple: if an external, removable factor causes the abnormal movement, the disorder is secondary.", "traps": {"a": "Huntington's chorea is a primary, hereditary neurodegenerative disease, not a secondary movement disorder.", "b": "Parkinson's disease is a primary, idiopathic degeneration of dopaminergic neurons, not secondary to another cause.", "d": "'None of these' is wrong because akathisia is a genuine secondary movement disorder."}}, {"q": "The term holophrase means", "concept": "Holophrase is a term from the study of early language development describing the way very young children, typically around twelve to eighteen months in the one-word or holophrastic stage, use a single word to convey the meaning of an entire sentence. The word 'holophrase' literally combines 'holo' (whole) and 'phrase,' capturing the idea that one word stands in for a complete thought. For example, a toddler saying 'milk' may mean 'I want milk,' 'that is milk,' or 'my milk is gone,' with the intended proposition inferred from context, gesture, and intonation. The concept is central to developmental accounts of how children move from single words toward two-word (telegraphic) speech and then full grammar; observers such as Jean Berko Gleason and researchers in the Piagetian and psycholinguistic traditions have documented this progression, and it aligns with the sequence of milestones described in developmental psychology texts like Elizabeth Hurlock's. The key insight is functional: the child is already communicating whole intentions before mastering syntax, so a single word is doing the work of a sentence. That is why the correct definition emphasises a single word used as a sentence, rather than simply being the first word spoken or a complete grammatical sentence. Recognising holophrastic speech helps caregivers and clinicians gauge whether pragmatic communication is developing normally even before word combinations appear.", "traps": {"b": "A holophrase is defined by its sentence-like function, not merely by being the first word a child utters.", "c": "A holophrase is a single word, not a full multi-word sentence.", "d": "The term refers to one word carrying whole-sentence meaning, not to the first few intelligible words collectively."}}, {"q": "Health psychology differs from behavioural medicine primarily in that", "concept": "These two fields overlap heavily and are easy to confuse, so it helps to see how each was defined. Health psychology was formally launched when Joseph Matarazzo, first president of the American Psychological Association's Division 38, described it as the discipline's contribution to promoting and maintaining health, preventing and treating illness, and studying the psychological causes and correlates of disease and the health-care system. Its centre of gravity is psychological science applied to health promotion and prevention: understanding attitudes, motivation, stress, coping, and behaviour change. Behavioural medicine, defined at the 1977 Yale Conference, is deliberately interdisciplinary: it integrates behavioural and biomedical knowledge and techniques relevant to health and illness, and it applies them clinically to prevention, diagnosis, treatment, and rehabilitation. In other words, behavioural medicine is a broader tent that includes physicians, nurses, and other clinicians alongside psychologists, and it fuses behavioural interventions directly with medical treatment. So the cleanest way to distinguish them, and the answer here, is that health psychology emphasises the psychological study of health promotion and prevention, whereas behavioural medicine integrates behavioural and biomedical interventions in an applied, clinical, multidisciplinary way. The other options are simply false characterisations: health psychology neither prescribes medication nor confines itself to neurology, and behavioural medicine most certainly does consider behaviour, since behaviour is right there in its name.", "traps": {"b": "Health psychology is a behavioural science, not a prescribing discipline, and does not rely on medication as its method.", "c": "Behavioural medicine is precisely the field that foregrounds behaviour, integrating it with biomedical knowledge, so this reverses the truth.", "d": "Health psychology is broadly biopsychosocial, spanning cognition, emotion, and social context, not a purely neurological enterprise."}}, {"q": "Suicidal risk is assessed to be highest when the following criteria are met in comparison to others, the 'time' factor being the same for all—", "concept": "Suicide risk assessment weighs a converging set of empirically validated markers rather than any single sign. Edwin Shneidman, the founder of modern suicidology, emphasized that risk peaks when psychological pain ('psychache') meets means and intent. Clinicians operationalize this through several dimensions: the lethality of the chosen method (a firearm or hanging is far more lethal than superficial cutting), the specificity of the plan (a detailed plan with identified means and time indicates rehearsal and resolve), the frequency and intensity of suicidal ideation, and static risk factors such as a family history of suicide, which carries both genetic and modeling influence. When these load together, high lethality, a concrete plan, persistent ideation, and family history, the probability of a fatal act is greatest. Aaron Beck's work on hopelessness added that pessimism about the future predicts eventual suicide better than depression severity alone. Option A stacks the most dangerous combination, so it is correct. The distractors each remove one or more critical elements: absent ideation, only moderate intent, or low lethality all attenuate acute danger even when other stressors exist. The clinical lesson is that risk is multiplicative, not additive; the deadliest presentation is the patient who has both the will (ideation, intent, history) and the way (a lethal, specific plan).", "traps": {"b": "Disrupted functioning alone does not signal imminent risk; without ideation, plan, or intent the acute danger is actually low.", "c": "Adequate functioning, no prior attempt, and only moderate intent describe a comparatively LOW-risk profile, not the highest.", "d": "Low lethality and absence of family history reduce risk; a recent attempt raises concern but the overall cluster is weaker than high-lethality plus a specific plan."}}, {"q": "Number of existing cases on a specific date out of the total population is called", "concept": "Epidemiology, the study of how disorders distribute across populations, distinguishes two core rate families: prevalence (how many cases exist) and incidence (how many new cases appear). Prevalence itself splits by the window of observation. Point prevalence is a snapshot: the proportion of a population that HAS the disorder on one specified date, cases divided by total population at that instant. Period prevalence widens the lens to a stretch of time (say all cases present at any point during a year), so it captures both those who already had the condition and those who developed it mid-period. Incidence is conceptually different: it counts only the fresh onsets over an interval, indexing risk of getting the disorder rather than the burden of having it. The stem's wording, 'existing cases on a specific date out of the total population,' is the textbook definition of point prevalence, so option D is precise. A useful mnemonic from epidemiologists is the bathtub: incidence is water flowing in from the tap, prevalence is the level of water standing in the tub, and point prevalence is that level measured at one exact second. Recovery and death drain the tub, which is why chronic disorders show high prevalence even with modest incidence.", "traps": {"a": "Prevalence is the umbrella term for all existing cases; the stem's 'specific date' narrows it to the point subtype, so the general term is not the precise answer.", "b": "Period prevalence counts existing cases across a time window (e.g. one year), not on a single specified date.", "c": "Incidence counts NEW cases arising over a period among those at risk, not all existing cases at one moment."}}, {"q": "In cognitive psychology, the 'Stroop effect' primarily demonstrates which cognitive phenomenon?", "concept": "The Stroop effect, first reported by John Ridley Stroop in 1935, is a classic demonstration of response interference and the automaticity of reading. Participants are shown color words printed in incongruent ink (for example, the word RED printed in blue ink) and asked to name the ink color, not read the word. Reaction times slow markedly and errors rise compared with naming the color of a neutral patch. The dominant explanation is that skilled reading is automatic: the word meaning is processed involuntarily and competes with the slower, controlled task of ink-color naming, producing a processing conflict that must be resolved. This taps selective attention and executive control, and the task is widely used to index the ability to inhibit a prepotent response. Modern accounts tie Stroop performance to the anterior cingulate cortex and prefrontal conflict-monitoring systems. Option a is correct because the defining feature of the effect is the interference (increased reaction time) caused by conflicting streams of information, one automatic and one controlled.", "traps": {"b": "This describes semantic priming or the encoding-specificity idea, not the Stroop task, which measures interference, not facilitation of recall.", "c": "The Stroop effect actually shows a decrease in speed under conflict, and it is not fundamentally about perceptual accuracy in divided attention.", "d": "Schema theory and episodic memory (Endel Tulving, 1972) are unrelated to the automatic word-reading interference that Stroop measured."}}, {"q": "In the context of psychometrics, which of the following best represents 'construct validity'?", "concept": "Construct validity is the extent to which a test actually measures the theoretical construct, the unobservable trait such as intelligence, anxiety, or extraversion, that it is intended to measure. The term and framework were formalized by Lee Cronbach and Paul Meehl in 1955, who argued that a construct is embedded in a nomological network of expected relationships, and evidence for construct validity accumulates as scores behave as theory predicts. It has two complementary strands: convergent validity (the measure correlates with other measures of the same construct) and discriminant validity (it does not correlate with measures of unrelated constructs), a distinction sharpened by Donald Campbell and Donald Fiske through the multitrait-multimethod matrix. Modern testing standards treat construct validity as the overarching, unifying concept under which content and criterion evidence fall. Option a, capturing whether the test measures what it claims to measure, is the standard textbook definition. The distractors describe reliability (b and d) and content validity (c), which are related but distinct psychometric properties.", "traps": {"b": "This describes reliability (specifically test-retest), not validity.", "c": "This describes content validity, a narrower facet, not construct validity itself.", "d": "This describes inter-rater reliability, a form of reliability, not construct validity."}}, {"q": "According to the Theory of Planned Behavior, which of the following factors influences an individual's intention to engage in health behaviors?", "concept": "The correct answer is attitude, subjective norms and self-efficacy. The Theory of Planned Behavior, developed by Icek Ajzen, holds that the strongest predictor of behaviour is a person's intention to perform it, and that intention is in turn shaped by three factors. The first is attitude toward the behaviour, one's favourable or unfavourable evaluation of performing it. The second is subjective norms, the perceived social pressure from important others to perform or not perform the behaviour. The third is perceived behavioural control, the person's belief in their ability to carry out the behaviour, a construct closely related to Albert Bandura's concept of self-efficacy. These three components jointly determine intention, and intention drives behaviour, so option A correctly names them. The Theory of Planned Behavior extended Ajzen and Martin Fishbein's earlier Theory of Reasoned Action by adding perceived behavioural control to account for behaviours not fully under voluntary control. Option B (genetics, personality traits, socio-economic status), option C (cultural beliefs, social support, health literacy), and option D (physical environment, emotional intelligence (Peter Salovey and John Mayer, 1990), coping strategies) all list plausible-sounding influences on health but none matches the three specific constructs of the model. The theory is widely applied in health psychology to predict and change behaviours such as exercise, smoking cessation, and safe practices. (no official key in the paper; answer determined by subject expertise)", "traps": {"b": "Genetics, personality traits, and socio-economic status are not the components of the Theory of Planned Behavior.", "c": "Cultural beliefs, social support, and health literacy are relevant to health but are not the three TPB predictors of intention.", "d": "Physical environment, emotional intelligence, and coping strategies do not correspond to the constructs of the Theory of Planned Behavior."}}, {"q": "The concept of \"reciprocal determinism\" is central to which personality theory?", "concept": "The correct answer is Social cognitive theory. Reciprocal determinism is a core concept of the social cognitive theory of personality developed by Albert Bandura. It proposes that human functioning results from the continuous, mutual interaction of three sets of factors: behaviour, personal or cognitive factors (such as beliefs and expectations), and the environment. Each of these influences and is influenced by the others in a triadic, bidirectional loop, so people are neither driven purely by inner forces nor simply shaped by the environment; instead they actively shape and are shaped by their surroundings. This interactive model is why option B is correct. Bandura is also famous for the concept of self-efficacy and for the Bobo doll studies demonstrating observational learning. Psychodynamic theory (option A), founded by Sigmund Freud, explains personality through unconscious conflicts, the id, ego, and superego, and psychosexual stages, not through reciprocal interaction of behaviour and environment. Humanistic theory (option C), advanced by Carl Rogers and Abraham Maslow, stresses free will, self-concept, and the drive toward self-actualisation. Biological theory (option D) roots personality in genetics, temperament, and brain physiology. Reciprocal determinism specifically captures Bandura's insight that person, behaviour, and environment jointly and reciprocally determine one another. (no official key in the paper; answer determined by subject expertise)", "traps": {"a": "Psychodynamic theory, from Sigmund Freud, centres on unconscious drives and psychosexual stages, not reciprocal determinism.", "c": "Humanistic theory, from Carl Rogers and Abraham Maslow, emphasises self-actualisation and free will, not the triadic reciprocal model.", "d": "Biological theory attributes personality to genetics and physiology, not to the interaction of behaviour, cognition, and environment."}}, {"q": "Which neuroscientific technique provides the highest temporal resolution for studying neural activity?", "concept": "Temporal resolution refers to how precisely in time a technique can track changes in neural activity, whereas spatial resolution refers to how precisely it localizes them in space. Electroencephalography (EEG), pioneered for humans by Hans Berger, records the summed electrical potentials of cortical neurons directly from scalp electrodes. Because it measures electrical activity in real time, its temporal resolution is on the order of milliseconds, the best among the options listed, which is why it and the related magnetoencephalography are preferred for studying the rapid dynamics of perception and the timing of event-related potentials. Its weakness is poor spatial resolution and the inverse problem of localizing sources. Functional MRI (fMRI) and PET rely on hemodynamic or metabolic signals (blood oxygenation for fMRI, tracer uptake for PET) that lag neural events by seconds to minutes, giving them fine spatial but coarse temporal resolution. CT is purely structural. Because the question asks specifically about the highest temporal resolution, EEG (option c) is correct.", "traps": {"a": "fMRI has excellent spatial resolution but poor temporal resolution (seconds), because it tracks the sluggish blood-oxygen response.", "b": "PET is even slower than fMRI, tracking metabolic tracer uptake over minutes.", "d": "CT is a static structural imaging method with essentially no temporal resolution for activity at all."}}, {"q": "Lack of bowel control in children is known as:", "concept": "The correct answer is encopresis. Encopresis is the repeated passage of faeces into inappropriate places (such as clothing or the floor) by a child who is old enough to have achieved bowel control, conventionally a chronological and developmental age of at least four years. It is the lack of bowel control beyond the expected age, and it can be either primary (the child has never established control) or secondary (control was achieved and then lost, often linked to stress or constipation with overflow soiling). Encopresis is contrasted with enuresis, which is the repeated involuntary or intentional voiding of urine, that is, lack of bladder control, into bed or clothes by a child old enough to be continent (usually age five and above). The simple way to keep these straight is that encopresis concerns the bowel (faeces) while enuresis concerns the bladder (urine). Both are elimination disorders in child psychiatry and may have physiological contributors (constipation, small bladder capacity), developmental delay, or emotional and behavioural factors. Because the question specifically asks about bowel control, encopresis is the correct term, and the key distinction to remember is bowel versus bladder.", "traps": {"b": "Analism is not a recognised clinical term for loss of bowel control; it is a distractor.", "c": "Enuresis is the lack of bladder control (involuntary urination), the urinary counterpart, not the bowel disorder asked about.", "d": "Anorexia is loss of appetite or the eating disorder anorexia nervosa, entirely unrelated to bowel control."}}, {"q": "Which of the following methods is used in Beck's cognitive therapy for depression?", "concept": "Cognitive therapy for depression was developed by Aaron Beck, who proposed that depression is maintained by systematically distorted thinking rather than by unconscious conflict. Central to his model is the negative cognitive triad: negative views of the self, the world, and the future, sustained by cognitive distortions such as arbitrary inference, overgeneralization, and catastrophizing, all stemming from maladaptive core beliefs and schemas. The therapy therefore trains clients to identify automatic negative thoughts, examine the evidence for and against them, and test their validity, essentially treating beliefs as hypotheses to be evaluated objectively rather than accepted as fact. This process, often called collaborative empiricism and cognitive restructuring, may be paired with behavioral experiments and homework. The distractors describe methods from other traditions: dream analysis and free association are hallmark techniques of the psychoanalysis of Sigmund Freud, and administering medication is a biological treatment. Because making objective, evidence-based assessments of one's beliefs is the defining technique of Beck's approach, option b is correct.", "traps": {"a": "Dream analysis is a psychoanalytic technique of Freud, not a cognitive therapy method.", "c": "Prescribing medication is a biomedical intervention, not a cognitive-therapy technique, and clinical psychologists using CBT do not prescribe.", "d": "Free association is the core method of psychoanalysis, not cognitive therapy."}}, {"q": "Which personality disorder is marked by manipulation, lack of remorse, and irresponsibility?", "concept": "Antisocial personality disorder (ASPD) is a Cluster B personality disorder in the DSM-5 characterized by a pervasive pattern of disregard for and violation of the rights of others beginning by age 15. Its hallmark features are deceitfulness and manipulation for personal gain, lack of remorse for harm caused, impulsivity, irritability and aggressiveness, reckless disregard for safety, and consistent irresponsibility in work and financial obligations. Diagnosis requires the person to be at least 18 and to have had evidence of conduct disorder before age 15. The construct overlaps with, but is broader than, the classic notion of psychopathy described by Hervey Cleckley in The Mask of Sanity and later operationalized by Robert Hare. The distractors are other personality disorders with different cores: borderline (emotional and relational instability, abandonment fears), dependent (clinging, submissive reliance on others), and narcissistic (grandiosity and need for admiration). Because the triad of manipulation, lack of remorse, and irresponsibility maps directly onto ASPD, option b is correct.", "traps": {"a": "Borderline personality disorder centers on instability of affect, identity, and relationships plus fear of abandonment, not a callous lack of remorse.", "c": "Dependent personality disorder is marked by submissiveness and a need to be cared for, the opposite of exploitative manipulation.", "d": "Narcissistic personality disorder features grandiosity and need for admiration; manipulation may occur, but lack of remorse and law-breaking irresponsibility define antisocial, not narcissistic."}}, {"q": "In experimental psychology, which of the following scenarios best controls for expectancy effects?", "concept": "Expectancy effects are systematic biases introduced when the beliefs or hopes of participants or experimenters influence outcomes. On the participant side these are demand characteristics and placebo responses; on the experimenter side they are the Rosenthal effect, named for Robert Rosenthal, who showed that experimenters can unconsciously cue subjects toward expected results. A single-blind procedure conceals the condition from participants only, leaving the experimenter free to bias measurement, coding, or interaction. A double-blind design conceals condition assignment from both the participants and the experimenters (or the personnel interacting with and assessing them), so neither party's expectations can shape behavior or scoring. This is the gold standard in clinical drug trials, where an active drug and an inert placebo are administered by staff who do not know which is which. Random assignment (option b) is essential for internal validity and controlling confounds, but it addresses group equivalence, not expectancy. Because only the double-blind arrangement neutralizes expectancy from both directions, option d is correct.", "traps": {"a": "A single-blind design hides condition from participants only, so experimenter expectancy effects can still leak through.", "b": "Random assignment controls for confounding between groups but does nothing to hide condition, so expectancy effects remain.", "c": "Instructions cannot eliminate unconscious expectancy on either side and may even introduce demand characteristics."}}, {"q": "Dark adaptation is the process in which the eyes get more sensitive to:", "concept": "The correct answer is light with low illumination. Dark adaptation is the gradual recovery of the eye's sensitivity that occurs when you move from a brightly lit environment into darkness, for example walking from sunlight into a dim cinema. At first you can see almost nothing, but over roughly twenty to thirty minutes your eyes become dramatically more sensitive, able to detect very faint light. The mechanism rests on the two photoreceptor systems of the retina. Cones, packed in the fovea, handle bright daytime (photopic) vision and colour but are relatively insensitive in dim light. Rods, spread across the periphery, contain the pigment rhodopsin and are exquisitely sensitive to low illumination. In bright light rhodopsin is bleached and broken down; in darkness it is resynthesised, and as its concentration rebuilds the rods regain sensitivity. The dark adaptation curve is therefore biphasic: an early rapid cone phase lasting a few minutes, then a slower rod phase that continues for half an hour and accounts for the deepest sensitivity. This is why faint stars become visible only after you have stood outside for a while, and why we see dim objects best slightly off-centre, using peripheral rods rather than the cone-rich fovea. The process is the basis of scotopic (low-light) vision.", "traps": {"a": "Green light is the wavelength the eye is most sensitive to in scotopic conditions (the Purkinje shift), but dark adaptation is about adapting to dim levels generally, not to a single colour.", "b": "Coloured lights are processed by cones, which actually lose their role in the dark; colour vision fades as we dark-adapt, so this is the opposite of what happens.", "c": "Light with bright illumination describes light adaptation, the quick adjustment when entering a bright room, which is the reverse process of dark adaptation."}}, {"q": "The improvement in anxiety may sometimes spuriously improve depression. This is called:", "concept": "The keyed answer is the halo effect. The halo effect is a cognitive bias in which one's overall impression of a person, or one prominent trait, colours the judgement of their other, separate characteristics. Coined by Edward Thorndike, it originally described how officers rating soldiers let a single favourable impression inflate ratings of unrelated qualities. In this clinical example, because the patient's anxiety has improved, the rater is inclined to judge that the depression has improved too, even though depression was not really assessed independently; the positive global impression spills over and spuriously raises the depression rating. This is a serious threat to the validity of clinical ratings and assessment, because it creates artificial correlations between symptoms that should be rated separately. Researchers guard against it by using structured, anchored rating scales, by having different raters assess different domains, and by blinding. It is worth noting that some texts would describe symptom co-improvement differently, but within the framework of rating bias the spillover of one improved judgement onto another is the halo effect, which is why the source keys it here. The key learning point is that a rater's general impression can distort the measurement of specific, supposedly independent variables.", "traps": {"b": "The ceiling effect occurs when a measure cannot register improvement above a maximum score because scores cluster at the top; it concerns scale limits, not impression spillover.", "c": "The Hawthorne effect is when people change their behaviour simply because they know they are being observed, unrelated to rating one symptom from another.", "d": "Therapeutic effect just means a genuine benefit from treatment, not a measurement bias, so it does not capture the spurious nature described."}}, {"q": "Who proposed the social role theory of gender?", "concept": "The correct answer is Alice Eagly. Alice Eagly proposed social role theory to explain sex differences in social behavior. The theory holds that observed psychological and behavioral differences between men and women arise largely from the contrasting social roles they occupy, roles historically shaped by a division of labor. Because women were more often assigned domestic and caregiving roles and men more often assigned provider and leadership roles, societies developed gender-role expectations (communal traits like nurturance for women, agentic traits like assertiveness for men). Individuals then internalize and enact these expectations, and observers infer that men and women have differing inherent dispositions, a bias that reinforces the roles. Crucially, social role theory is a sociocultural account and stands in direct contrast to the evolutionary psychology explanation championed by David Buss, who attributes sex differences to inherited adaptations from ancestral mating and survival pressures. Eagly later extended her framework into the biosocial and role congruity theories, the latter explaining prejudice against women in leadership when leader stereotypes clash with female gender roles. The item tests correct attribution of the sociocultural theory to Eagly.", "traps": {"a": "David Buss is associated with the evolutionary psychology account of sex differences, the rival to social role theory.", "c": "Mehta and Strough studied gender segregation across the lifespan, not the origin of social role theory.", "d": "Anderson is not the originator of this theory and is a distractor name here."}}, {"q": "Which of the following statements is TRUE with respect to Minnesota Multiphasic Personality Inventory (MMPI)?", "concept": "The correct answer is that the MMPI is derived by finding items that discriminate between criterion and control groups. The Minnesota Multiphasic Personality Inventory was developed by Starke Hathaway and J. Charnley McKinley in the early 1940s and is the classic example of the empirical (criterion-keying) method of test construction. Rather than assuming in advance which items should measure a trait (the rational or deductive approach) or grouping items by statistical clustering (the factor-analytic approach used by Raymond Cattell for the 16PF), the empirical method selects items purely on the basis of whether they empirically distinguish a criterion group (for example, patients diagnosed with depression) from a normal control group. An item is retained for a scale if the two groups answer it differently, regardless of whether its content seems face-relevant. This is why some MMPI items appear unrelated to the construct they help measure. The approach yields clinical scales (such as Depression, Hypochondriasis, Psychopathic Deviate, Schizophrenia, Paranoia) plus validity scales (L, F, K) that detect response distortion. Because options a and b both describe the rational method that the MMPI did not use, the only true statement is that it discriminates between criterion and control groups, making option c correct.", "traps": {"a": "The MMPI used the empirical, not the rational, method of construction, so this is false.", "b": "Assuming traits in advance and writing items to fit them is the rational (deductive) approach, which the MMPI deliberately rejected.", "d": "Since both a and b describe the rational method the MMPI did not use, this combined option is also false."}}, {"q": "Narendra turns around and around in a circle. When he stops, he feels like his head is spinning. What is responsible for this sensation?", "concept": "The correct answer is the semicircular canals. Spinning and the dizzy after-sensation are functions of the vestibular system in the inner ear, which provides our sense of balance and head movement. The vestibular apparatus has two parts. The three semicircular canals, oriented in three different planes, detect rotational (angular) acceleration: each canal is filled with fluid (endolymph) and contains a gelatinous cupula with hair cells. When the head rotates, the fluid lags behind due to inertia, bending the cupula and triggering the hair cells. When Narendra suddenly stops spinning, the fluid keeps moving for a moment, continuing to bend the hair cells, so the brain is still told the head is rotating even though it has stopped. This mismatch produces the illusion of spinning, dizziness, and the characteristic nystagmus of the eyes. The other vestibular structures, the otolith organs (the utricle and saccule), detect linear acceleration and the pull of gravity, telling us about head tilt and straight-line motion, not rotation. Because the question is specifically about turning in circles and the resulting spin sensation, the rotation-detecting semicircular canals are the correct structure.", "traps": {"b": "Proprioceptors are receptors in muscles and joints that sense body and limb position, not the rotational dizziness of the inner ear.", "c": "The otolith organs (utricle and saccule) detect linear acceleration and gravity/head tilt, not the rotational spinning that causes this dizziness.", "d": "Otolith crystals (otoconia) sit on the otolith organs and respond to gravity and linear motion; they do not signal rotation."}}, {"q": "A researcher would like to study how and to what degree heredity and the environment influence obesity. What population of individuals would provide the most information?", "concept": "The correct answer is monozygotic twins adopted by different parents. This is the classic 'twins reared apart' design, the most powerful natural experiment in behaviour genetics for separating the effects of heredity from environment. Monozygotic (identical) twins share essentially 100 percent of their genes, so when they are raised in different families and thus different environments, any remaining similarity between them (for example in body weight or obesity) can be attributed largely to their shared genetics, while any differences reflect environmental influence. This logic underpinned famous projects such as the Minnesota Study of Twins Reared Apart led by Thomas Bouchard. Comparing identical twins reared apart to identical twins reared together, and to fraternal twins and unrelated adoptees, lets researchers estimate heritability. Dizygotic twins and ordinary siblings share only about half their genes, so they cannot pinpoint genetic contribution as precisely, and twins raised together confound genes with a shared home environment. The item tests understanding of why maximising genetic similarity while varying environment yields the cleanest estimate of the nature versus nurture balance for a trait like obesity.", "traps": {"a": "Dizygotic (fraternal) twins share only about 50 percent of their genes, so they cannot isolate genetic influence as cleanly as identical twins, even when reared apart.", "b": "Monozygotic twins raised together share both genes and environment, so any similarity is confounded; you cannot separate nature from nurture.", "d": "Ordinary siblings share only about 50 percent of genes on average, making them far less informative for isolating genetic effects than identical twins reared apart."}}, {"q": "Any distorting or selective effect of a person’s inner world on his perception or conception of the outer world is termed:", "concept": "The keyed answer is denial, though the wording of the question describes a broader concept. The phrase 'any distorting or selective effect of a person's inner world on his perception of the outer world' captures how defence mechanisms in general bend reality to protect the ego. Denial is the most primitive of these defences: the person simply refuses to acknowledge an external reality that is too threatening to bear, behaving as though a painful fact does not exist, for example a terminally ill patient insisting they are perfectly healthy, or a person refusing to accept a loved one's death. Defence mechanisms were first systematised by Sigmund Freud and elaborated by Anna Freud in The Ego and the Mechanisms of Defence. They operate unconsciously and serve to reduce anxiety arising from conflict between the id's impulses, the superego's prohibitions, and external reality. Denial works at the level of perception itself, blocking the threatening information before it is fully registered, which is exactly why it fits a definition framed around distorting one's conception of the outer world. Clinically, heavy reliance on denial is associated with more immature or psychotic-level functioning, whereas mature defences like sublimation or humour distort reality far less. The source treats denial as the answer because the definition stresses a global filtering of outer reality rather than a specific impulse.", "traps": {"a": "Projection attributes one's own unacceptable feelings to other people; it distorts perception but in a specific outward-blaming way rather than the broad selective filtering described.", "b": "Introjection takes external objects or attitudes into the self, the opposite direction of flow from the inner world distorting the outer.", "c": "Empathy is the accurate sharing of another's emotional state, not a distortion of reality, so it is not a defence mechanism at all."}}, {"q": "The term ‘Ambivalence’ was coined by:", "concept": "The correct answer is Eugen Bleuler. Ambivalence, the simultaneous holding of contradictory feelings, attitudes, or impulses toward the same object (such as loving and hating someone at once), was coined by the Swiss psychiatrist Eugen Bleuler. Bleuler is one of the most important figures in the history of schizophrenia. In 1911 he renamed Kraepelin's dementia praecox as schizophrenia, meaning a splitting of psychic functions, to capture the disintegration between thought, emotion, and behaviour. He identified what are now called Bleuler's four As as the fundamental symptoms of the disorder: loosening of Associations (disordered thought connections), Affective disturbance (blunted or inappropriate emotion), Ambivalence (contradictory feelings or volitions held together), and Autism (withdrawal into an inner fantasy world). He regarded hallucinations and delusions as merely accessory symptoms, secondary to these core disturbances. Ambivalence as Bleuler used it can occur in the emotional, volitional, or intellectual spheres and reflects the fragmentation of the integrated mind that he believed defined schizophrenia. The term has since entered general psychological and psychoanalytic vocabulary, but its origin lies with Bleuler.", "traps": {"a": "Kraepelin coined dementia praecox and built the classification of psychoses, but the specific term ambivalence was Bleuler's contribution.", "c": "Richmond Fromm is not a recognised originator of this term; Erich Fromm worked on humanistic and social psychoanalysis, not ambivalence.", "d": "Sigmund Freud used ambivalence in his writing, but he did not coin the term; it originated with Bleuler."}}, {"q": "Reliable difference between two groups can be obtained by using:", "concept": "The correct answer is a statistical test. To know whether two groups genuinely differ, rather than differing only because of random sampling fluctuation, you must apply an inferential statistical test such as a t-test, ANOVA, or chi-square. These tests compute the probability (the p-value) that the observed difference could have arisen by chance if there were truly no difference in the populations. If that probability is small (conventionally below .05), the difference is judged statistically significant and considered reliable, meaning unlikely to be a fluke. The logic rests on null hypothesis significance testing: you assume no difference (the null hypothesis), calculate how surprising your data would be under that assumption, and reject the null when the data are sufficiently improbable. Without such a test you cannot distinguish a real effect from noise, no matter how large the raw difference looks, because small samples produce large random swings. This is the core tool of quantitative research design and why a statistical test, not a property of the measuring instrument, is what establishes a reliable difference between groups.", "traps": {"a": "Norms are reference scores from a standardisation sample used to interpret an individual's score, not a means of comparing two groups for a reliable difference.", "b": "Validity is whether a test measures what it claims to measure; it concerns the instrument's accuracy, not the comparison of groups.", "c": "Reliability is the consistency of a measurement instrument; a reliable test can still leave a group difference untested for significance."}}, {"q": "Which method is characterized by moving from specific observations to broader generalizations?", "concept": "The correct answer is Inductive reasoning. Inductive reasoning is defined by its direction of inference: it moves from specific, particular observations toward broader, general conclusions or theories. The researcher notices individual instances, identifies a recurring pattern, and then generalises to a wider principle, so the phrase in the question, from specific observations to broader generalizations, is the textbook definition of induction, making option B correct. Deductive reasoning (option A) runs in exactly the opposite direction, from broad general premises or theory down to specific predictions and instances, so it cannot be the answer. Experimental design (option C) is a methodological strategy for manipulating variables and controlling conditions to test causal hypotheses, in the tradition of Ronald Fisher; it is a type of study, not a label for the specific-to-general direction of reasoning. Qualitative analysis (option D) frequently employs inductive logic and is associated with it, but qualitative analysis names a family of data-analysis approaches rather than the reasoning pattern itself, so it is not the precise term the question seeks. A key caution about induction is that its conclusions are probable rather than certain, since a general claim inferred from limited observations can always be overturned by a new counterexample. (no official key in the paper; answer determined by subject expertise)", "traps": {"a": "Deductive reasoning moves from broad generalisations to specific predictions, the reverse direction.", "c": "Experimental design is a research strategy for testing causal hypotheses, not a description of the inductive direction of inference.", "d": "Qualitative analysis often uses induction but is a category of analysis, not the name of the reasoning direction the question defines."}}, {"q": "Which of the following is a type of attitude measurement scale?", "concept": "The correct answer is Likert scale. A Likert scale is a specific attitude measurement technique developed by Rensis Likert in 1932. It presents respondents with a series of statements and asks them to indicate their level of agreement along a symmetric range, typically five points from strongly disagree to strongly agree, and it sums or averages responses to gauge an underlying attitude. It is one of the most widely used attitude scales, alongside the Thurstone scale (Louis Leon Thurstone) and the Guttman scale (Louis Guttman). The other three options, nominal, ordinal, and interval, are Stanley Smith Stevens's levels of measurement, describing the mathematical properties of data rather than being named instruments for capturing attitudes. Nominal denotes unordered categories, ordinal denotes ranked categories, and interval denotes equal-spaced values with an arbitrary zero. While Likert responses are themselves usually treated as ordinal data, the Likert scale as a whole is a purpose-built attitude-measurement method, which is what the question asks for. Recognising named attitude scales matters in psychometrics because each has different assumptions about scoring and dimensionality, and the Likert format's ease of construction and interpretation explains its dominance in survey research. (no official key in the paper; answer determined by subject expertise)", "traps": {"a": "Nominal scale is a level of measurement, not a purpose-built attitude scale.", "b": "Ordinal scale is a measurement level describing rank order, not a named attitude-measurement instrument.", "c": "Interval scale is a measurement level, not a specific attitude scale technique."}}, {"q": "Arvind is a college student who has strong negative feelings about smoking cigarettes. His grandfather died of lung cancer and he believes smoking is disgusting. One night at a party, Arvind's friends all go outside for a cigarette and he decides to smoke as well. What will he most likely experience as a result?", "concept": "The correct answer is cognitive dissonance. Leon Festinger developed the theory of cognitive dissonance in 1957, proposing that people feel an uncomfortable state of psychological tension when they hold two contradictory cognitions or when their behaviour conflicts with their attitudes. Arvind strongly believes smoking is disgusting and harmful (his grandfather died of lung cancer), yet he chooses to smoke. The clash between his anti-smoking attitude and his pro-smoking behaviour produces dissonance. Festinger argued that people are motivated to reduce this tension, typically by changing the attitude ('maybe smoking once is not so bad'), changing the behaviour (stopping), or adding consonant cognitions ('everyone was doing it, it was just social'). Festinger and James Merrill Carlsmith demonstrated this experimentally in their famous 1959 study where participants paid only one dollar to lie about a boring task later rated it as more enjoyable, because low external justification forced them to resolve dissonance internally. Distractors like justification of effort are subtypes of dissonance but require prior effort or suffering, which is absent here. This item tests whether the student can identify the general dissonance concept from an attitude-behaviour conflict scenario.", "traps": {"a": "Justification of effort is a specific dissonance phenomenon where people overvalue goals they suffered for (as in initiation studies); Arvind expended no effort, so this narrower term does not fit.", "b": "An increased drive to smoke would be a physiological or motivational craving; the scenario centres on a clash between belief and action, not a biological urge.", "d": "Drive reduction (from Clark Hull's theory) refers to satisfying a biological need to restore homeostasis; smoking here does not reduce any drive, it creates psychological tension."}}, {"q": "Vaibhav smokes, drinks alcohol, overeats, and bites his nails. Which stage of Freud's stages of psychosexual Development has Vaibhav become fixated at?", "concept": "The correct answer is the oral stage. Sigmund Freud proposed five psychosexual stages of development (oral, anal, phallic, latency, genital), each centred on a different erogenous zone where libidinal energy is focused. If a child's needs are either overindulged or under-gratified at a given stage, Freud argued that some libido remains fixated there, producing characteristic adult personality traits and behaviours. The oral stage (roughly birth to 18 months) centres on the mouth, with pleasure derived from sucking, biting, and chewing. Fixation at the oral stage is expressed in adulthood through mouth-oriented and dependency-related behaviours such as smoking, excessive drinking, overeating, nail-biting, and thumb-sucking, exactly the cluster described for Vaibhav. An oral-receptive versus oral-aggressive personality may also develop. The anal stage (option B) concerns bladder and bowel control and yields orderliness or messiness; the phallic stage involves the Oedipus and Electra complexes; and latency is a quiet period before the mature genital stage. Although Freud's theory is scientifically criticised and largely unfalsifiable, it remains standard exam content. The item tests the classic association between oral fixation and mouth-focused adult habits.", "traps": {"a": "The phallic stage centres on the genitals and the Oedipus or Electra complex (Carl Jung, 1913); fixation there relates to identity and sexuality issues, not mouth-focused habits.", "b": "Anal-stage fixation produces either excessive orderliness (anal-retentive) or messiness (anal-expulsive), tied to toilet training, not oral behaviours.", "d": "The latency stage is a period of dormant sexual energy with no fixations in Freud's scheme; it is not associated with a distinct set of adult traits."}}, {"q": "Which area of the brain is primarily associated with the consolidation of long-term memories?", "concept": "The correct answer is Hippocampus. The hippocampus, a seahorse-shaped structure in the medial temporal lobe, plays a central role in consolidating new information from short-term into long-term declarative memory, that is, memory for facts and events. Its importance was dramatically revealed by the case of patient H.M. (Henry Molaison), studied by Brenda Milner, whose bilateral hippocampal removal left him unable to form new long-term memories (anterograde amnesia) while sparing older memories and motor learning. This showed the hippocampus is essential for encoding and consolidating new declarative memories, even though the memories are eventually stored in the neocortex. Option A is thus correct. The amygdala (option B), also in the temporal lobe, processes emotion, especially fear, and modulates how strongly emotional experiences are remembered, but it is not the primary consolidation site. The prefrontal cortex (option C) supports working memory, attention, and executive control rather than the consolidation of new long-term memories. The cerebellum (option D) governs motor coordination, balance, and procedural (implicit) learning such as classically conditioned responses, not declarative memory. The concept of synaptic consolidation, involving long-term potentiation described by Donald Hebb's principle that cells that fire together wire together, underlies how the hippocampus stabilises new memories. (no official key in the paper; answer determined by subject expertise)", "traps": {"b": "The amygdala processes emotion and modulates the emotional strength of memories, but it is not the primary consolidation structure.", "c": "The prefrontal cortex supports working memory and executive function rather than the consolidation of new long-term memories.", "d": "The cerebellum is chiefly involved in motor coordination and procedural learning, not declarative memory consolidation."}}, {"q": "Helicopter Parenting is the result of:", "concept": "The keyed answer is all of the above, because helicopter parenting is multiply determined rather than springing from one source. Helicopter parenting describes an over involved style in which parents hover, intervene excessively, solve problems their child could solve alone, and monitor and control developmentally inappropriate amounts of the child's life. Research on its origins points to several converging causes. First, parental anxiety: parents who are highly anxious about safety, failure, or the future manage their own distress by controlling the child's environment, so the hovering is partly an emotion regulation strategy for the parent. Second, parents' unfulfilled wishes: parents may project their own thwarted ambitions onto the child and micromanage achievement so the child realises the life the parent did not, a form of vicarious living. Third, the parents' own personality traits: dispositions such as perfectionism, neuroticism, high need for control, or an anxious attachment style predispose a person to over involvement. Because each of these has empirical support and they often act together, the comprehensive answer is all of the above. Developmentally the concern is that over parenting undermines the child's autonomy, self efficacy (Albert Bandura, 1977), and emotion regulation, contributing to higher anxiety and lower coping in emerging adults, which is why it is studied as a risk style rather than a benign quirk.", "traps": {"a": "Parental anxiety is a genuine cause but only one of several, so selecting it alone is incomplete.", "b": "Unfulfilled parental wishes contribute through vicarious living, but again this is only one contributing factor, not the whole picture.", "c": "Parents' personality traits such as perfectionism and high control needs matter, yet they too are just one strand of a multiply determined pattern."}}, {"q": "Which of the following technique or techniques would not typically be included within the repertoire of an Adlerian counsellor?", "concept": "The correct answer is analysis of transference. Adlerian counselling, derived from the Individual Psychology of Alfred Adler, emphasizes holism, social interest (Gemeinschaftsgefuhl), lifestyle assessment, birth-order and family constellation, striving for superiority, and encouragement, working in a collaborative, egalitarian, present-and-future-oriented way. Its distinctive techniques include acting as if (encouraging clients to behave as though they were already the capable person they wish to become), the push-button technique (having clients alternately generate pleasant and unpleasant memories to demonstrate that they can control their emotional states), catching oneself, spitting in the client's soup, paradoxical intention, and above all encouragement, which Adlerians regard as the key to counteracting discouragement and inferiority feelings. Analysis of transference, by contrast, is a hallmark of classical psychoanalysis developed by Sigmund Freud, in which the client's unconscious redirection of feelings about significant early figures onto the analyst is systematically interpreted. Adler broke from Freud and de-emphasized the unconscious, drive theory, and the intensive analysis of transference in favor of conscious goals, social embeddedness, and encouragement. Therefore, transference analysis is the technique that does not belong in the Adlerian repertoire, making option d correct.", "traps": {"a": "Acting 'as if', having clients behave as though they were the person they wish to be, is a classic Adlerian technique.", "b": "The push-button technique, in which clients generate pleasant and unpleasant images to see they can control feelings, is Adlerian.", "c": "Encouragement is central to Adlerian counselling, aimed at building courage and social interest."}}, {"q": "The diathesis-stress model of psychopathology suggests that mental disorders result from :", "concept": "The correct answer is a combination of genetic predisposition and environmental stressors. The diathesis-stress model is an interactionist framework in psychopathology holding that mental disorders arise from the interaction between a diathesis, a pre-existing vulnerability or predisposition (often genetic, but also biological or psychological), and stress, adverse environmental experiences or life events. Neither factor alone is usually sufficient: a person may carry a vulnerability that never manifests unless triggered by sufficient environmental stress, and conversely, stress may not produce disorder in someone without the underlying predisposition. The disorder emerges when the accumulated stress exceeds the threshold set by the individual's diathesis. This interaction of nature and nurture is exactly what option C describes. Option A, genetic factors only, is wrong because it omits the stress side of the equation and reduces the model to pure heredity. Option B, environmental factors only, is likewise incomplete because it ignores the predisposition, or diathesis. Option D, neurobiological abnormalities only, is a single-cause, reductionist explanation that contradicts the model's central claim that disorder results from the interplay of vulnerability and environment, not from biology alone. The diathesis-stress model, with roots in work by researchers such as Paul Meehl on schizophrenia, is widely used to explain conditions like depression and schizophrenia, integrating biological and environmental contributions. (no official key in the paper; answer determined by subject expertise)", "traps": {"a": "Genetic factors only ignores the stress component; the model is explicitly about the interaction of predisposition and stress.", "b": "Environmental factors only ignores the diathesis (predisposition) side of the model.", "d": "Neurobiological abnormalities only is a reductionist single-cause view, contrary to the model's interactionist stance."}}, {"q": "Which of the following is an example of a quantitative research method?", "concept": "The correct answer is Survey. Quantitative research collects numerical data that can be counted, measured, and statistically analysed to test hypotheses and generalise to a population. A survey administers standardised questions to a sample and yields numeric responses (ratings, frequencies, percentages), so it is a classic quantitative method. This distinction traces to the broader positivist tradition described by Auguste Comte, in which knowledge is built from measurable observation. Qualitative methods, by contrast, aim to understand meaning, context, and lived experience through words rather than numbers. Case study (championed as a method by Robert Yin), ethnography (rooted in the anthropology of Bronislaw Malinowski), and grounded theory (developed by Barney Glaser and Anselm Strauss) all fall on the qualitative side because they produce rich descriptive text, not quantified variables. The key marker of a quantitative method is that the data can be entered into statistics and expressed as numbers. Surveys with closed-ended, scaled items fit this exactly. Understanding this divide matters because it determines which analysis (means, correlations, significance tests versus thematic coding) is appropriate for the data collected. (no official key in the paper; answer determined by subject expertise)", "traps": {"a": "A case study is an in-depth qualitative examination of a single instance, describing meaning rather than measuring numeric variables.", "b": "Ethnography is a qualitative, immersive study of a culture or group through observation and field notes, not numeric data.", "d": "Grounded theory is a qualitative approach that builds theory inductively from textual data, not from quantification."}}]});
